export const BANK = {"LANGUAGES":{"hinglish":"hi-IN","english":"en-IN","telugu":"te-IN","tamil":"ta-IN","kannada":"kn-IN","malayalam":"ml-IN","marathi":"mr-IN","bengali":"bn-IN","gujarati":"gu-IN","punjabi":"pa-IN"},"ANSWER_LANGS":["hinglish","english","telugu","tamil","kannada","malayalam"],"ALIASES":{"डू":"two","टू":"two","थ्री":"three","त्री":"three","सम":"sum","स्टॉक":"stock","शेयर":"share","पानी":"water","डुप्लिकेट":"duplicate","ज़ीरो":"zero","शून्य":"zero","सबएरे":"subarray","एनाग्राम":"anagram","प्रोडक्ट":"product","कंटेनर":"container","प्रॉफिट":"profit","खरीदें":"buy","बेचें":"sell","लिंक्ड":"linked","सॉर्ट":"sort","ट्री":"tree","ग्राफ":"graph","स्टैक":"stack","क्यू":"queue","हीप":"heap","सर्च":"search","रिवर्स":"reverse","उल्टा":"reverse","चक्र":"cycle","गहराई":"depth","సార్ట్":"sort","ట్రీ":"tree","గ్రాఫ్":"graph","స్టాక్":"stock","சார்ட்":"sort","ட்ரீ":"tree","கிராஃப்":"graph","ஸ்டாக்":"stock","ಸಾರ್ಟ್":"sort","ಟ್ರೀ":"tree","ಗ್ರಾಫ್":"graph","ಸ್ಟಾಕ್":"stock","സോർട്ട്":"sort","ട്രീ":"tree","ഗ്രാഫ്":"graph","സ്റ്റാക്ക്":"stack","టూ":"two","సమ్":"sum","షేర్":"share","டூ":"two","சம்":"sum","ஷேர்":"share","ಟೂ":"two","ಸಮ್":"sum","ಶೇರ್":"share","ടൂ":"two","സം":"sum","സ്റ്റോക്ക്":"stock","ഷെയർ":"share"},"TOPIC_META":{"Two Sum":["Arrays & Searching","Easy"],"3Sum":["Arrays & Searching","Medium"],"Container With Most Water":["Arrays & Searching","Medium"],"Best Time to Buy and Sell Stock":["Arrays & Searching","Easy"],"Product of Array Except Self":["Arrays & Searching","Medium"],"Longest Consecutive Sequence":["Arrays & Searching","Medium"],"Subarray Sum Equals K (Prefix Sum)":["Arrays & Searching","Medium"],"Remove Duplicates from Sorted Array":["Arrays & Searching","Easy"],"Move Zeroes":["Arrays & Searching","Easy"],"Longest Substring Without Repeating Characters":["Strings & Hashing","Medium"],"Valid Anagram":["Strings & Hashing","Easy"],"Sliding Window (generic)":["Arrays & Searching","Medium"]},"FALLBACKS":{"hinglish":"Ye topic abhi meri list mein nahi hai. Main arrays, strings, linked list, stack, trees, graphs, DP, sorting aur heap ke 40 topics samjha sakta hoon. Neeche topics browse karo ya search mein topic ka naam likho, main pattern ke saath samjha dunga.","english":"That topic is not in my list yet. I cover 40 topics across arrays, strings, linked lists, stacks, trees, graphs, dynamic programming, sorting, and heaps. Browse the topics below or type a topic name in search, and I will explain it with its pattern.","telugu":"ఆ topic నా list లో ఇంకా లేదు. Arrays, strings, linked list, stack, trees, graphs, DP, sorting, heap — మొత్తం 40 topics వివరించగలను. కింద topics చూడండి లేదా search లో topic పేరు రాయండి.","tamil":"அந்த topic என் list-ல் இன்னும் இல்லை. Arrays, strings, linked list, stack, trees, graphs, DP, sorting, heap — மொத்தம் 40 topics விளக்க முடியும். கீழே topics பாருங்கள் அல்லது search-ல் topic பெயரை எழுதுங்கள்.","kannada":"ಆ topic ನನ್ನ list ನಲ್ಲಿ ಇನ್ನೂ ಇಲ್ಲ. Arrays, strings, linked list, stack, trees, graphs, DP, sorting, heap — ಒಟ್ಟು 40 topics ವಿವರಿಸಬಹುದು. ಕೆಳಗೆ topics ನೋಡಿ ಅಥವಾ search ನಲ್ಲಿ topic ಹೆಸರು ಬರೆಯಿರಿ.","malayalam":"ആ topic എന്റെ list-ൽ ഇതുവരെ ഇല്ല. Arrays, strings, linked list, stack, trees, graphs, DP, sorting, heap — ആകെ 40 topics വിശദീകരിക്കാൻ കഴിയും. താഴെ topics നോക്കുക അല്ലെങ്കിൽ search-ൽ topic പേര് എഴുതുക."},"STOPWORDS_ANSWERS":["a","an","and","batao","explain","for","hai","how","in","is","ka","ke","ki","ko","kya","me","mein","my","of","on","or","please","samjha","samjhao","se","tell","the","to","what","why","with"],"FAMILY_GUIDES":[{"id":"linked_list","title":"Linked List patterns","keywords":["linked","link list","singly","doubly","head","node","pointer"],"answers":{"hinglish":"Linked list ke zyada problems teen patterns se bante hain: dummy node se head ke edge cases khatm karo, slow aur fast pointer se beech ya cycle dhoondho, aur teen pointers se links ulta karo. Is family mein main ye samjha sakta hoon: Reverse Linked List, Linked List Cycle, Merge Two Sorted Lists, aur Remove Nth Node From End. In mein se kisi ka naam bolo, main pattern ke saath samjha dunga.","english":"Most linked list problems use three patterns: a dummy node to remove head edge cases, slow and fast pointers to find the middle or a cycle, and three pointers to reverse links. In this family I can explain: Reverse Linked List, Linked List Cycle, Merge Two Sorted Lists, and Remove Nth Node From End. Name one of those and I will explain it with its pattern."}},{"id":"stack_queue","title":"Stack & Queue patterns","keywords":["stack","queue","deque","bracket","parenthesis","parentheses","monotonic","lifo","fifo"],"answers":{"hinglish":"Stack last in first out hota hai, queue first in first out. Stack tab use karo jab sabse recent cheez pehle chahiye, jaise brackets match karna ya pichhla bada element. Monotonic stack mein sirf useful elements rakho, bekaar ko pop kar do. Is family mein main ye samjha sakta hoon: Valid Parentheses, Min Stack, aur Next Greater Element. Kisi ka naam bolo.","english":"A stack is last in, first out; a queue is first in, first out. Use a stack when the most recent item is needed first, such as matching brackets or finding a previous greater element. A monotonic stack keeps only useful elements and pops the rest. In this family I can explain: Valid Parentheses, Min Stack, and Next Greater Element. Name one of those."}},{"id":"trees","title":"Tree patterns","keywords":["tree","bst","binary tree","traversal","ancestor","root","leaf","subtree","inorder","preorder","postorder"],"answers":{"hinglish":"Tree ke problems aksar recursion se bante hain: node par kuch karo, phir left aur right par wahi karo. BST mein ordering shortcut deti hai, left chhota, right bada. Traversal ka order badal do toh kaam badal jata hai. Is family mein main ye samjha sakta hoon: Binary Tree Traversals, Maximum Depth, Invert Binary Tree, Validate BST, aur Lowest Common Ancestor. Kisi ka naam bolo, main pattern ke saath samjha dunga.","english":"Tree problems usually use recursion: do something at the node, then recurse left and right. In a BST, ordering is the shortcut: left is smaller, right is larger. Changing the traversal order changes the job. In this family I can explain: Binary Tree Traversals, Maximum Depth, Invert Binary Tree, Validate BST, and Lowest Common Ancestor. Name one of those and I will explain it with its pattern."}},{"id":"graphs","title":"Graph patterns","keywords":["graph","bfs","dfs","dijkstra","shortest path","connected","adjacency","island","visited","topological","breadth","depth first"],"answers":{"hinglish":"Graph ke do main traversal hain: BFS queue se level by level chalta hai aur unweighted graph mein shortest path deta hai. DFS gehra jata hai aur cycle ya connected parts dhoondhne mein kaam aata hai. Dono mein visited set zaroori hai. Weighted graph mein shortest path ke liye Dijkstra chahiye, jo priority queue se chalta hai, BFS kaafi nahi hai. Is family mein main ye samjha sakta hoon: BFS, DFS, aur Number of Islands. Kisi ka naam bolo.","english":"Graphs have two main traversals: BFS uses a queue, runs level by level, and gives the shortest path in an unweighted graph. DFS goes deep and helps with cycles and connected parts. Both need a visited set. For weighted graphs, the shortest path needs Dijkstra's algorithm with a priority queue; BFS alone is not enough. In this family I can explain: BFS, DFS, and Number of Islands. Name one of those."}},{"id":"dp","title":"Dynamic Programming patterns","keywords":["dynamic programming","dp","memoization","memoisation","tabulation","knapsack","subsequence","optimal substructure","overlapping"],"answers":{"hinglish":"DP tab kaam aata hai jab wahi chhote subproblems baar baar aayein aur bada jawab chhote jawabon se bane. Pehle recurrence likho, phir base case, phir ya toh memo ke saath recursion ya table ke saath iteration. Is family mein main ye samjha sakta hoon: Climbing Stairs, House Robber, aur Coin Change. Kisi ka naam bolo, main recurrence ke saath samjha dunga.","english":"Dynamic programming helps when the same small subproblems repeat and the big answer is built from small ones. First write the recurrence, then the base case, then use recursion with memoisation or iteration with a table. In this family I can explain: Climbing Stairs, House Robber, and Coin Change. Name one of those and I will explain it with its recurrence."}},{"id":"sorting","title":"Sorting patterns","keywords":["sort","sorting","bubble","insertion","selection","heap sort","quicksort","mergesort","quick sort","merge sort"],"answers":{"hinglish":"Sorting ke main patterns: divide and conquer, jaise quick sort aur merge sort, aur simple insertion style, jaise bubble aur insertion sort. Quick sort average mein tez aur in place hota hai, merge sort hamesha O of n log n deta hai aur stable hota hai. Is family mein main ye samjha sakta hoon: Quick Sort, Merge Sort, aur Binary Search. Kisi ka naam bolo.","english":"Sorting has two main families: divide and conquer, such as quick sort and merge sort, and simple insertion-style sorts, such as bubble and insertion sort. Quick sort is fast on average and in place; merge sort is always O of n log n and stable. In this family I can explain: Quick Sort, Merge Sort, and Binary Search. Name one of those."}},{"id":"heap","title":"Heap patterns","keywords":["heap","priority queue","kth","top k","largest","smallest"],"answers":{"hinglish":"Heap tab use karo jab baar baar sabse bada ya sabse chhota element chahiye. Top k largest ke liye min-heap rakho, top k smallest ke liye max-heap. Heap ka top hamesha jawab hota hai, baaki order matter nahi karta. Is family mein main ye samjha sakta hoon: Kth Largest Element aur Top K Frequent Elements. Kisi ka naam bolo.","english":"Use a heap when you repeatedly need the largest or smallest element. For the top k largest, keep a min-heap; for the top k smallest, keep a max-heap. The heap top is always the answer; the rest of the order does not matter. In this family I can explain: Kth Largest Element and Top K Frequent Elements. Name one of those."}},{"id":"arrays","title":"Array patterns","keywords":["array","subarray","prefix","two pointer","sliding window","binary search","kadane"],"answers":{"hinglish":"Array ke main patterns: two pointers, sliding window, prefix sum, aur hash map. Sorted array ho toh two pointers ya binary search socho. Subarray sum ho toh prefix sum, aur window wale sawal mein sliding window. Is family mein main Two Sum, Sliding Window, Prefix Sum, Binary Search, aur Maximum Subarray samjha sakta hoon. Kisi ka naam bolo.","english":"Array problems mostly use four patterns: two pointers, sliding window, prefix sums, and hash maps. A sorted array suggests two pointers or binary search; subarray sums suggest prefix sums; window questions suggest sliding window. In this family I can explain Two Sum, Sliding Window, Prefix Sum, Binary Search, and Maximum Subarray. Name one of those."}},{"id":"strings","title":"String patterns","keywords":["string","substring","palindrome","anagram","character","char"],"answers":{"hinglish":"String ke main patterns: two pointers, hash map se counting, aur centre se expand karna. Anagram ho toh letter count socho, palindrome ho toh centre se expand karo, bina repeat ke longest ho toh sliding window. Is family mein main Valid Anagram, Group Anagrams, Longest Palindromic Substring, aur Longest Substring samjha sakta hoon. Kisi ka naam bolo.","english":"String problems mostly use three patterns: two pointers, hash-map counting, and expanding around a centre. Anagrams suggest letter counts, palindromes suggest expanding around a centre, and longest-without-repeat suggests sliding window. In this family I can explain Valid Anagram, Group Anagrams, Longest Palindromic Substring, and Longest Substring. Name one of those."}},{"id":"recursion_backtracking","title":"Recursion & Backtracking patterns","keywords":["recursion","recursive","backtrack","backtracking","subset","subsets","permutation","combination","n-queens","n queens","choose"],"answers":{"hinglish":"Backtracking ka pattern hai choose, explore, unchoose. Ek choice lo, aage badho, phir choice wapas lo aur doosri choice try karo. Base case batata hai kab rukna hai, aur visited ya used tracking dobara wahi choice rokta hai. Subsets, permutations, aur N-Queens isi pattern se bante hain. Tree aur recursion ke liye Binary Tree Traversals ya Reverse Linked List poochho.","english":"Backtracking follows choose, explore, unchoose. Make a choice, go deeper, undo the choice, and try the next one. The base case says when to stop, and visited tracking stops repeats. Subsets, permutations, and N-Queens all follow this pattern. For tree and recursion basics, ask about Binary Tree Traversals or Reverse Linked List."}}],"FAMILY_CATEGORIES":{"linked_list":"Linked List","stack_queue":"Stack & Queue","trees":"Trees","graphs":"Graphs","dp":"Dynamic Programming","sorting":"Sorting","heap":"Heap","arrays":"Arrays & Searching","strings":"Strings & Hashing","recursion_backtracking":"Trees"},"POPULAR":["Two Sum","Binary Search","Reverse Linked List","Valid Parentheses","Binary Tree Traversals","Breadth-First Search (BFS)","Climbing Stairs","Quick Sort"],"ANSWERS":[{"topic":"Two Sum","keywords":["two sum","2 sum","to sum","do sum","टू सम","do number ka sum","pair sum","target sum","టూ సమ్","டூ சம்","ಟೂ ಸಮ್","ടൂ സം"],"answers":{"hinglish":"Pattern hai hash map. Array ko ek baar scan karo, aur har number ke liye check karo ki uska partner, matlab target minus current number, pehle aa chuka hai ya nahi. Mila toh dono index mil gaye. Ye kaam isliye karta hai kyunki hum purane numbers ko yaad rakhte hain, dobara dhoondhne ki zaroorat nahi padti. Time hai O of n, space bhi O of n. Trade-off ye hai: brute force O of n square hota hai, yahan hum thodi memory deke speed lete hain. Interview mein ye trade-off bolna important hai.","english":"The pattern is a hash map. Scan the array once, and for each number check whether its partner — target minus the current number — has already been seen. If yes, you have both indices. It works because you remember past numbers instead of searching for them again. Time is O of n, space is O of n. The trade-off: brute force takes O of n square; here you spend a little memory to buy speed, and you should say that trade-off out loud in the interview.","telugu":"Pattern: hash map. Array ని ఒక్కసారి scan చేయండి. ప్రతి number కి, target minus ఆ number — ఆ partner ముందు వచ్చిందా అని check చేయండి. వస్తే రెండు indices దొరికాయి. ఎందుకంటే పాత numbers ని గుర్తు పెట్టుకుంటాం, మళ్ళీ వెతకాల్సిన అవసరం లేదు. Time complexity O(n), space O(n). Brute force O(n square) కన్నా ఇది fast; కొంచెం memory ఎక్కువ వాడతాం — interview లో ఈ trade-off చెప్పాలి.","tamil":"Pattern: hash map. Array-ஐ ஒரு முறை scan செய்யுங்கள். ஒவ்வொரு number-க்கும், target minus அந்த number — அந்த partner முன்பு வந்ததா என்று check செய்யுங்கள். வந்திருந்தால் இரண்டு indices கிடைத்துவிடும். பழைய numbers-ஐ நினைவில் வைப்பதால் இது வேலை செய்கிறது. Time complexity O(n), space O(n). Brute force O(n square)-ஐ விட இது fast; கொஞ்சம் memory அதிகம் — interview-ல் இந்த trade-off சொல்ல வேண்டும்.","kannada":"Pattern: hash map. Array ಅನ್ನು ಒಂದು ಬಾರಿ scan ಮಾಡಿ. ಪ್ರತಿ number ಗೆ, target minus ಆ number — ಆ partner ಮೊದಲು ಬಂದಿದೆಯೇ ಎಂದು check ಮಾಡಿ. ಬಂದಿದ್ದರೆ ಎರಡು indices ಸಿಕ್ಕಿತು. ಹಳೆಯ numbers ಅನ್ನು ನೆನಪಿಡುವುದರಿಂದ ಇದು ಕೆಲಸ ಮಾಡುತ್ತದೆ. Time complexity O(n), space O(n). Brute force O(n square) ಕ್ಕಿಂತ ಇದು fast; ಸ್ವಲ್ಪ memory ಹೆಚ್ಚು — interview ನಲ್ಲಿ ಈ trade-off ಹೇಳಬೇಕು.","malayalam":"Pattern: hash map. Array ഒരിക്കൽ scan ചെയ്യുക. ഓരോ number-നും, target minus ആ number — ആ partner നേരത്തെ വന്നിട്ടുണ്ടോ എന്ന് check ചെയ്യുക. ഉണ്ടെങ്കിൽ രണ്ട് indices കിട്ടി. പഴയ numbers ഓർത്തുവെക്കുന്നതുകൊണ്ടാണ് ഇത് work ചെയ്യുന്നത്. Time complexity O(n), space O(n). Brute force O(n square)-നേക്കാൾ ഇത് fast ആണ്; കുറച്ച് memory കൂടുതൽ — interview-ൽ ഈ trade-off പറയണം."},"simple":{"hinglish":"Simple mein: har number ke saath uska partner dhoondho. Partner pehle mila hai toh jawab mil gaya. Partner ko yaad rakhne ke liye hash map use hota hai.","english":"Simply: for every number, look for its partner that completes the target. A hash map remembers the numbers you have already seen, so each lookup is instant."},"example":"Example: array hai 2, 7, 11, 15 aur target 9. 2 ke liye partner 7 chahiye, abhi nahi mila. Phir 7 aaya, uska partner 2 pehle se map mein hai. Answer: index 0 aur 1."},{"topic":"3Sum","keywords":["3sum","3 sum","three sum","थ्री सम","teen number","triplet","త్రీ సమ్","த்ரீ சம்","ತ್ರೀ ಸಮ್","ത്രീ സം"],"answers":{"hinglish":"Pattern hai sort karke two pointers. Pehle array sort karo, phir ek number fix karo, aur baaki do ko left aur right pointer se dhoondho. Sum chhota hai toh left badhao, bada hai toh right ghatao. Sorting ki wajah se pointers ek hi direction mein chalte hain, isliye har fixed number ke liye linear scan kaafi hai. Time hai O of n square, space O of 1 extra. Trade-off: duplicates skip karna bhoolna sabse common galti hai, aur bina sort kiye two pointer chalega hi nahi.","english":"The pattern is sort plus two pointers. Sort the array, fix one number, then hunt the other two with a left and a right pointer. Sum too small, move left up; too big, move right down. Sorting lets both pointers move in one direction only, so each fixed number costs a linear scan. Time is O of n square, extra space O of 1. The common trap is forgetting to skip duplicates — and two pointers simply do not work on an unsorted array.","telugu":"Pattern: ముందు array sort చేయండి, తర్వాత two pointers. ఒక number fix చేసి, మిగilin రెండు numbers ని left, right pointers తో వెతకండి. Sum చిన్నదైతే left పెంచండి, పెద్దదైతే right తగ్గించండి. Time complexity O(n square). Duplicates skip చేయడం మర్చిపోవడం common mistake.","tamil":"Pattern: முதலில் array-ஐ sort செய்யுங்கள், பிறகு two pointers. ஒரு number-ஐ fix செய்து, மீதமுள்ள இரண்டையும் left, right pointers கொண்டு தேடுங்கள். Sum சிறியதாக இருந்தால் left-ஐ நகர்த்தவும், பெரியதாக இருந்தால் right-ஐ நகர்த்தவும். Time complexity O(n square). Duplicates-ஐ skip செய்ய மறப்பது common mistake.","kannada":"Pattern: ಮೊದಲು array ಅನ್ನು sort ಮಾಡಿ, ನಂತರ two pointers. ಒಂದು number ಅನ್ನು fix ಮಾಡಿ, ಉಳಿದ ಎರಡನ್ನು left, right pointers ನಿಂದ ಹುಡುಕಿ. Sum ಚಿಕ್ಕದಾದರೆ left ಹೆಚ್ಚಿಸಿ, ದೊಡ್ಡದಾದರೆ right ಕಡಿಮೆ ಮಾಡಿ. Time complexity O(n square). Duplicates skip ಮಾಡಲು ಮರೆಯುವುದು common mistake.","malayalam":"Pattern: ആദ്യം array sort ചെയ്യുക, പിന്നെ two pointers. ഒരു number fix ചെയ്ത്, ബാക്കി രണ്ടിനെ left, right pointers വെച്ച് തിരയുക. Sum ചെറുതാണെങ്കിൽ left കൂട്ടുക, വലുതാണെങ്കിൽ right കുറയ്ക്കുക. Time complexity O(n square). Duplicates skip ചെയ്യാൻ മറക്കുന്നത് common mistake ആണ്."},"simple":{"hinglish":"Simple mein: array sort karo, ek number pakdo, aur baaki do ko dono ends se beech ki taraf laakar dhoondho.","english":"Simply: sort the array, hold one number fixed, and close in on the other two from both ends."},"example":"Example: array hai minus 1, 0, 1, 2, minus 1, minus 4. Sorted karke fix karo minus 1, pointers se 1 aur 0 milte hain — triplet: minus 1, 0, 1, sum zero."},{"topic":"Container With Most Water","keywords":["container","most water","पानी","paani","max water","max area","കണ്ടെയ്നർ","கன்டெய்னர்","కంటైనర్","ಕಂಟೈನರ್"],"answers":{"hinglish":"Pattern hai two pointers, dono ends se. Area hota hai chhoti height guna width. Har step par chhoti wali side ko andar move karo, kyunki badi side ko move karne se area kabhi badh nahi sakta, width toh ghat hi rahi hai. Ye greedy move isliye sahi hai kyunki chhoti height hi area ki limit hai. Time hai O of n, space O of 1. Trade-off: ye sirf tab kaam karta hai jab do ends ke beech ka area chahiye, har pair check karne ki zaroorat nahi.","english":"The pattern is two pointers from both ends. Area is the shorter height times the width. Each step, move the shorter side inward: moving the taller side can never help, because the width only shrinks and the short side caps the area anyway. Time is O of n, space O of 1. The trade-off: this greedy shortcut only works because the area is defined by the two ends — you never need to check every pair.","telugu":"Pattern: two pointers, రెండు చివర్ల నుంచి. Area అంటే చిన్న height into width. ప్రతి step లో చిన్న side ని లోపలికి move చేయండి — పెద్ద side move చేస్తే area పెరగదు, ఎందుకంటే width తగ్గుతుంది. Time complexity O(n), space O(1).","tamil":"Pattern: two pointers, இரண்டு முனைகளிலிருந்தும். Area என்பது சிறிய height பெருக்கல் width. ஒவ்வொரு step-லும் சிறிய side-ஐ உள்ளே நகர்த்துங்கள் — பெரிய side-ஐ நகர்த்தினால் area கூடாது, width குறைந்து கொண்டே போகும். Time complexity O(n), space O(1).","kannada":"Pattern: two pointers, ಎರಡು ತುದಿಗಳಿಂದ. Area ಎಂದರೆ ಚಿಕ್ಕ height ಗುಣಿಸಿದ width. ಪ್ರತಿ step ನಲ್ಲಿ ಚಿಕ್ಕ side ಅನ್ನು ಒಳಗೆ move ಮಾಡಿ — ದೊಡ್ಡ side move ಮಾಡಿದರೆ area ಹೆಚ್ಚಾಗುವುದಿಲ್ಲ, width ಕಡಿಮೆಯಾಗುತ್ತಲೇ ಇರುತ್ತದೆ. Time complexity O(n), space O(1).","malayalam":"Pattern: two pointers, രണ്ട് അറ്റത്തുനിന്നും. Area എന്നാൽ ചെറിയ height ഗുണം width. ഓരോ step-ലും ചെറിയ side അകത്തേക്ക് move ചെയ്യുക — വലിയ side move ചെയ്താൽ area കൂടില്ല, width കുറഞ്ഞുകൊണ്ടിരിക്കും. Time complexity O(n), space O(1)."},"simple":{"hinglish":"Simple mein: dono kinare se shuru karo, jo side chhoti hai use andar lao. Chhoti side hi paani ki limit hai.","english":"Simply: start from both edges and keep moving the shorter wall inward — the short wall is what limits the water."},"example":"Example: heights hai 1, 8, 6, 2, 5, 4, 8, 3, 7. Ends par 1 aur 7: area 7. Chhoti side 1 ko hatao, phir 8 aur 7 milte hain: area 49. Yahi maximum hai."},{"topic":"Best Time to Buy and Sell Stock","keywords":["stock","स्टॉक","share","शेयर","kharid","bech","profit","buy and sell","షేర్","ஷேர்","ಶೇರ್","ഷെയർ","స్టాక్","ஸ்டாக்","ಸ್ಟಾಕ್","സ്റ്റോക്ക്"],"answers":{"hinglish":"Pattern hai ek hi scan mein minimum price yaad rakhna. Jaise jaise aage badho, ab tak ka sabse sasta price maintain karo, aur har din check karo ki aaj bechne par kitna profit hoga. Ye isliye kaam karta hai kyunki best deal hamesha kisi purane minimum ke against hi banti hai. Time hai O of n, space O of 1. Trade-off: ye sirf ek transaction ke liye hai. Do transactions ya fee wala version aaye toh DP lagega.","english":"The pattern is one scan while remembering the minimum price so far. Keep updating the cheapest price seen, and at each day ask: if I sold today, what is my profit? It works because the best deal is always measured against some earlier minimum. Time is O of n, space O of 1. The trade-off: this solves a single transaction; two transactions or a fee turns it into a DP problem.","telugu":"Pattern: ఒకే scan లో minimum price గుర్తుంచుకోవడం. ఇప్పటివరకు చూసిన అత్యంత చౌక price ని maintain చేయండి, ప్రతి రోజు — ఈ రోజు అమ్మితే ఎంత profit? అని check చేయండి. Time complexity O(n), space O(1). ఇది ఒకే transaction కోసం; రెండు transactions అంటే DP వాడాలి.","tamil":"Pattern: ஒரே scan-ல் minimum price-ஐ நினைவில் வைப்பது. இதுவரை பார்த்த மிகக் குறைந்த price-ஐ maintain செய்யுங்கள், ஒவ்வொரு நாளும் — இன்று விற்றால் எவ்வளவு profit? என்று check செய்யுங்கள். Time complexity O(n), space O(1). இது ஒரே transaction-க்கு; இரண்டு transactions என்றால் DP வேண்டும்.","kannada":"Pattern: ಒಂದೇ scan ನಲ್ಲಿ minimum price ಅನ್ನು ನೆನಪಿಡುವುದು. ಇದುವರೆಗೆ ನೋಡಿದ ಅತ್ಯಂತ ಅಗ್ಗದ price ಅನ್ನು maintain ಮಾಡಿ, ಪ್ರತಿ ದಿನ — ಇಂದು ಮಾರಿದರೆ ಎಷ್ಟು profit? ಎಂದು check ಮಾಡಿ. Time complexity O(n), space O(1). ಇದು ಒಂದು transaction ಗೆ ಮಾತ್ರ; ಎರಡು transactions ಆದರೆ DP ಬೇಕು.","malayalam":"Pattern: ഒരൊറ്റ scan-ൽ minimum price ഓർത്തുവെക്കുക. ഇതുവരെ കണ്ട ഏറ്റവും കുറഞ്ഞ price maintain ചെയ്യുക, ഓരോ ദിവസവും — ഇന്ന് വിറ്റാൽ എത്ര profit? എന്ന് check ചെയ്യുക. Time complexity O(n), space O(1). ഇത് ഒരു transaction-ന് മാത്രം; രണ്ട് transactions ആണെങ്കിൽ DP വേണം."},"simple":{"hinglish":"Simple mein: sabse sasta din yaad rakho, aur har din usi se bechne ka profit check karo. Sabse bada profit hi jawab hai.","english":"Simply: remember the cheapest day so far, and check the selling profit against it every day. The biggest profit wins."},"example":"Example: prices hai 7, 1, 5, 3, 6, 4. Sabse sasta 1 hai. Uske baad 6 par becho toh profit 5. Yahi maximum hai."},{"topic":"Product of Array Except Self","keywords":["product except self","except self","guna","गुणा","product of array","ప్రోడక్ట్","ப்ராடக்ட்","ಪ್ರಾಡಕ್ಟ್","പ്രോഡക്റ്റ്"],"answers":{"hinglish":"Pattern hai prefix aur suffix product. Har index ke liye left side ka total product aur right side ka total product alag se rakho, phir answer hai dono ka guna. Division bilkul use nahi karna, kyunki zero aate hi division fail ho jayega. Pehle left products result array mein bharo, phir right se ulta scan karke multiply kar do. Time hai O of n, aur extra space O of 1 kyunki result array count nahi hota. Trade-off: do pass lagte hain, lekin division wale shortcut se zyada safe hai.","english":"The pattern is prefix and suffix products. For each index you need the product of everything on its left times everything on its right. Never use division — a single zero breaks it. Fill the result with left products in one pass, then scan from the right multiplying in the right products. Time is O of n, extra space O of 1 since the result array does not count. The trade-off: two passes, but far safer than the division shortcut.","telugu":"Pattern: prefix మరియు suffix products. ప్రతి index కి, ఎడమ వైపు మొత్తం product మరియు కుడి వైపు మొత్తం product కలపండి. Division అస్సలు వాడొద్దు — zero వస్తే fail అవుతుంది. Time complexity O(n), extra space O(1).","tamil":"Pattern: prefix மற்றும் suffix products. ஒவ்வொரு index-க்கும், இடது பக்க மொத்த product மற்றும் வலது பக்க மொத்த product-ஐ பெருக்குங்கள். Division பயன்படுத்தவே கூடாது — zero வந்தால் fail ஆகும். Time complexity O(n), extra space O(1).","kannada":"Pattern: prefix ಮತ್ತು suffix products. ಪ್ರತಿ index ಗೆ, ಎಡಭಾಗದ ಒಟ್ಟು product ಮತ್ತು ಬಲಭಾಗದ ಒಟ್ಟು product ಅನ್ನು ಗುಣಿಸಿ. Division ಬಳಸಲೇಬೇಡಿ — zero ಬಂದರೆ fail ಆಗುತ್ತದೆ. Time complexity O(n), extra space O(1).","malayalam":"Pattern: prefix-ഉം suffix products-ഉം. ഓരോ index-നും, ഇടതുവശത്തെ ആകെ product-ഉം വലതുവശത്തെ ആകെ product-ഉം ഗുണിക്കുക. Division ഉപയോഗിക്കരുത് — zero വന്നാൽ fail ആകും. Time complexity O(n), extra space O(1)."},"simple":{"hinglish":"Simple mein: har number ke liye baayein ka guna aur daayein ka guna multiply kar do. Division kabhi nahi.","english":"Simply: for each position, multiply the product of everything on its left by the product of everything on its right. No division, ever."},"example":"Example: array hai 1, 2, 3, 4. Index 1 par value 2 hai: left product 1, right product 3 guna 4 matlab 12. Answer wahan 12. Poora answer: 24, 12, 8, 6."},{"topic":"Longest Consecutive Sequence","keywords":["consecutive","lagatar","लगातार","sequence","longest consecutive"],"answers":{"hinglish":"Pattern hai hash set. Saare numbers set mein daal do. Phir sirf un numbers se sequence shuru karo jinka pichla number set mein nahi hai, matlab jo sequence ka start ho sakte hain. Wahan se aage count karo. Har number sirf ek baar sequence ke andar visit hota hai, isliye total time O of n hai, sorting wale O of n log n se better. Space hai O of n set ke liye. Trade-off: memory zyada lagti hai, lekin interview mein O of n solution hi expected hota hai.","english":"The pattern is a hash set. Put all numbers in a set, then only start counting a sequence from a number whose predecessor is not in the set — a true sequence start. Each number is visited once inside a sequence, so total time is O of n, beating the O of n log n sort. Space is O of n for the set. The trade-off: more memory, but O of n is what the interview expects.","telugu":"Pattern: hash set. అన్ని numbers ని set లో వేయండి. తర్వాత, ముందు number set లో లేని numbers నుంచి మాత్రమే sequence ప్రారంభించండి — అవే నిజమైన starts. ప్రతి number ఒక్కసారే visit అవుతుంది కాబట్టి time O(n). Space O(n).","tamil":"Pattern: hash set. எல்லா numbers-ஐயும் set-ல் போடுங்கள். பிறகு, முந்தைய number set-ல் இல்லாத numbers-லிருந்து மட்டுமே sequence தொடங்குங்கள் — அவைதான் உண்மையான starts. ஒவ்வொரு number-ம் ஒருமுறை மட்டுமே visit ஆவதால் time O(n). Space O(n).","kannada":"Pattern: hash set. ಎಲ್ಲಾ numbers ಅನ್ನು set ನಲ್ಲಿ ಹಾಕಿ. ನಂತರ, ಹಿಂದಿನ number set ನಲ್ಲಿ ಇಲ್ಲದ numbers ನಿಂದ ಮಾತ್ರ sequence ಆರಂಭಿಸಿ — ಅವೇ ನಿಜವಾದ starts. ಪ್ರತಿಯೊಂದು number ಒಮ್ಮೆ ಮಾತ್ರ visit ಆಗುವುದರಿಂದ time O(n). Space O(n).","malayalam":"Pattern: hash set. എല്ലാ numbers-ഉം set-ൽ ഇടുക. പിന്നെ, മുൻപത്തെ number set-ൽ ഇല്ലാത്ത numbers-ൽ നിന്ന് മാത്രം sequence തുടങ്ങുക — അവയാണ് യഥാർത്ഥ starts. ഓരോ number-ഉം ഒരിക്കൽ മാത്രം visit ചെയ്യുന്നതുകൊണ്ട് time O(n). Space O(n)."},"simple":{"hinglish":"Simple mein: saare numbers ko set mein rakho, aur sirf wahan se ginti shuru karo jahan se nayi chain banti hai.","english":"Simply: keep all numbers in a set, and only start counting where a new chain begins."},"example":"Example: numbers hai 100, 4, 200, 1, 3, 2. Chain 1, 2, 3, 4 banti hai — length 4. Yahi longest hai."},{"topic":"Subarray Sum Equals K (Prefix Sum)","keywords":["prefix sum","subarray sum","subarray","सबएरे","sum equals k","sum barabar k","సబ్అరే","சப்அரே","ಸಬ್ಅರೇ","സബ്അറേ"],"answers":{"hinglish":"Pattern hai prefix sum ke saath hash map. Chalte chalte cumulative sum rakho. Agar current prefix sum minus k pehle kahin aa chuka hai, toh beech wala subarray ka sum exactly k hai. Map mein har prefix sum kitni baar aaya, ye count rakho, aur zero prefix sum ko count ek se shuru karo. Time hai O of n, space O of n. Trade-off: negative numbers hon toh sliding window fail ho jata hai, isiliye yahan hash map wala tareeka hi sahi hai.","english":"The pattern is prefix sum with a hash map. Keep a running cumulative sum. If the current prefix sum minus k has appeared before, the subarray between those points sums to exactly k. Store how many times each prefix sum occurred, starting with zero seen once. Time is O of n, space O of n. The trade-off: with negative numbers, sliding window breaks — the hash map is the right tool here.","telugu":"Pattern: prefix sum మరియు hash map. నడుస్తూ cumulative sum ఉంచండి. Current prefix sum minus k ముందు వచ్చి ఉంటే, మధ్యలో ఉన్న subarray sum exactly k. Time complexity O(n), space O(n). Negative numbers ఉంటే sliding window పనిచేయదు — అందుకే hash map వాడాలి.","tamil":"Pattern: prefix sum உடன் hash map. ஓடிக்கொண்டே cumulative sum வைத்திருங்கள். Current prefix sum minus k முன்பு வந்திருந்தால், நடுவில் உள்ள subarray sum சரியாக k. Time complexity O(n), space O(n). Negative numbers இருந்தால் sliding window வேலை செய்யாது — அதனால் hash map தான் சரி.","kannada":"Pattern: prefix sum ಜೊತೆಗೆ hash map. ಓಡುತ್ತಾ cumulative sum ಇಟ್ಟುಕೊಳ್ಳಿ. Current prefix sum minus k ಮೊದಲು ಬಂದಿದ್ದರೆ, ಮಧ್ಯದ subarray sum ನಿಖರವಾಗಿ k. Time complexity O(n), space O(n). Negative numbers ಇದ್ದರೆ sliding window ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ — ಹಾಗಾಗಿ hash map ಸರಿ.","malayalam":"Pattern: prefix sum-ഉം hash map-ഉം. ഓടിക്കൊണ്ട് cumulative sum സൂക്ഷിക്കുക. Current prefix sum minus k നേരത്തെ വന്നിട്ടുണ്ടെങ്കിൽ, ഇടയിലുള്ള subarray sum കൃത്യമായി k. Time complexity O(n), space O(n). Negative numbers ഉണ്ടെങ്കിൽ sliding window work ചെയ്യില്ല — അതുകൊണ്ട് hash map ആണ് ശരി."},"simple":{"hinglish":"Simple mein: chalta hua total rakho. Agar total minus k pehle dikha tha, toh beech ka hissa hi jawab hai.","english":"Simply: keep a running total. If total minus k was seen before, the stretch in between is your answer."},"example":"Example: array hai 1, 1, 1 aur k hai 2. Prefix sums: 0, 1, 2, 3. Prefix 0 ke baad 2 aaya — ek subarray. Phir 1 ke baad 3 — dusra. Total 2 subarrays."},{"topic":"Remove Duplicates from Sorted Array","keywords":["remove duplicate","duplicate hatao","डुप्लिकेट","duplicates","డూప్లికేట్","டூப்ளிகேட்","ಡೂಪ್ಲಿಕೇಟ್","ഡ്യൂപ്ലിക്കേറ്റ്"],"answers":{"hinglish":"Pattern hai two pointers, ek read pointer aur ek write pointer. Array sorted hai, isliye duplicates hamesha saath saath aayenge. Read pointer sab ko scan karta hai, aur jab naya value mile tabhi write pointer aage badhta hai aur value wahan likhi jaati hai. Time hai O of n, space O of 1, aur koi extra array nahi banta. Trade-off: ye sirf sorted array par kaam karta hai, unsorted mein set ya map lagega.","english":"The pattern is two pointers: a read pointer and a write pointer. Because the array is sorted, duplicates always sit together. The read pointer scans everything; the write pointer advances only when a new value appears, and writes it there. Time is O of n, space O of 1, no extra array. The trade-off: this only works when sorted — unsorted input needs a set or a map.","telugu":"Pattern: two pointers — ఒక read pointer, ఒక write pointer. Array sorted కాబట్టి duplicates ఎప్పుడూ పక్కపక్కనే ఉంటాయి. కొత్త value వచ్చినప్పుడే write pointer ముందుకు వెళ్తుంది. Time complexity O(n), space O(1). ఇది sorted array పైన మాత్రమే పనిచేస్తుంది.","tamil":"Pattern: two pointers — ஒரு read pointer, ஒரு write pointer. Array sorted என்பதால் duplicates எப்போதும் அருகருகே இருக்கும். புதிய value வரும்போது மட்டுமே write pointer முன்னேறும். Time complexity O(n), space O(1). இது sorted array-ல் மட்டுமே வேலை செய்யும்.","kannada":"Pattern: two pointers — ಒಂದು read pointer, ಒಂದು write pointer. Array sorted ಆಗಿರುವುದರಿಂದ duplicates ಯಾವಾಗಲೂ ಪಕ್ಕಪಕ್ಕದಲ್ಲೇ ಇರುತ್ತವೆ. ಹೊಸ value ಬಂದಾಗ ಮಾತ್ರ write pointer ಮುಂದೆ ಹೋಗುತ್ತದೆ. Time complexity O(n), space O(1). ಇದು sorted array ನಲ್ಲಿ ಮಾತ್ರ ಕೆಲಸ ಮಾಡುತ್ತದೆ.","malayalam":"Pattern: two pointers — ഒരു read pointer, ഒരു write pointer. Array sorted ആയതുകൊണ്ട് duplicates എപ്പോഴും അടുത്തടുത്ത് ഇരിക്കും. പുതിയ value വരുമ്പോൾ മാത്രമേ write pointer മുന്നോട്ട് പോകൂ. Time complexity O(n), space O(1). ഇത് sorted array-ൽ മാത്രമേ work ചെയ്യൂ."},"simple":{"hinglish":"Simple mein: ek pointer padhta hai, dusra sirf naye numbers likhta hai. Duplicates apne aap peeche reh jaate hain.","english":"Simply: one pointer reads everything, the other writes only new values. Duplicates get left behind automatically."},"example":"Example: array hai 1, 1, 2, 2, 3. Read pointer chalta hai, write pointer sirf 1, 2, 3 likhta hai. Pehle 3 positions hi jawab hain."},{"topic":"Move Zeroes","keywords":["move zero","zeroes","zero","ज़ीरो","शून्य","end mein zero","జీరో","ஜீரோ","ಜೀರೋ","സീറോ"],"answers":{"hinglish":"Pattern hai two pointers, bilkul remove duplicates jaisa. Ek write pointer rakho. Jo number zero nahi hai, use write pointer wali jagah par le aao aur pointer badhao. Aakhir mein bachi hui jagah zero se bhar do. Order bhi maintain rehta hai aur extra space bhi nahi lagta. Time hai O of n, space O of 1. Trade-off: swaps zyada ho sakte hain, lekin in-place solution ke liye ye standard hai.","english":"The pattern is two pointers, the same family as remove duplicates. Keep a write pointer. Whenever a non-zero number appears, move it to the write position and advance. At the end, fill the remaining spots with zeroes. Order is preserved and no extra space is used. Time is O of n, space O of 1. The trade-off: there can be many swaps, but this is the standard in-place solution.","telugu":"Pattern: two pointers. ఒక write pointer ఉంచండి. Zero కాని number వచ్చినప్పుడల్లా దాన్ని write position కి తీసుకురండి. చివర్లో మిగిలిన చోట్ల zeroes నింపండి. Order maintain అవుతుంది, extra space లేదు. Time complexity O(n), space O(1).","tamil":"Pattern: two pointers. ஒரு write pointer வைத்திருங்கள். Zero அல்லாத number வரும்போதெல்லாம் அதை write position-க்கு கொண்டு வாருங்கள். கடைசியில் மீதமுள்ள இடங்களில் zeroes நிரப்புங்கள். Order maintain ஆகும், extra space இல்லை. Time complexity O(n), space O(1).","kannada":"Pattern: two pointers. ಒಂದು write pointer ಇಟ್ಟುಕೊಳ್ಳಿ. Zero ಅಲ್ಲದ number ಬಂದಾಗಲೆಲ್ಲಾ ಅದನ್ನು write position ಗೆ ತನ್ನಿ. ಕೊನೆಯಲ್ಲಿ ಉಳಿದ ಜಾಗಗಳಲ್ಲಿ zeroes ತುಂಬಿ. Order maintain ಆಗುತ್ತದೆ, extra space ಇಲ್ಲ. Time complexity O(n), space O(1).","malayalam":"Pattern: two pointers. ഒരു write pointer വെക്കുക. Zero അല്ലാത്ത number വരുമ്പോഴെല്ലാം അതിനെ write position-ലേക്ക് കൊണ്ടുവരിക. അവസാനം ബാക്കിയുള്ള സ്ഥലങ്ങളിൽ zeroes നിറയ്ക്കുക. Order maintain ചെയ്യും, extra space ഇല്ല. Time complexity O(n), space O(1)."},"simple":{"hinglish":"Simple mein: zero wale numbers ko peeche dhakel do — pehle saare non-zero aage, phir saare zero peeche.","english":"Simply: push all non-zero numbers to the front in order, then fill the back with zeroes."},"example":"Example: array hai 0, 1, 0, 3, 12. Non-zero numbers aage: 1, 3, 12. Peeche zero bhar do: 1, 3, 12, 0, 0."},{"topic":"Longest Substring Without Repeating Characters","keywords":["substring","repeat","bina repeat","longest substring","sliding window substring","సబ్‌స్ట్రింగ్","சப்ஸ்ட்ரிங்","ಸಬ್‌ಸ್ಟ್ರಿಂಗ್","സബ്സ്ട്രിംഗ്"],"answers":{"hinglish":"Pattern hai sliding window ke saath last index ka map. Right pointer window badhata hai. Jaise hi koi character repeat ho, left pointer ko us character ke pichle index se ek aage le jao. Window ke andar kabhi duplicate nahi rehta, isliye har window valid hoti hai aur sabse lambi hi answer hai. Time hai O of n, space characters ke set ke size ke barabar. Trade-off: left pointer kabhi peeche nahi jaata, yahi is pattern ki pehchan hai.","english":"The pattern is a sliding window with a last-seen index map. The right pointer grows the window. The moment a character repeats, jump the left pointer to just after that character's previous position. The window never holds a duplicate, so every window is valid and the longest one is the answer. Time is O of n; space is the size of the character set. The key insight: the left pointer never moves backwards.","telugu":"Pattern: sliding window మరియు last index map. Right pointer window ని పెంచుతుంది. ఏ character అయినా repeat అయితే, left pointer ని ఆ character మునుపటి position తర్వాతకి జరపండి. Window లో duplicate ఎప్పుడూ ఉండదు. Time complexity O(n).","tamil":"Pattern: sliding window உடன் last index map. Right pointer window-ஐ வளர்க்கும். ஏதாவது character repeat ஆனவுடன், left pointer-ஐ அந்த character-ன் முந்தைய position-க்கு அடுத்ததாக நகர்த்துங்கள். Window-க்குள் duplicate எப்போதும் இருக்காது. Time complexity O(n).","kannada":"Pattern: sliding window ಜೊತೆಗೆ last index map. Right pointer window ಅನ್ನು ಬೆಳೆಸುತ್ತದೆ. ಯಾವುದೇ character repeat ಆದ ಕೂಡಲೇ, left pointer ಅನ್ನು ಆ character ನ ಹಿಂದಿನ position ನ ನಂತರಕ್ಕೆ ಸರಿಸಿ. Window ನಲ್ಲಿ duplicate ಎಂದಿಗೂ ಇರುವುದಿಲ್ಲ. Time complexity O(n).","malayalam":"Pattern: sliding window-ഉം last index map-ഉം. Right pointer window വളർത്തും. ഏതെങ്കിലും character repeat ആയാൽ, left pointer-നെ ആ character-ന്റെ മുൻപത്തെ position-ന് ശേഷം നീക്കുക. Window-ൽ duplicate ഒരിക്കലും ഉണ്ടാകില്ല. Time complexity O(n)."},"simple":{"hinglish":"Simple mein: ek khidki rakho jisme koi letter do baar na ho. Letter repeat ho toh khidki ko aage se chhota kar do.","english":"Simply: keep a window with no repeated letter. When a letter repeats, shrink the window from the left."},"example":"Example: string hai a b c a b c b b. Window a b c banti hai, phir a repeat hota hai toh window aage badhti hai. Sabse lambi window ki length 3 hai."},{"topic":"Valid Anagram","keywords":["anagram","एनाग्राम","అనాగ్రామ్","அனகிராம்","ಅನಾಗ್ರಾಮ್","അനഗ്രാം"],"answers":{"hinglish":"Pattern hai frequency count. Pehli string ke har character ki count badhao, dusri string ke har character ki count ghatao. Aakhir mein saari counts zero honi chahiye. Chhote alphabet ke liye size 26 ka array kaafi hai, general case mein hash map use karo. Time hai O of n, space O of 1 array wale version mein. Trade-off: sorting wala solution O of n log n hai, frequency count usse tez aur simple hai.","english":"The pattern is frequency counting. Count up every character of the first string, then count down every character of the second. At the end, all counts must be zero. For a small alphabet, an array of size 26 is enough; in general, use a hash map. Time is O of n, space O of 1 for the array version. The trade-off: sorting both strings costs O of n log n — counting is faster and simpler.","telugu":"Pattern: frequency count. మొదటి string లో ప్రతి character count పెంచండి, రెండో string లో తగ్గించండి. చివర్లో అన్ని counts zero అవ్వాలి. చిన్న alphabet కోసం size 26 array సరిపోతుంది. Time complexity O(n). Sorting కన్నా ఇది fast మరియు simple.","tamil":"Pattern: frequency count. முதல் string-ல் ஒவ்வொரு character count-ஐ கூட்டுங்கள், இரண்டாவது string-ல் குறையுங்கள். கடைசியில் எல்லா counts-உம் zero ஆக வேண்டும். சிறிய alphabet-க்கு size 26 array போதும். Time complexity O(n). Sorting-ஐ விட இது fast மற்றும் simple.","kannada":"Pattern: frequency count. ಮೊದಲ string ನಲ್ಲಿ ಪ್ರತಿ character count ಹೆಚ್ಚಿಸಿ, ಎರಡನೇ string ನಲ್ಲಿ ಕಡಿಮೆ ಮಾಡಿ. ಕೊನೆಯಲ್ಲಿ ಎಲ್ಲಾ counts zero ಆಗಬೇಕು. ಚಿಕ್ಕ alphabet ಗೆ size 26 array ಸಾಕು. Time complexity O(n). Sorting ಕ್ಕಿಂತ ಇದು fast ಮತ್ತು simple.","malayalam":"Pattern: frequency count. ആദ്യ string-ൽ ഓരോ character count-ഉം കൂട്ടുക, രണ്ടാമത്തെ string-ൽ കുറയ്ക്കുക. അവസാനം എല്ലാ counts-ഉം zero ആകണം. ചെറിയ alphabet-ന് size 26 array മതി. Time complexity O(n). Sorting-നേക്കാൾ ഇത് fast-ഉം simple-ഉം ആണ്."},"simple":{"hinglish":"Simple mein: dono shabdon ke letters gino. Har letter ki ginti barabar ho toh anagram hai.","english":"Simply: count the letters in both words. If every letter count matches, it's an anagram."},"example":"Example: anagram aur nagaram. Dono mein a teen baar, aur g, n, r, m ek ek baar. Counts barabar — anagram hai."},{"topic":"Sliding Window (generic)","keywords":["sliding window","window pattern","खिड़की","స్లైడింగ్ విండో","ஸ்லைடிங் விண்டோ","ಸ್ಲೈಡಿಂಗ್ ವಿಂಡೋ","സ്ലൈഡിംഗ് വിൻഡോ"],"answers":{"hinglish":"Sliding window tab use hota hai jab subarray ya substring par koi condition check karni ho aur array ke elements zyada tar positive hon ya window ka size manageable ho. Right pointer window failata hai, aur condition toot-te hi left pointer window sikodta hai. Dono pointers sirf aage badhte hain, isliye time O of n hota hai. Trade-off: negative numbers wale sum problems mein ye fail ho sakta hai, wahan prefix sum with hash map lagta hai.","english":"Use a sliding window when you must check a condition over a subarray or substring and the elements are mostly positive, or the window size is manageable. The right pointer expands the window; when the condition breaks, the left pointer shrinks it. Both pointers only move forward, giving O of n time. The trade-off: with negative numbers in a sum problem this can fail — switch to prefix sum with a hash map there.","telugu":"Subarray లేదా substring పై condition check చేయాల్సి వచ్చినప్పుడు sliding window వాడండి. Right pointer window ని విస్తరిస్తుంది, condition విరిగితే left pointer దాన్ని తగ్గిస్తుంది. రెండు pointers ముందుకే వెళ్తాయి కాబట్టి time O(n). Negative numbers ఉంటే prefix sum వాడాలి.","tamil":"Subarray அல்லது substring மீது condition check செய்ய வேண்டியபோது sliding window பயன்படுத்துங்கள். Right pointer window-ஐ விரிவாக்கும், condition முறிந்தால் left pointer அதை சுருக்கும். இரண்டு pointers-உம் முன்னோக்கி மட்டுமே நகர்வதால் time O(n). Negative numbers இருந்தால் prefix sum வேண்டும்.","kannada":"Subarray ಅಥವಾ substring ಮೇಲೆ condition check ಮಾಡಬೇಕಾದಾಗ sliding window ಬಳಸಿ. Right pointer window ಅನ್ನು ವಿಸ್ತರಿಸುತ್ತದೆ, condition ಮುರಿದರೆ left pointer ಅದನ್ನು ಕುಗ್ಗಿಸುತ್ತದೆ. ಎರಡು pointers ಮುಂದಕ್ಕೆ ಮಾತ್ರ ಚಲಿಸುವುದರಿಂದ time O(n). Negative numbers ಇದ್ದರೆ prefix sum ಬೇಕು.","malayalam":"Subarray അല്ലെങ്കിൽ substring-മേൽ condition check ചെയ്യേണ്ടിവരുമ്പോൾ sliding window ഉപയോഗിക്കുക. Right pointer window വലുതാക്കും, condition തെറ്റിയാൽ left pointer ചുരുക്കും. രണ്ട് pointers-ഉം മുന്നോട്ട് മാത്രം നീങ്ങുന്നതുകൊണ്ട് time O(n). Negative numbers ഉണ്ടെങ്കിൽ prefix sum വേണം."},"simple":{"hinglish":"Simple mein: ek khidki jo aage badhti hai — right se failao, left se sikodo. Har element ek hi baar andar aur ek hi baar bahar.","english":"Simply: a window that slides forward — grow it from the right, shrink it from the left. Every element enters and leaves once."},"example":"Example: array hai 2, 1, 5, 1, 3, 2 aur k hai 3. Teen teen ki windows: 2 1 5 ka sum 8, 1 5 1 ka 7, 5 1 3 ka 9, 1 3 2 ka 6. Maximum 9 hai."},{"topic":"Binary Search","category":"Arrays & Searching","difficulty":"Easy","keywords":["binary search","binarysearch","bainari search","sorted array search","log n search","द्विआधारी खोज","బైనరీ సెర్చ్","பைனரி சர்ச்","ಬೈನರಿ ಸರ್ಚ್","ബൈനറി സെർച്ച്"],"answers":{"hinglish":"Pattern hai divide and conquer, sorted array par. Mid element ko target se compare karo. Target chhota hai toh left half mein jao, bada hai toh right half mein. Har step mein search space aadha ho jata hai, isliye ye linear scan se bahut tez hai. Time hai O of log n, space O of 1. Trade-off: array sorted hona zaroori hai. Sorted nahi hai toh pehle sort karna padega, jo O of n log n hai. Interview mein overflow-safe mid, matlab low plus high minus low by two, bolna achha lagta hai.","english":"The pattern is divide and conquer on a sorted array. Compare the middle element with the target. If the target is smaller, search the left half; if larger, the right half. Each step halves the search space, so it is far faster than a linear scan. Time is O of log n, space O of 1. The trade-off: the array must be sorted. If it is not, sorting first costs O of n log n. In an interview, mention the overflow-safe midpoint: low plus half of high minus low.","telugu":"Pattern: sorted array పై divide and conquer. Middle element ని target తో compare చేయండి. Target చిన్నదైతే left half, పెద్దదైతే right half వెతకండి. ప్రతి step లో search space సగం అవుతుంది. Time O(log n), space O(1). Array sorted గా ఉండాలి — లేకపోతే ముందు sort చేయాలి, అది O(n log n).","tamil":"Pattern: sorted array மீது divide and conquer. Middle element-ஐ target உடன் compare செய்யுங்கள். Target சிறியதாக இருந்தால் left half, பெரியதாக இருந்தால் right half தேடுங்கள். ஒவ்வொரு step-லும் search space பாதியாகிறது. Time O(log n), space O(1). Array sorted ஆக இருக்க வேண்டும் — இல்லையெனில் முதலில் sort செய்ய வேண்டும்.","kannada":"Pattern: sorted array ಮೇಲೆ divide and conquer. Middle element ಅನ್ನು target ಜೊತೆ compare ಮಾಡಿ. Target ಚಿಕ್ಕದಾಗಿದ್ದರೆ left half, ದೊಡ್ಡದಾಗಿದ್ದರೆ right half ಹುಡುಕಿ. ಪ್ರತಿ step ನಲ್ಲಿ search space ಅರ್ಧವಾಗುತ್ತದೆ. Time O(log n), space O(1). Array sorted ಆಗಿರಬೇಕು — ಇಲ್ಲದಿದ್ದರೆ ಮೊದಲು sort ಮಾಡಬೇಕು, ಅದು O(n log n).","malayalam":"Pattern: sorted array-യിൽ divide and conquer. Middle element-നെ target-മായി compare ചെയ്യുക. Target ചെറുതാണെങ്കിൽ left half, വലുതാണെങ്കിൽ right half തിരയുക. ഓരോ step-ലും search space പകുതിയാകും. Time O(log n), space O(1). Array sorted ആയിരിക്കണം — അല്ലെങ്കിൽ ആദ്യം sort ചെയ്യണം, അത് O(n log n) ആണ്."},"simple":{"hinglish":"Simple mein: beech wala element dekho, target usse chhota hai ya bada, us hisaab se aadha array hata do. Baar baar yehi karo.","english":"Simply: look at the middle element, discard the half that cannot contain the target, and repeat."},"example":"Example: nums = [1, 3, 5, 7, 9], target = 7. Mid = 5, target bigger, go right. Mid = 7, found at index 3."},{"topic":"Merge Intervals","category":"Arrays & Searching","difficulty":"Medium","keywords":["merge intervals","merge interval","overlapping intervals","interval merge","merge overlapping"],"answers":{"hinglish":"Pattern hai sort karke merge. Intervals ko start time ke hisaab se sort karo, phir ek ek karke dekho. Agar current interval pichhle merged interval se overlap karta hai, toh end ko max tak badhao. Nahi toh naya interval shuru karo. Sorting ki wajah se overlap check sirf pichhle interval se karna padta hai. Time hai O of n log n sorting ke liye, space O of n output ke liye. Trade-off: input ko sort karna padta hai, original order kho jata hai. Yehi pattern meeting rooms aur insert interval mein bhi kaam aata hai.","english":"The pattern is sort, then merge. Sort the intervals by start time, then walk through them once. If the current interval overlaps the last merged one, extend its end to the maximum. Otherwise, start a new interval. Sorting means you only ever compare with the previous merged interval. Time is O of n log n for sorting, space O of n for the output. The trade-off: you lose the original order. The same pattern solves meeting rooms and insert interval.","telugu":"Pattern: start time ప్రకారం sort చేసి merge చేయండి. Current interval గత interval తో overlap అయితే end ని max వరకు పెంచండి, లేకపోతే కొత్త interval మొదలుపెట్టండి. Time O(n log n), space O(n). Sorting వల్ల original order పోతుంది — ఇదే trade-off.","tamil":"Pattern: start time படி sort செய்து merge செய்யுங்கள். Current interval முந்தைய interval உடன் overlap ஆனால் end-ஐ max வரை நீட்டவும், இல்லையெனில் புதிய interval தொடங்கவும். Time O(n log n), space O(n). Sorting-ஆல் original order போய்விடும் — அதுதான் trade-off.","kannada":"Pattern: start time ಪ್ರಕಾರ sort ಮಾಡಿ merge ಮಾಡಿ. Current interval ಹಿಂದಿನ interval ಜೊತೆ overlap ಆದರೆ end ಅನ್ನು max ವರೆಗೆ ವಿಸ್ತರಿಸಿ, ಇಲ್ಲದಿದ್ದರೆ ಹೊಸ interval ಶುರು ಮಾಡಿ. Time O(n log n), space O(n). Sorting ನಿಂದ original order ಕಳೆದುಹೋಗುತ್ತದೆ — ಅದೇ trade-off.","malayalam":"Pattern: start time അനുസരിച്ച് sort ചെയ്ത് merge ചെയ്യുക. Current interval മുൻ interval-മായി overlap ആയാൽ end max വരെ നീട്ടുക, ഇല്ലെങ്കിൽ പുതിയ interval തുടങ്ങുക. Time O(n log n), space O(n). Sorting കാരണം original order നഷ്ടമാകും — അതാണ് trade-off."},"simple":{"hinglish":"Simple mein: pehle sort karo, phir chipke hue intervals ko ek bada interval bana do.","english":"Simply: sort first, then glue together any intervals that touch or overlap."},"example":"Example: [[1,3],[2,6],[8,10],[15,18]] -> [[1,6],[8,10],[15,18]]."},{"topic":"Trapping Rain Water","category":"Arrays & Searching","difficulty":"Hard","keywords":["trapping rain water","trap rain water","rain water","rainwater","trapped water","water trapped"],"answers":{"hinglish":"Pattern hai two pointers with left max aur right max. Har position par rukne wala paani min of left max and right max minus height hota hai. Do pointer, left aur right, chhoti side se aage badhte hain, kyunki paani chhoti deewar se decide hota hai. Time hai O of n, space O of 1. Trade-off: do extra arrays se left max aur right max pehle nikaalna samajhna aasan hai, lekin O of n space leta hai. Two pointer version wahi kaam bina extra space ke karta hai, bas logic thoda dhyaan se bolna padta hai.","english":"The pattern is two pointers tracking the left maximum and right maximum. The water held at any position is the minimum of the two maxima minus its height. The pointers advance from the smaller side, because water is limited by the shorter wall. Time is O of n, space O of 1. The trade-off: precomputing left and right maxima in two arrays is easier to explain but costs O of n space. The two-pointer version does the same work with no extra space, at the cost of trickier reasoning.","telugu":"Pattern: left max, right max తో two pointers. ప్రతి position లో నీరు = min(left max, right max) minus height. చిన్న side నుంచి pointers ముందుకు వెళ్తాయి. Time O(n), space O(1). రెండు arrays వాడితే అర్థం చేసుకోవడం సులభం, కానీ O(n) space పడుతుంది.","tamil":"Pattern: left max, right max உடன் two pointers. ஒவ்வொரு position-லும் நீர் = min(left max, right max) minus height. சிறிய பக்கத்திலிருந்து pointers முன்னேறும். Time O(n), space O(1). இரண்டு arrays பயன்படுத்தினால் புரிவது எளிது, ஆனால் O(n) space ஆகும்.","kannada":"Pattern: left max, right max ಜೊತೆ two pointers. ಪ್ರತಿ position ನಲ್ಲಿ ನೀರು = min(left max, right max) minus height. ಚಿಕ್ಕ ಬದಿಯಿಂದ pointers ಮುಂದುವರಿಯುತ್ತವೆ. Time O(n), space O(1). ಎರಡು arrays ಬಳಸಿದರೆ ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವುದು ಸುಲಭ, ಆದರೆ O(n) space ಬೇಕು.","malayalam":"Pattern: left max, right max എന്നിവയോടെ two pointers. ഓരോ position-ലും വെള്ളം = min(left max, right max) minus height. ചെറിയ വശത്ത് നിന്ന് pointers മുന്നോട്ട് പോകും. Time O(n), space O(1). രണ്ട് arrays ഉപയോഗിച്ചാൽ മനസ്സിലാക്കാൻ എളുപ്പം, പക്ഷേ O(n) space വേണം."},"simple":{"hinglish":"Simple mein: har jagah paani utna rukta hai jitni chhoti deewar allow karti hai, apni height minus karke.","english":"Simply: at each spot, water is limited by the shorter of the tallest walls on either side, minus your own height."},"example":"Example: height = [0,1,0,2,1,0,1,3,2,1,2,1] -> trapped water = 6."},{"topic":"Maximum Subarray (Kadane's Algorithm)","category":"Arrays & Searching","difficulty":"Medium","keywords":["maximum subarray","max subarray","kadane","kadane's","largest sum subarray","maximum sum subarray"],"answers":{"hinglish":"Pattern hai Kadane's algorithm, greedy running sum. Chalte hue sum ko track karo, aur jab sum negative ho jaye toh use zero se restart karo, kyunki negative prefix aage ke sum ko sirf kam karega. Har step par best sum update karte raho. Time hai O of n, space O of 1. Trade-off: ye sirf maximum sum deta hai, subarray ka start aur end bhi chahiye toh extra tracking karni padegi. Edge case: saare numbers negative hon toh answer sabse bada, matlab sabse kam negative, number hota hai.","english":"The pattern is Kadane's algorithm: a greedy running sum. Track the current sum, and restart it at zero whenever it goes negative, because a negative prefix can only drag the future sum down. Keep the best sum seen so far. Time is O of n, space O of 1. The trade-off: this gives only the maximum sum; to also return the subarray bounds you need extra tracking. Edge case: if every number is negative, the answer is the largest, least negative, number.","telugu":"Pattern: Kadane's algorithm. Running sum track చేయండి; sum negative అయితే zero నుంచి restart చేయండి, ఎందుకంటే negative prefix ముందు sum ని తగ్గిస్తుంది. Time O(n), space O(1). అన్ని numbers negative అయితే, అతిపెద్ద number ఏ answer.","tamil":"Pattern: Kadane's algorithm. Running sum-ஐ track செய்யுங்கள்; sum negative ஆனால் zero-விலிருந்து restart செய்யுங்கள், ஏனெனில் negative prefix எதிர்கால sum-ஐ குறைக்கும். Time O(n), space O(1). எல்லா numbers-ம் negative என்றால், மிகப்பெரிய number தான் answer.","kannada":"Pattern: Kadane's algorithm. Running sum track ಮಾಡಿ; sum negative ಆದರೆ zero ನಿಂದ restart ಮಾಡಿ, ಏಕೆಂದರೆ negative prefix ಮುಂದಿನ sum ಅನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ. Time O(n), space O(1). ಎಲ್ಲಾ numbers negative ಆದರೆ, ದೊಡ್ಡ number ಏ answer.","malayalam":"Pattern: Kadane's algorithm. Running sum track ചെയ്യുക; sum negative ആയാൽ zero-യിൽ നിന്ന് restart ചെയ്യുക, കാരണം negative prefix ഭാവി sum കുറയ്ക്കും. Time O(n), space O(1). എല്ലാ numbers-ഉം negative ആണെങ്കിൽ, ഏറ്റവും വലിയ number ആണ് answer."},"simple":{"hinglish":"Simple mein: sum jodte jao, jab sum negative ho toh naya shuru karo, best sum yaad rakho.","english":"Simply: keep adding, restart when the running sum turns negative, and remember the best sum you saw."},"example":"Example: nums = [-2,1,-3,4,-1,2,1,-5,4] -> maximum sum = 6, from [4,-1,2,1]."},{"topic":"Group Anagrams","category":"Strings & Hashing","difficulty":"Medium","keywords":["group anagrams","group anagram","anagram groups","grouping anagrams"],"answers":{"hinglish":"Pattern hai hash map with a canonical key. Har word ke liye ek key banao jo uske saare anagrams ke liye same ho. Do tareeke hain: letters ko sort karke key banana, ya 26 letters ki count ko key banana. Count wala tareeka tez hai. Phir same key wale words ek hi group mein daal do. Time hai O of n into k, jahan k word ki length hai, count key ke saath. Trade-off: sort key likhna aasan hai lekin O of k log k leta hai. Count key tez hai par key banana thoda lamba hai.","english":"The pattern is a hash map with a canonical key. For each word, build a key that is identical for all of its anagrams. Two ways: sort the letters to form the key, or count the 26 letters to form the key. Counting is faster. Then place words with the same key in one group. Time is O of n times k, where k is word length, with the counting key. The trade-off: the sort key is easier to write but costs O of k log k. The count key is faster but more code.","telugu":"Pattern: canonical key తో hash map. ప్రతి word కి, దాని anagrams అన్నిటికీ ఒకేలా ఉండే key తయారుచేయండి — letters sort చేయడం లేదా 26 letters count చేయడం. Count key వేగంగా ఉంటుంది. Time O(n x k). Sort key సులభం, కానీ O(k log k).","tamil":"Pattern: canonical key உடன் hash map. ஒவ்வொரு word-க்கும், அதன் anagrams அனைத்திற்கும் ஒரே மாதிரியான key உருவாக்குங்கள் — letters-ஐ sort செய்வது அல்லது 26 letters-ஐ count செய்வது. Count key வேகமானது. Time O(n x k). Sort key எளிது, ஆனால் O(k log k).","kannada":"Pattern: canonical key ಜೊತೆ hash map. ಪ್ರತಿ word ಗೆ, ಅದರ ಎಲ್ಲಾ anagrams ಗೆ ಒಂದೇ ರೀತಿಯ key ಮಾಡಿ — letters sort ಮಾಡುವುದು ಅಥವಾ 26 letters count ಮಾಡುವುದು. Count key ವೇಗವಾಗಿದೆ. Time O(n x k). Sort key ಸುಲಭ, ಆದರೆ O(k log k).","malayalam":"Pattern: canonical key-യോടെ hash map. ഓരോ word-നും, അതിന്റെ എല്ലാ anagrams-നും ഒരേപോലെയുള്ള key ഉണ്ടാക്കുക — letters sort ചെയ്യുകയോ 26 letters count ചെയ്യുകയോ. Count key വേഗമാണ്. Time O(n x k). Sort key എളുപ്പം, പക്ഷേ O(k log k)."},"simple":{"hinglish":"Simple mein: jo words ek jaise letters se bane hain, unhe ek hi dabbe mein daal do. Dabbe ka naam letters ki count hai.","english":"Simply: put words built from the same letters in the same box, and label the box by its letter counts."},"example":"Example: [eat, tea, tan, ate, nat, bat] -> [[eat,tea,ate],[tan,nat],[bat]]."},{"topic":"Longest Palindromic Substring","category":"Strings & Hashing","difficulty":"Medium","keywords":["longest palindromic substring","palindromic substring","longest palindrome","palindrome substring","expand around center","expand around centre"],"answers":{"hinglish":"Pattern hai expand around centre. Har position ko centre maan ke dono taraf failo, jab tak characters match karte rahen. Do tarah ke centre hote hain: ek character wala odd length, aur do character wala even length. Dono check karna zaroori hai. Time hai O of n square, space O of 1. Trade-off: Manacher's algorithm O of n mein karta hai, lekin interview mein likhna aur samjhana mushkil hai. Expand around centre samajhna aasan hai aur aksar acceptable hota hai, bas dono centre types mat bhoolna.","english":"The pattern is expand around centre. Treat every position as a centre and grow outwards while the characters match. There are two centre types: a single character for odd lengths, and two characters for even lengths. You must check both. Time is O of n squared, space O of 1. The trade-off: Manacher's algorithm runs in O of n, but it is hard to write and explain in an interview. Expand around centre is easy to reason about and usually acceptable, as long as you handle both centre types.","telugu":"Pattern: centre చుట్టూ expand చేయడం. ప్రతి position ని centre గా తీసుకుని, characters match అయ్యేవరకు రెండు వైపులా విస్తరించండి. Odd length కి ఒక character, even length కి రెండు characters — రెండూ check చేయాలి. Time O(n square), space O(1). Manacher's O(n), కానీ కష్టం.","tamil":"Pattern: centre-ஐ சுற்றி expand செய்வது. ஒவ்வொரு position-ஐயும் centre ஆக எடுத்து, characters match ஆகும் வரை இரு பக்கமும் விரிவாக்குங்கள். Odd length-க்கு ஒரு character, even length-க்கு இரண்டு characters — இரண்டையும் check செய்ய வேண்டும். Time O(n square), space O(1). Manacher's O(n), ஆனால் கடினம்.","kannada":"Pattern: centre ಸುತ್ತ expand ಮಾಡುವುದು. ಪ್ರತಿ position ಅನ್ನು centre ಆಗಿ ತೆಗೆದುಕೊಂಡು, characters match ಆಗುವವರೆಗೆ ಎರಡೂ ಬದಿಗೆ ವಿಸ್ತರಿಸಿ. Odd length ಗೆ ಒಂದು character, even length ಗೆ ಎರಡು characters — ಎರಡನ್ನೂ check ಮಾಡಬೇಕು. Time O(n square), space O(1). Manacher's O(n), ಆದರೆ ಕಷ್ಟ.","malayalam":"Pattern: centre-ന് ചുറ്റും expand ചെയ്യുക. ഓരോ position-നെയും centre ആയി എടുത്ത്, characters match ആകുന്നതുവരെ രണ്ട് വശത്തേക്കും വികസിപ്പിക്കുക. Odd length-ന് ഒരു character, even length-ന് രണ്ട് characters — രണ്ടും check ചെയ്യണം. Time O(n square), space O(1). Manacher's O(n), പക്ഷേ ബുദ്ധിമുട്ടാണ്."},"simple":{"hinglish":"Simple mein: har jagah se beech se bahar ki taraf failo, jab tak dono taraf same letter mile. Sabse lamba wala jawab hai.","english":"Simply: grow outwards from every possible centre while both sides match, and keep the longest one you find."},"example":"Example: s = babad -> bab or aba. s = cbbd -> bb."},{"topic":"Reverse Linked List","category":"Linked List","difficulty":"Easy","keywords":["reverse linked list","reverse link list","reverse a linked list","reversing linked list","linked list reverse","reverse list","रिवर्स लिंक्ड लिस्ट","లింక్డ్ లిస్ట్ రివర్స్","லிங்க்ட் லிஸ்ட் ரிவர்ஸ்","ಲಿಂಕ್ಡ್ ಲಿಸ್ಟ್ ರಿವರ್ಸ್","ലിങ്ക്ഡ് ലിസ്റ്റ് റിവേഴ്സ്"],"answers":{"hinglish":"Pattern hai three pointers: previous, current, next. Har node par pehle next ko save karo, phir current ka next previous ki taraf mod do, phir previous aur current ko ek step aage badhao. Aakhir mein previous hi nayi head ban jata hai. Ye kaam karta hai kyunki hum ek ek karke har link ko ulta karte hain, list ko dobara banaye bina. Time hai O of n, space O of 1 iterative version mein. Recursive version bhi O of n time leta hai lekin call stack ke liye O of n space leta hai.","english":"The pattern is three pointers: previous, current, and next. At each node, save next, flip current's next pointer to point at previous, then move previous and current one step forward. At the end, previous is the new head. It works because you reverse one link at a time without rebuilding the list. Time is O of n, space O of 1 for the iterative version. The recursive version also takes O of n time but O of n stack space.","telugu":"Pattern: previous, current, next అనే మూడు pointers. ప్రతి node దగ్గర next ని save చేసి, current యొక్క next ని previous వైపు తిప్పండి, తర్వాత రెండింటినీ ముందుకు జరపండి. చివర్లో previous ఏ కొత్త head. Time O(n), space O(1). Recursive version కి O(n) stack space పడుతుంది.","tamil":"Pattern: previous, current, next என்ற மூன்று pointers. ஒவ்வொரு node-லும் next-ஐ save செய்து, current-ன் next-ஐ previous பக்கம் திருப்புங்கள், பிறகு இரண்டையும் முன்னே நகர்த்துங்கள். முடிவில் previous தான் புதிய head. Time O(n), space O(1). Recursive version-க்கு O(n) stack space ஆகும்.","kannada":"Pattern: previous, current, next ಎಂಬ ಮೂರು pointers. ಪ್ರತಿ node ನಲ್ಲಿ next ಅನ್ನು save ಮಾಡಿ, current ನ next ಅನ್ನು previous ಕಡೆಗೆ ತಿರುಗಿಸಿ, ನಂತರ ಎರಡನ್ನೂ ಮುಂದಕ್ಕೆ ಸರಿಸಿ. ಕೊನೆಯಲ್ಲಿ previous ಏ ಹೊಸ head. Time O(n), space O(1). Recursive version ಗೆ O(n) stack space ಬೇಕು.","malayalam":"Pattern: previous, current, next എന്ന മൂന്ന് pointers. ഓരോ node-ലും next save ചെയ്ത്, current-ന്റെ next previous-ലേക്ക് തിരിക്കുക, പിന്നീട് രണ്ടും മുന്നോട്ട് നീക്കുക. അവസാനം previous ആണ് പുതിയ head. Time O(n), space O(1). Recursive version-ന് O(n) stack space വേണം."},"simple":{"hinglish":"Simple mein: har node ka teer ulta kar do, ek ek karke, aakhir wala node head ban jayega.","english":"Simply: flip each node's arrow one by one; the last node becomes the new head."},"example":"Example: 1 -> 2 -> 3 -> null becomes 3 -> 2 -> 1 -> null."},{"topic":"Linked List Cycle","category":"Linked List","difficulty":"Easy","keywords":["linked list cycle","cycle in linked list","detect cycle","floyd cycle","tortoise hare","cycle detection linked list","loop in linked list"],"answers":{"hinglish":"Pattern hai Floyd's cycle detection, tortoise and hare. Ek slow pointer ek step chalta hai, ek fast pointer do step. Agar list mein cycle hai toh fast pointer slow ko peeche se pakad lega, kyunki woh gol gol ghoom rahe hain. Cycle nahi hai toh fast null tak pahunch jayega. Time hai O of n, space O of 1. Trade-off: visited nodes ko hash set mein rakhna samajhna aasan hai, lekin O of n space leta hai. Two pointer wala tareeka bina extra memory ke wahi jawab deta hai. Cycle ka start dhoondhna ho toh dono ko head se dobara chalana padta hai.","english":"The pattern is Floyd's cycle detection: tortoise and hare. A slow pointer moves one step, a fast pointer moves two. If there is a cycle, the fast pointer will eventually catch the slow one from behind, since both keep looping. If there is no cycle, the fast pointer reaches null. Time is O of n, space O of 1. The trade-off: storing visited nodes in a hash set is easier to follow but costs O of n space. The two-pointer method gives the same answer with no extra memory. To find where the cycle starts, restart one pointer at the head.","telugu":"Pattern: Floyd's tortoise and hare. Slow pointer ఒక step, fast pointer రెండు steps వెళ్తాయి. Cycle ఉంటే fast, slow ని పట్టుకుంటుంది; లేకపోతే fast null కి చేరుతుంది. Time O(n), space O(1). Hash set వాడితే సులభం, కానీ O(n) space పడుతుంది.","tamil":"Pattern: Floyd's tortoise and hare. Slow pointer ஒரு step, fast pointer இரண்டு steps செல்லும். Cycle இருந்தால் fast, slow-ஐ பிடிக்கும்; இல்லையெனில் fast null-ஐ அடையும். Time O(n), space O(1). Hash set பயன்படுத்தினால் எளிது, ஆனால் O(n) space ஆகும்.","kannada":"Pattern: Floyd's tortoise and hare. Slow pointer ಒಂದು step, fast pointer ಎರಡು steps ಹೋಗುತ್ತದೆ. Cycle ಇದ್ದರೆ fast, slow ಅನ್ನು ಹಿಡಿಯುತ್ತದೆ; ಇಲ್ಲದಿದ್ದರೆ fast null ತಲುಪುತ್ತದೆ. Time O(n), space O(1). Hash set ಬಳಸಿದರೆ ಸುಲಭ, ಆದರೆ O(n) space ಬೇಕು.","malayalam":"Pattern: Floyd's tortoise and hare. Slow pointer ഒരു step, fast pointer രണ്ട് steps പോകും. Cycle ഉണ്ടെങ്കിൽ fast, slow-നെ പിടിക്കും; ഇല്ലെങ്കിൽ fast null-ൽ എത്തും. Time O(n), space O(1). Hash set ഉപയോഗിച്ചാൽ എളുപ്പം, പക്ഷേ O(n) space വേണം."},"simple":{"hinglish":"Simple mein: ek dheere, ek tez. Tez wala dheere wale ko pakad le toh cycle hai, nahi toh nahi hai.","english":"Simply: one slow, one fast. If the fast one laps the slow one, there is a cycle."},"example":"Example: 3 -> 2 -> 0 -> -4, with -4 pointing back to 2 -> cycle present, answer true."},{"topic":"Merge Two Sorted Lists","category":"Linked List","difficulty":"Easy","keywords":["merge two sorted lists","merge sorted lists","merge two sorted linked lists","merge two lists"],"answers":{"hinglish":"Pattern hai dummy node with two pointers. Ek dummy head banao, phir dono lists ke head ko compare karo. Chhota node dummy ki tail se jodo, aur us list ka pointer aage badhao. Ek list khatm ho jaye toh doosri list ka bacha hua hissa seedha jod do. Dummy node se edge cases aasan ho jate hain, head ko alag se handle nahi karna padta. Time hai O of n plus m, space O of 1 iterative version mein. Recursive version bhi same time leta hai, lekin stack space leta hai.","english":"The pattern is a dummy node with two pointers. Create a dummy head, then compare the heads of both lists. Attach the smaller node to the dummy tail and advance that list's pointer. When one list runs out, attach the rest of the other directly. The dummy node removes edge cases, so you never handle the head separately. Time is O of n plus m, space O of 1 for the iterative version. The recursive version takes the same time but uses stack space.","telugu":"Pattern: dummy node తో two pointers. Dummy head తయారుచేసి, రెండు lists heads ని compare చేయండి. చిన్న node ని tail కి జోడించి, ఆ list pointer ముందుకు జరపండి. ఒక list అయిపోతే మరొకటి మిగిలిన భాగం నేరుగా జోడించండి. Time O(n + m), space O(1).","tamil":"Pattern: dummy node உடன் two pointers. Dummy head உருவாக்கி, இரண்டு lists-ன் heads-ஐ compare செய்யுங்கள். சிறிய node-ஐ tail-ல் இணைத்து, அந்த list pointer-ஐ முன்னே நகர்த்துங்கள். ஒரு list முடிந்தால் மற்றதின் மீதியை நேரடியாக இணைக்கவும். Time O(n + m), space O(1).","kannada":"Pattern: dummy node ಜೊತೆ two pointers. Dummy head ಮಾಡಿ, ಎರಡು lists ನ heads ಅನ್ನು compare ಮಾಡಿ. ಚಿಕ್ಕ node ಅನ್ನು tail ಗೆ ಜೋಡಿಸಿ, ಆ list pointer ಅನ್ನು ಮುಂದಕ್ಕೆ ಸರಿಸಿ. ಒಂದು list ಮುಗಿದರೆ ಇನ್ನೊಂದರ ಉಳಿದ ಭಾಗವನ್ನು ನೇರವಾಗಿ ಜೋಡಿಸಿ. Time O(n + m), space O(1).","malayalam":"Pattern: dummy node-യോടെ two pointers. Dummy head ഉണ്ടാക്കി, രണ്ട് lists-ന്റെ heads compare ചെയ്യുക. ചെറിയ node tail-ൽ ചേർത്ത്, ആ list pointer മുന്നോട്ട് നീക്കുക. ഒരു list തീർന്നാൽ മറ്റേതിന്റെ ബാക്കി നേരിട്ട് ചേർക്കുക. Time O(n + m), space O(1)."},"simple":{"hinglish":"Simple mein: dono ke pehle node mein se chhota wala lo, jodte jao, ek khatm ho toh doosri poori jod do.","english":"Simply: always take the smaller of the two front nodes, and when one list ends, attach the rest of the other."},"example":"Example: [1,2,4] + [1,3,4] -> [1,1,2,3,4,4]."},{"topic":"Remove Nth Node From End of List","category":"Linked List","difficulty":"Medium","keywords":["remove nth node from end","remove nth from end","nth node from end","remove node from end linked list"],"answers":{"hinglish":"Pattern hai two pointers with a fixed gap. Pehle fast pointer ko n steps aage bhejo, phir slow aur fast ko saath chalao. Jab fast end tak pahunchega, slow us node par hoga jise hatana hai usse just pehle. Phir slow ka next skip kar do. Dummy node use karo taaki head ko hatana ho toh bhi same code chale. Time hai O of n single pass mein, space O of 1. Do pass wala tareeka pehle length nikaalta hai, phir hatata hai — kaam karta hai, par do baar chalna padta hai.","english":"The pattern is two pointers with a fixed gap. Move the fast pointer n steps ahead, then walk slow and fast together. When fast reaches the end, slow sits just before the node to remove. Then skip that node. Use a dummy node so removing the head works with the same code. Time is O of n in a single pass, space O of 1. The two-pass method first measures the length, then removes — it works, but walks the list twice.","telugu":"Pattern: fixed gap తో two pointers. Fast pointer ని n steps ముందుకు పంపి, తర్వాత slow, fast కలిసి నడపండి. Fast end కి చేరేసరికి slow తొలగించాల్సిన node కి ముందు ఉంటుంది. Dummy node వాడండి. Time O(n), space O(1), single pass.","tamil":"Pattern: fixed gap உடன் two pointers. Fast pointer-ஐ n steps முன்னே அனுப்பி, பிறகு slow, fast இரண்டையும் சேர்த்து நடத்துங்கள். Fast end-ஐ அடையும்போது slow நீக்க வேண்டிய node-க்கு முன்னால் இருக்கும். Dummy node பயன்படுத்துங்கள். Time O(n), space O(1), single pass.","kannada":"Pattern: fixed gap ಜೊತೆ two pointers. Fast pointer ಅನ್ನು n steps ಮುಂದಕ್ಕೆ ಕಳುಹಿಸಿ, ನಂತರ slow, fast ಒಟ್ಟಿಗೆ ನಡೆಸಿ. Fast end ತಲುಪುವಾಗ slow ತೆಗೆದುಹಾಕಬೇಕಾದ node ಗಿಂತ ಮುಂಚೆ ಇರುತ್ತದೆ. Dummy node ಬಳಸಿ. Time O(n), space O(1), single pass.","malayalam":"Pattern: fixed gap-ഓടെ two pointers. Fast pointer n steps മുന്നോട്ട് അയച്ച്, പിന്നീട് slow, fast ഒരുമിച്ച് നടത്തുക. Fast end-ൽ എത്തുമ്പോൾ slow നീക്കേണ്ട node-ന് തൊട്ടുമുമ്പ് ആയിരിക്കും. Dummy node ഉപയോഗിക്കുക. Time O(n), space O(1), single pass."},"simple":{"hinglish":"Simple mein: fast ko n aage bhejo, phir dono saath chalo. Fast khatm ho toh slow sahi jagah par hoga.","english":"Simply: send fast n steps ahead, then walk both together. When fast ends, slow is in the right place."},"example":"Example: [1,2,3,4,5], n = 2 -> [1,2,3,5]. Node 4 removed."},{"topic":"Valid Parentheses","category":"Stack & Queue","difficulty":"Easy","keywords":["valid parentheses","valid parenthesis","balanced parentheses","parentheses valid","brackets valid","valid brackets","balanced brackets"],"answers":{"hinglish":"Pattern hai stack. Opening bracket mile toh stack mein daalo, closing bracket mile toh stack ka top check karo. Top par matching opening bracket hai toh pop karo, nahi hai ya stack khaali hai toh galat hai. Aakhir mein stack khaali hona chahiye. Stack isliye kaam karta hai kyunki bracket last in first out order mein band hote hain, sabse andar wala pehle band hota hai. Time hai O of n, space O of n worst case mein. Trade-off: sirf ek type ka bracket ho toh counter kaafi hai, lekin teen type ke liye stack chahiye.","english":"The pattern is a stack. On an opening bracket, push it. On a closing bracket, check the top of the stack. If the top is the matching opener, pop it; if not, or the stack is empty, the string is invalid. At the end the stack must be empty. A stack works because brackets close last-in-first-out: the innermost closes first. Time is O of n, space O of n in the worst case. The trade-off: one bracket type needs only a counter, but three types need a stack.","telugu":"Pattern: stack. Opening bracket వస్తే push చేయండి, closing bracket వస్తే stack top check చేయండి. Matching opener ఉంటే pop చేయండి, లేకపోతే invalid. చివర్లో stack ఖాళీగా ఉండాలి. Time O(n), space O(n). Brackets last-in-first-out order లో close అవుతాయి, అందుకే stack పనిచేస్తుంది.","tamil":"Pattern: stack. Opening bracket வந்தால் push செய்யுங்கள், closing bracket வந்தால் stack top-ஐ check செய்யுங்கள். Matching opener இருந்தால் pop செய்யுங்கள், இல்லையெனில் invalid. முடிவில் stack காலியாக இருக்க வேண்டும். Time O(n), space O(n). Brackets last-in-first-out order-ல் close ஆகும், அதனால் stack வேலை செய்கிறது.","kannada":"Pattern: stack. Opening bracket ಬಂದರೆ push ಮಾಡಿ, closing bracket ಬಂದರೆ stack top check ಮಾಡಿ. Matching opener ಇದ್ದರೆ pop ಮಾಡಿ, ಇಲ್ಲದಿದ್ದರೆ invalid. ಕೊನೆಯಲ್ಲಿ stack ಖಾಲಿ ಇರಬೇಕು. Time O(n), space O(n). Brackets last-in-first-out order ನಲ್ಲಿ close ಆಗುತ್ತವೆ, ಆದ್ದರಿಂದ stack ಕೆಲಸ ಮಾಡುತ್ತದೆ.","malayalam":"Pattern: stack. Opening bracket വന്നാൽ push ചെയ്യുക, closing bracket വന്നാൽ stack top check ചെയ്യുക. Matching opener ഉണ്ടെങ്കിൽ pop ചെയ്യുക, ഇല്ലെങ്കിൽ invalid. അവസാനം stack ശൂന്യമായിരിക്കണം. Time O(n), space O(n). Brackets last-in-first-out order-ൽ close ആകും, അതുകൊണ്ട് stack പ്രവർത്തിക്കുന്നു."},"simple":{"hinglish":"Simple mein: kholne wala andar daalo, band karne wala aaye toh upar wala match hona chahiye. Aakhir mein kuch bacha toh galat.","english":"Simply: push openers, and every closer must match the top. Anything left over means invalid."},"example":"Example: ()[]{} -> valid. (] -> invalid. ([)] -> invalid."},{"topic":"Min Stack","category":"Stack & Queue","difficulty":"Medium","keywords":["min stack","minimum stack","stack getmin","get minimum stack","minstack"],"answers":{"hinglish":"Pattern hai do stacks, ya ek stack with pairs. Har push par value ke saath us time tak ka minimum bhi save karo. Phir getMin sirf top pair ka minimum padh ke O of 1 mein jawab de deta hai. Pop par dono ek saath hat jate hain, toh minimum hamesha sahi rehta hai. Time hai har operation ke liye O of 1, space O of n extra minimums ke liye. Trade-off: har push par minimum dobara dhoondhna O of n hota. Thodi extra memory deke hum har operation ko constant time bana lete hain.","english":"The pattern is two stacks, or one stack of pairs. On every push, store the value together with the minimum so far. Then getMin reads the minimum from the top pair in O of 1. On pop, both leave together, so the minimum stays correct. Every operation takes O of 1 time, with O of n extra space for the stored minima. The trade-off: rescanning for the minimum on every push costs O of n. A little extra memory makes every operation constant time.","telugu":"Pattern: రెండు stacks, లేదా pairs తో ఒక stack. ప్రతి push దగ్గర value తో పాటు అప్పటివరకు minimum కూడా save చేయండి. అప్పుడు getMin O(1) లో answer ఇస్తుంది. ప్రతి operation O(1), space O(n). Minimum మళ్ళీ వెతికితే O(n) పడుతుంది.","tamil":"Pattern: இரண்டு stacks, அல்லது pairs உடன் ஒரு stack. ஒவ்வொரு push-லும் value உடன் அதுவரை minimum-ஐயும் save செய்யுங்கள். பிறகு getMin O(1)-ல் answer தரும். ஒவ்வொரு operation-ம் O(1), space O(n). Minimum-ஐ மீண்டும் தேடினால் O(n) ஆகும்.","kannada":"Pattern: ಎರಡು stacks, ಅಥವಾ pairs ಜೊತೆ ಒಂದು stack. ಪ್ರತಿ push ನಲ್ಲಿ value ಜೊತೆಗೆ ಅಲ್ಲಿಯವರೆಗಿನ minimum ಅನ್ನು save ಮಾಡಿ. ನಂತರ getMin O(1) ನಲ್ಲಿ answer ನೀಡುತ್ತದೆ. ಪ್ರತಿ operation O(1), space O(n). Minimum ಅನ್ನು ಮತ್ತೆ ಹುಡುಕಿದರೆ O(n) ಆಗುತ್ತದೆ.","malayalam":"Pattern: രണ്ട് stacks, അല്ലെങ്കിൽ pairs-ഓടെ ഒരു stack. ഓരോ push-ലും value-യോടൊപ്പം അതുവരെയുള്ള minimum-ഉം save ചെയ്യുക. പിന്നീട് getMin O(1)-ൽ answer തരും. ഓരോ operation-ഉം O(1), space O(n). Minimum വീണ്ടും തിരഞ്ഞാൽ O(n) ആകും."},"simple":{"hinglish":"Simple mein: har value ke saath us time ka sabse chhota number chipka do. Upar wala chipka number hi minimum hai.","english":"Simply: stick the smallest-so-far number onto every value you push. The top sticker is always the minimum."},"example":"Example: push -2, 0, -3. getMin -> -3. pop. top -> 0. getMin -> -2."},{"topic":"Next Greater Element","category":"Stack & Queue","difficulty":"Medium","keywords":["next greater element","next greater","next largest element","monotonic stack","next bigger element"],"answers":{"hinglish":"Pattern hai monotonic decreasing stack. Array ko right se left scan karo, aur stack mein sirf woh elements rakho jo current se bade hain. Chhote ya barabar elements ko pop kar do, kyunki woh aage kisi ke liye next greater nahi ban sakte. Stack ka top hi next greater hota hai, khaali hai toh koi nahi. Har element ek baar push aur ek baar pop hota hai, isliye time O of n hai, space O of n. Trade-off: har element ke liye aage scan karna O of n square hota hai. Stack se hum bekaar comparisons bacha lete hain.","english":"The pattern is a monotonic decreasing stack. Scan the array from right to left, keeping only elements larger than the current one on the stack. Pop smaller or equal elements, because they can never be anyone's next greater element. The stack top is the next greater element, or none if empty. Each element is pushed and popped once, so time is O of n, space O of n. The trade-off: scanning ahead for every element costs O of n squared. The stack skips comparisons that can never win.","telugu":"Pattern: monotonic decreasing stack. Right నుంచి left కి scan చేయండి, current కన్నా పెద్ద elements మాత్రమే stack లో ఉంచండి. చిన్న elements ని pop చేయండి. Stack top ఏ next greater element. Time O(n), space O(n). ముందుకు scan చేస్తే O(n square) పడుతుంది.","tamil":"Pattern: monotonic decreasing stack. Right-லிருந்து left-க்கு scan செய்யுங்கள், current-ஐ விட பெரிய elements மட்டும் stack-ல் வையுங்கள். சிறிய elements-ஐ pop செய்யுங்கள். Stack top தான் next greater element. Time O(n), space O(n). முன்னே scan செய்தால் O(n square) ஆகும்.","kannada":"Pattern: monotonic decreasing stack. Right ನಿಂದ left ಗೆ scan ಮಾಡಿ, current ಗಿಂತ ದೊಡ್ಡ elements ಮಾತ್ರ stack ನಲ್ಲಿ ಇರಿಸಿ. ಚಿಕ್ಕ elements ಅನ್ನು pop ಮಾಡಿ. Stack top ಏ next greater element. Time O(n), space O(n). ಮುಂದೆ scan ಮಾಡಿದರೆ O(n square) ಆಗುತ್ತದೆ.","malayalam":"Pattern: monotonic decreasing stack. Right-ൽ നിന്ന് left-ലേക്ക് scan ചെയ്യുക, current-നേക്കാൾ വലിയ elements മാത്രം stack-ൽ വയ്ക്കുക. ചെറിയ elements pop ചെയ്യുക. Stack top ആണ് next greater element. Time O(n), space O(n). മുന്നോട്ട് scan ചെയ്താൽ O(n square) ആകും."},"simple":{"hinglish":"Simple mein: peeche se aao, chhote elements hata do, upar bacha hua bada wala hi jawab hai.","english":"Simply: walk backwards, throw away smaller elements, and the survivor on top is the answer."},"example":"Example: nums = [4,5,2,25] -> next greater = [5,25,25,-1]."},{"topic":"Binary Tree Traversals","category":"Trees","difficulty":"Easy","keywords":["binary tree traversal","tree traversal","inorder","in order traversal","preorder","pre order traversal","postorder","post order traversal","inorder preorder postorder","traverse tree","tree traversals"],"answers":{"hinglish":"Pattern hai recursion: node, left, right ka order badal do, traversal badal jata hai. Inorder hai left, node, right — BST mein ye sorted order deta hai. Preorder hai node, left, right — tree ko copy karne ya serialize karne mein kaam aata hai. Postorder hai left, right, node — bachchon ko pehle process karna ho toh, jaise delete karte waqt. Time hai O of n, space O of height recursion stack ke liye. Trade-off: iterative version stack se bhi likha ja sakta hai, lekin recursion samajhna aur likhna aasan hai. Level order alag hai, woh queue se hota hai, BFS jaisa.","english":"The pattern is recursion: change the order of node, left, and right, and you change the traversal. Inorder is left, node, right — on a BST it gives sorted order. Preorder is node, left, right — useful for copying or serialising a tree. Postorder is left, right, node — for when children must be processed first, such as deletion. Time is O of n, space O of height for the recursion stack. The trade-off: an iterative stack version is possible, but recursion is easier to write and explain. Level order is different: it uses a queue, like BFS.","telugu":"Pattern: recursion — node, left, right order మారిస్తే traversal మారుతుంది. Inorder: left, node, right — BST లో sorted order ఇస్తుంది. Preorder: node, left, right. Postorder: left, right, node. Time O(n), space O(height). Level order queue తో చేస్తారు, BFS లాగా.","tamil":"Pattern: recursion — node, left, right order-ஐ மாற்றினால் traversal மாறும். Inorder: left, node, right — BST-ல் sorted order தரும். Preorder: node, left, right. Postorder: left, right, node. Time O(n), space O(height). Level order queue கொண்டு செய்யப்படும், BFS போல.","kannada":"Pattern: recursion — node, left, right order ಬದಲಾಯಿಸಿದರೆ traversal ಬದಲಾಗುತ್ತದೆ. Inorder: left, node, right — BST ನಲ್ಲಿ sorted order ನೀಡುತ್ತದೆ. Preorder: node, left, right. Postorder: left, right, node. Time O(n), space O(height). Level order queue ಜೊತೆ ಮಾಡುತ್ತಾರೆ, BFS ಹಾಗೆ.","malayalam":"Pattern: recursion — node, left, right order മാറ്റിയാൽ traversal മാറും. Inorder: left, node, right — BST-യിൽ sorted order തരും. Preorder: node, left, right. Postorder: left, right, node. Time O(n), space O(height). Level order queue കൊണ്ട് ചെയ്യും, BFS പോലെ."},"simple":{"hinglish":"Simple mein: inorder mein beech wala beech mein, preorder mein pehle, postorder mein aakhir mein. Baaki left phir right.","english":"Simply: inorder puts the node in the middle, preorder first, postorder last. Otherwise left, then right."},"example":"Example: tree 1 with left 2 and right 3. Inorder: 2,1,3. Preorder: 1,2,3. Postorder: 2,3,1."},{"topic":"Maximum Depth of Binary Tree","category":"Trees","difficulty":"Easy","keywords":["maximum depth of binary tree","max depth binary tree","depth of binary tree","height of binary tree","tree height","max depth tree","tree depth"],"answers":{"hinglish":"Pattern hai recursion: kisi node ki depth, uske bachchon ki max depth plus one hoti hai. Null node ki depth zero hoti hai. Left aur right dono ki depth nikaalo, badi wali lo, ek jod do. Yehi soch har node par lagti hai, isliye recursion natural hai. Time hai O of n, space O of height recursion stack ke liye. Skewed tree mein height n ho sakti hai, balanced mein log n. Trade-off: iterative BFS level by level bhi kar sakta hai, lekin recursion chhota aur saaf hota hai. Depth aur height mein ek ka farak kabhi kabhi confuse karta hai, definition pehle clear karo.","english":"The pattern is recursion: a node's depth is the maximum depth of its children plus one. A null node's depth is zero. Compute the depth of the left and right subtrees, take the larger, and add one. The same idea applies at every node, so recursion is natural. Time is O of n, space O of height for the recursion stack. A skewed tree can have height n; a balanced one, log n. The trade-off: iterative BFS level by level also works, but recursion is shorter and cleaner. Be clear whether depth counts nodes or edges — definitions differ by one.","telugu":"Pattern: recursion. Node depth = పిల్లల max depth + 1; null node depth 0. Left, right depths తీసుకుని పెద్దదానికి 1 కలపండి. Time O(n), space O(height). Skewed tree లో height n కావచ్చు, balanced లో log n. BFS తో కూడా చేయవచ్చు, కానీ recursion సులభం.","tamil":"Pattern: recursion. Node depth = குழந்தைகளின் max depth + 1; null node depth 0. Left, right depths எடுத்து பெரியதுடன் 1 சேர்க்கவும். Time O(n), space O(height). Skewed tree-ல் height n ஆகலாம், balanced-ல் log n. BFS கொண்டும் செய்யலாம், ஆனால் recursion எளிது.","kannada":"Pattern: recursion. Node depth = ಮಕ್ಕಳ max depth + 1; null node depth 0. Left, right depths ತೆಗೆದುಕೊಂಡು ದೊಡ್ಡದಕ್ಕೆ 1 ಸೇರಿಸಿ. Time O(n), space O(height). Skewed tree ನಲ್ಲಿ height n ಆಗಬಹುದು, balanced ನಲ್ಲಿ log n. BFS ನಿಂದಲೂ ಮಾಡಬಹುದು, ಆದರೆ recursion ಸುಲಭ.","malayalam":"Pattern: recursion. Node depth = കുട്ടികളുടെ max depth + 1; null node depth 0. Left, right depths എടുത്ത് വലുതിനോട് 1 കൂട്ടുക. Time O(n), space O(height). Skewed tree-യിൽ height n ആകാം, balanced-ൽ log n. BFS കൊണ്ടും ചെയ്യാം, പക്ഷേ recursion എളുപ്പമാണ്."},"simple":{"hinglish":"Simple mein: neeche kitne level hain, woh gino. Khaali jagah zero, har node ek jod deta hai.","english":"Simply: count the levels below you. Empty is zero, and every node adds one."},"example":"Example: root 3, left 9, right 20 with children 15, 7 -> depth = 3."},{"topic":"Invert Binary Tree","category":"Trees","difficulty":"Easy","keywords":["invert binary tree","invert tree","mirror tree","mirror binary tree","flip binary tree","reverse binary tree"],"answers":{"hinglish":"Pattern hai recursion with swap. Har node par left aur right bachchon ko swap karo, phir dono par wahi kaam dobara karo. Null node par ruk jao. Swap pehle karo ya baad mein, dono chalte hain, bas har node par swap hona chahiye. Time hai O of n, space O of height recursion stack ke liye. Trade-off: iterative version queue se bhi ho sakta hai, level by level swap karke. Recursion zyada seedha hai aur interview mein pehle yahi bolna chahiye.","english":"The pattern is recursion with a swap. At every node, swap the left and right children, then recurse on both. Stop at null nodes. Swapping before or after the recursive calls both work, as long as every node is swapped. Time is O of n, space O of height for the recursion stack. The trade-off: an iterative queue version can swap level by level. Recursion is more direct and the one to state first in an interview.","telugu":"Pattern: swap తో recursion. ప్రతి node దగ్గర left, right పిల్లల్ని swap చేసి, రెండింటిపై మళ్ళీ అదే చేయండి. Null దగ్గర ఆగండి. Time O(n), space O(height). Queue తో iterative గా కూడా చేయవచ్చు, కానీ recursion సూటిగా ఉంటుంది.","tamil":"Pattern: swap உடன் recursion. ஒவ்வொரு node-லும் left, right குழந்தைகளை swap செய்து, இரண்டிலும் மீண்டும் அதையே செய்யுங்கள். Null-ல் நிறுத்துங்கள். Time O(n), space O(height). Queue கொண்டு iterative ஆகவும் செய்யலாம், ஆனால் recursion நேரடியானது.","kannada":"Pattern: swap ಜೊತೆ recursion. ಪ್ರತಿ node ನಲ್ಲಿ left, right ಮಕ್ಕಳನ್ನು swap ಮಾಡಿ, ಎರಡರ ಮೇಲೂ ಮತ್ತೆ ಅದನ್ನೇ ಮಾಡಿ. Null ನಲ್ಲಿ ನಿಲ್ಲಿ. Time O(n), space O(height). Queue ಜೊತೆ iterative ಆಗಿಯೂ ಮಾಡಬಹುದು, ಆದರೆ recursion ನೇರವಾಗಿದೆ.","malayalam":"Pattern: swap-ഓടെ recursion. ഓരോ node-ലും left, right കുട്ടികളെ swap ചെയ്ത്, രണ്ടിലും വീണ്ടും അതുതന്നെ ചെയ്യുക. Null-ൽ നിർത്തുക. Time O(n), space O(height). Queue കൊണ്ട് iterative ആയും ചെയ്യാം, പക്ഷേ recursion നേരിട്ടുള്ളതാണ്."},"simple":{"hinglish":"Simple mein: har node ke left right badal do, sheesha image ban jayegi.","english":"Simply: swap left and right at every node, and you get the mirror image."},"example":"Example: [4,2,7,1,3,6,9] inverted -> [4,7,2,9,6,3,1]."},{"topic":"Validate Binary Search Tree","category":"Trees","difficulty":"Medium","keywords":["validate binary search tree","validate bst","check bst","is valid bst","valid bst","bst valid","binary search tree valid"],"answers":{"hinglish":"Pattern hai range check with recursion. Har node ke liye ek allowed range rakho, low aur high. Node ki value range ke andar honi chahiye. Left mein jao toh high node ki value ban jati hai, right mein jao toh low node ki value ban jati hai. Sirf direct bachchon ko dekhna kaafi nahi hai, poore subtree ko range mein rehna hai. Time hai O of n, space O of height. Trade-off: inorder traversal karke sorted hai ya nahi check karna bhi chalta hai, lekin range wala tareeka galat node milte hi ruk sakta hai. Edge case: duplicate values allowed nahi hain, strict less than aur greater than use karo.","english":"The pattern is a range check with recursion. Carry an allowed range, low and high, for each node. The node's value must lie inside it. Going left, high becomes the node's value; going right, low becomes the node's value. Checking only direct children is not enough — the whole subtree must respect the range. Time is O of n, space O of height. The trade-off: an inorder traversal that checks sorted order also works, but the range method can stop at the first violation. Edge case: duplicates are not allowed, so use strict less-than and greater-than.","telugu":"Pattern: range check తో recursion. ప్రతి node కి low, high range ఉంచండి; value range లోపల ఉండాలి. Left కి వెళ్తే high = node value, right కి వెళ్తే low = node value. పిల్లల్ని మాత్రమే చూడటం సరిపోదు. Time O(n), space O(height). Duplicates allowed కావు.","tamil":"Pattern: range check உடன் recursion. ஒவ்வொரு node-க்கும் low, high range வையுங்கள்; value range-க்குள் இருக்க வேண்டும். Left சென்றால் high = node value, right சென்றால் low = node value. குழந்தைகளை மட்டும் பார்ப்பது போதாது. Time O(n), space O(height). Duplicates அனுமதிக்கப்படவில்லை.","kannada":"Pattern: range check ಜೊತೆ recursion. ಪ್ರತಿ node ಗೆ low, high range ಇರಿಸಿ; value range ಒಳಗೆ ಇರಬೇಕು. Left ಗೆ ಹೋದರೆ high = node value, right ಗೆ ಹೋದರೆ low = node value. ಮಕ್ಕಳನ್ನು ಮಾತ್ರ ನೋಡುವುದು ಸಾಕಾಗುವುದಿಲ್ಲ. Time O(n), space O(height). Duplicates allowed ಅಲ್ಲ.","malayalam":"Pattern: range check-ഓടെ recursion. ഓരോ node-നും low, high range വയ്ക്കുക; value range-നുള്ളിൽ ആയിരിക്കണം. Left-ലേക്ക് പോയാൽ high = node value, right-ലേക്ക് പോയാൽ low = node value. കുട്ടികളെ മാത്രം നോക്കിയാൽ പോരാ. Time O(n), space O(height). Duplicates അനുവദനീയമല്ല."},"simple":{"hinglish":"Simple mein: har node ko apni had mein rehna hai. Baayein wale chhote, daayein wale bade, poori shaka tak.","english":"Simply: every node must stay within its bounds. Everything left is smaller, everything right is bigger, all the way down."},"example":"Example: [2,1,3] -> valid. [5,1,4,null,null,3,6] -> invalid, 3 is in the right subtree of 5 but smaller than 5."},{"topic":"Lowest Common Ancestor of a BST","category":"Trees","difficulty":"Medium","keywords":["lowest common ancestor","lca","lowest common ancestor bst","lca bst","common ancestor","lowest common ancestor binary search tree"],"answers":{"hinglish":"Pattern hai BST property ka use. Root se shuru karo. Dono nodes root se chhote hain toh answer left mein hai, dono bade hain toh right mein hai. Ek chhota ek bada hai, ya ek root ke barabar hai, toh wahi root answer hai, kyunki wahan paths alag hote hain. Time hai O of height, space O of 1 iterative version mein. Trade-off: general binary tree mein ye trick nahi chalti, wahan dono taraf search karke recursion se karna padta hai. BST mein ordering hi shortcut hai, use bolna important hai.","english":"The pattern is to use the BST property. Start at the root. If both nodes are smaller than the root, the answer is on the left; if both are larger, on the right. If one is smaller and one larger, or one equals the root, that root is the answer, because the paths split there. Time is O of height, space O of 1 for the iterative version. The trade-off: this trick does not work for a general binary tree, where you must search both sides recursively. In a BST, the ordering is the shortcut — say so in the interview.","telugu":"Pattern: BST property వాడండి. Root నుంచి మొదలుపెట్టండి. రెండు nodes root కన్నా చిన్నవైతే left, పెద్దవైతే right. ఒకటి చిన్నది, ఒకటి పెద్దది అయితే ఆ root ఏ answer. Time O(height), space O(1). General binary tree లో ఈ trick పనిచేయదు.","tamil":"Pattern: BST property-ஐ பயன்படுத்துங்கள். Root-லிருந்து தொடங்குங்கள். இரண்டு nodes-ம் root-ஐ விட சிறியதாக இருந்தால் left, பெரியதாக இருந்தால் right. ஒன்று சிறியது, ஒன்று பெரியது என்றால் அந்த root தான் answer. Time O(height), space O(1). General binary tree-ல் இந்த trick வேலை செய்யாது.","kannada":"Pattern: BST property ಬಳಸಿ. Root ನಿಂದ ಶುರು ಮಾಡಿ. ಎರಡೂ nodes root ಗಿಂತ ಚಿಕ್ಕದಾಗಿದ್ದರೆ left, ದೊಡ್ಡದಾಗಿದ್ದರೆ right. ಒಂದು ಚಿಕ್ಕದು, ಒಂದು ದೊಡ್ಡದು ಆದರೆ ಆ root ಏ answer. Time O(height), space O(1). General binary tree ನಲ್ಲಿ ಈ trick ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ.","malayalam":"Pattern: BST property ഉപയോഗിക്കുക. Root-ൽ നിന്ന് തുടങ്ങുക. രണ്ട് nodes-ഉം root-നേക്കാൾ ചെറുതാണെങ്കിൽ left, വലുതാണെങ്കിൽ right. ഒന്ന് ചെറുത്, ഒന്ന് വലുത് ആണെങ്കിൽ ആ root ആണ് answer. Time O(height), space O(1). General binary tree-യിൽ ഈ trick പ്രവർത്തിക്കില്ല."},"simple":{"hinglish":"Simple mein: jahan dono ke raaste alag hote hain, wahi common ancestor hai.","english":"Simply: the ancestor where the two paths split is the answer."},"example":"Example: BST [6,2,8,0,4,7,9], p = 2, q = 8 -> LCA = 6. p = 2, q = 4 -> LCA = 2."},{"topic":"Breadth-First Search (BFS)","category":"Graphs","difficulty":"Medium","keywords":["breadth first search","bfs","breadth-first","bfs graph","breadth first traversal","level order graph"],"answers":{"hinglish":"Pattern hai queue with visited set. Start node ko queue mein daalo aur visited mark karo. Queue se node nikaalo, uske neighbours ko dekho, jo visited nahi hain unhe queue mein daalo aur visited mark karo. Ye level by level chalta hai, pehle paas wale, phir door wale. Isliye BFS unweighted graph mein shortest path, matlab sabse kam edges, deta hai. Time hai O of vertices plus edges, space O of vertices. Trade-off: DFS se zyada memory leta hai kyunki poora level queue mein rehta hai, lekin shortest path ki guarantee deta hai.","english":"The pattern is a queue with a visited set. Put the start node in the queue and mark it visited. Remove a node, look at its neighbours, and enqueue any unvisited ones, marking them visited. This runs level by level: near nodes first, then farther ones. That is why BFS gives the shortest path, fewest edges, in an unweighted graph. Time is O of vertices plus edges, space O of vertices. The trade-off: it uses more memory than DFS because a whole level sits in the queue, but it guarantees the shortest path.","telugu":"Pattern: visited set తో queue. Start node ని queue లో వేసి visited mark చేయండి. Node తీసి, neighbours చూసి, visited కానివాటిని queue లో వేయండి. Level by level వెళ్తుంది, అందుకే unweighted graph లో shortest path ఇస్తుంది. Time O(V + E), space O(V).","tamil":"Pattern: visited set உடன் queue. Start node-ஐ queue-ல் போட்டு visited mark செய்யுங்கள். Node-ஐ எடுத்து, neighbours-ஐ பார்த்து, visited ஆகாதவற்றை queue-ல் போடுங்கள். Level by level செல்லும், அதனால் unweighted graph-ல் shortest path தரும். Time O(V + E), space O(V).","kannada":"Pattern: visited set ಜೊತೆ queue. Start node ಅನ್ನು queue ನಲ್ಲಿ ಹಾಕಿ visited mark ಮಾಡಿ. Node ತೆಗೆದು, neighbours ನೋಡಿ, visited ಆಗದವುಗಳನ್ನು queue ನಲ್ಲಿ ಹಾಕಿ. Level by level ಹೋಗುತ್ತದೆ, ಆದ್ದರಿಂದ unweighted graph ನಲ್ಲಿ shortest path ನೀಡುತ್ತದೆ. Time O(V + E), space O(V).","malayalam":"Pattern: visited set-ഓടെ queue. Start node queue-ൽ ഇട്ട് visited mark ചെയ്യുക. Node എടുത്ത്, neighbours നോക്കി, visited ആകാത്തവ queue-ൽ ഇടുക. Level by level പോകും, അതുകൊണ്ട് unweighted graph-ൽ shortest path തരും. Time O(V + E), space O(V)."},"simple":{"hinglish":"Simple mein: pehle paas wale, phir unke paas wale. Jaise paani mein lehar failti hai.","english":"Simply: near neighbours first, then their neighbours — like ripples spreading in water."},"example":"Example: graph 1 connected to 2 and 3, 2 connected to 4. BFS from 1 visits 1, 2, 3, then 4."},{"topic":"Depth-First Search (DFS)","category":"Graphs","difficulty":"Medium","keywords":["depth first search","dfs","depth-first","dfs graph","depth first traversal"],"answers":{"hinglish":"Pattern hai recursion ya stack with visited set. Ek path par jitna gehra ja sakte ho jao, phir peeche aao aur doosra path try karo. Visited set zaroori hai, nahi toh cycle mein ghoomte rahoge. DFS cycle detect karne, connected components ginne, aur topological sort jaise kaamon mein kaam aata hai. Time hai O of vertices plus edges, space O of vertices recursion stack ke liye. Trade-off: DFS shortest path ki guarantee nahi deta, woh BFS ka kaam hai. Lekin DFS kam memory mein chalta hai aur backtracking wale problems mein natural hai.","english":"The pattern is recursion or a stack with a visited set. Go as deep as you can along one path, then backtrack and try another. A visited set is essential, or you will loop forever in a cycle. DFS is used for cycle detection, counting connected components, and topological sort. Time is O of vertices plus edges, space O of vertices for the recursion stack. The trade-off: DFS does not guarantee the shortest path — that is BFS's job. But DFS uses less memory and feels natural for backtracking problems.","telugu":"Pattern: visited set తో recursion లేదా stack. ఒక path లో వీలైనంత లోతుగా వెళ్లి, వెనక్కి వచ్చి మరో path try చేయండి. Cycle detection, connected components కి ఉపయోగపడుతుంది. Time O(V + E), space O(V). Shortest path guarantee ఇవ్వదు — అది BFS పని.","tamil":"Pattern: visited set உடன் recursion அல்லது stack. ஒரு path-ல் முடிந்தவரை ஆழமாகச் சென்று, பின்னே வந்து வேறு path try செய்யுங்கள். Cycle detection, connected components-க்கு பயன்படும். Time O(V + E), space O(V). Shortest path guarantee தராது — அது BFS வேலை.","kannada":"Pattern: visited set ಜೊತೆ recursion ಅಥವಾ stack. ಒಂದು path ನಲ್ಲಿ ಸಾಧ್ಯವಾದಷ್ಟು ಆಳಕ್ಕೆ ಹೋಗಿ, ಹಿಂದಕ್ಕೆ ಬಂದು ಇನ್ನೊಂದು path try ಮಾಡಿ. Cycle detection, connected components ಗೆ ಉಪಯುಕ್ತ. Time O(V + E), space O(V). Shortest path guarantee ನೀಡುವುದಿಲ್ಲ — ಅದು BFS ಕೆಲಸ.","malayalam":"Pattern: visited set-ഓടെ recursion അല്ലെങ്കിൽ stack. ഒരു path-ൽ കഴിയുന്നത്ര ആഴത്തിൽ പോയി, തിരികെ വന്ന് മറ്റൊരു path try ചെയ്യുക. Cycle detection, connected components എന്നിവയ്ക്ക് ഉപയോഗപ്രദം. Time O(V + E), space O(V). Shortest path guarantee തരില്ല — അത് BFS-ന്റെ ജോലിയാണ്."},"simple":{"hinglish":"Simple mein: ek raaste par aakhir tak jao, phir wapas aake doosra raasta lo. Gaye hue jagah par dobara mat jao.","english":"Simply: follow one road to its end, backtrack, and try the next road. Never revisit a place you have seen."},"example":"Example: graph 1 connected to 2 and 3, 2 connected to 4. DFS from 1 can visit 1, 2, 4, then 3."},{"topic":"Number of Islands","category":"Graphs","difficulty":"Medium","keywords":["number of islands","islands","count islands","number islands","island count","connected islands"],"answers":{"hinglish":"Pattern hai grid DFS or BFS with visited marking. Grid ke har cell par jao. Agar cell land hai aur visited nahi hai, toh count ek badhao aur us poore island ko flood fill se visited mark kar do. Flood fill matlab upar neeche baayein daayein ke land cells ko bhi visited karna, jab tak island khatm na ho. Diagonal count nahi hota, sirf chaar disha. Time hai O of rows into columns, space O of rows into columns worst case recursion ke liye. Trade-off: grid ko hi visited mark karke badalna space bachata hai, lekin input badal deta hai. Alag visited set input ko safe rakhta hai, par extra memory leta hai.","english":"The pattern is grid DFS or BFS with visited marking. Scan every cell. If a cell is land and unvisited, increase the count and flood-fill the whole island as visited. Flood fill means marking the land cells up, down, left, and right, until the island ends. Diagonals do not count, only four directions. Time is O of rows times columns, space O of rows times columns in the worst case for recursion. The trade-off: marking the grid itself saves space but mutates the input. A separate visited set keeps the input safe but costs extra memory.","telugu":"Pattern: visited marking తో grid DFS లేదా BFS. ప్రతి cell చూడండి; land అయి, visited కాకపోతే count పెంచి, ఆ island మొత్తం flood fill చేయండి. నాలుగు దిశలు మాత్రమే — diagonal లెక్కలోకి రాదు. Time O(rows x cols). Grid నే mark చేస్తే space ఆదా, కానీ input మారిపోతుంది.","tamil":"Pattern: visited marking உடன் grid DFS அல்லது BFS. ஒவ்வொரு cell-ஐயும் பாருங்கள்; land ஆகவும் visited ஆகாமலும் இருந்தால் count-ஐ அதிகரித்து, அந்த island முழுவதையும் flood fill செய்யுங்கள். நான்கு திசைகள் மட்டும் — diagonal கணக்கில் வராது. Time O(rows x cols). Grid-ஐயே mark செய்தால் space மிச்சம், ஆனால் input மாறிவிடும்.","kannada":"Pattern: visited marking ಜೊತೆ grid DFS ಅಥವಾ BFS. ಪ್ರತಿ cell ನೋಡಿ; land ಆಗಿ, visited ಆಗದಿದ್ದರೆ count ಹೆಚ್ಚಿಸಿ, ಆ island ಪೂರ್ತಿ flood fill ಮಾಡಿ. ನಾಲ್ಕು ದಿಕ್ಕುಗಳು ಮಾತ್ರ — diagonal ಲೆಕ್ಕಕ್ಕೆ ಬರುವುದಿಲ್ಲ. Time O(rows x cols). Grid ಅನ್ನು mark ಮಾಡಿದರೆ space ಉಳಿಯುತ್ತದೆ, ಆದರೆ input ಬದಲಾಗುತ್ತದೆ.","malayalam":"Pattern: visited marking-ഓടെ grid DFS അല്ലെങ്കിൽ BFS. ഓരോ cell-ഉം നോക്കുക; land ആയും visited ആകാതെയും ആണെങ്കിൽ count കൂട്ടി, ആ island മുഴുവൻ flood fill ചെയ്യുക. നാല് ദിശകൾ മാത്രം — diagonal കണക്കിൽ വരില്ല. Time O(rows x cols). Grid തന്നെ mark ചെയ്താൽ space ലാഭം, പക്ഷേ input മാറും."},"simple":{"hinglish":"Simple mein: naya land mila toh ek island gino, phir usse jude saare land ko rang do taaki dobara na gino.","english":"Simply: when you find fresh land, count one island, then paint the whole connected patch so you never count it twice."},"example":"Example: grid [[1,1,0],[1,0,0],[0,0,1]] -> 2 islands."},{"topic":"Climbing Stairs","category":"Dynamic Programming","difficulty":"Easy","keywords":["climbing stairs","climb stairs","stairs","climbing staircase","ways to climb stairs"],"answers":{"hinglish":"Pattern hai dynamic programming with Fibonacci recurrence. Nth step tak pahunchne ke tareeke, n minus 1 se ek step aur n minus 2 se do step ke tareekon ka sum hote hain. Matlab dp of n equals dp of n minus 1 plus dp of n minus 2. Sirf pichhle do values chahiye, isliye do variables kaafi hain. Time hai O of n, space O of 1. Trade-off: plain recursion bina memo ke exponential hoti hai, kyunki wahi subproblems baar baar solve hote hain. DP mein har subproblem ek baar solve hota hai. Ye DP samajhne ka sabse aasan pehla problem hai.","english":"The pattern is dynamic programming with a Fibonacci recurrence. The ways to reach step n equal the ways to reach n minus 1 plus the ways to reach n minus 2. That is, dp of n equals dp of n minus 1 plus dp of n minus 2. Only the last two values are needed, so two variables are enough. Time is O of n, space O of 1. The trade-off: plain recursion without memoisation is exponential, because the same subproblems are solved again and again. With DP, each subproblem is solved once. This is the easiest first DP problem.","telugu":"Pattern: Fibonacci recurrence తో DP. dp(n) = dp(n-1) + dp(n-2). గత రెండు values మాత్రమే కావాలి, అందుకే రెండు variables చాలు. Time O(n), space O(1). Memo లేని recursion exponential అవుతుంది — అదే subproblems మళ్ళీ మళ్ళీ solve అవుతాయి. DP లో ప్రతిదీ ఒక్కసారే.","tamil":"Pattern: Fibonacci recurrence உடன் DP. dp(n) = dp(n-1) + dp(n-2). கடைசி இரண்டு values மட்டும் போதும், அதனால் இரண்டு variables போதும். Time O(n), space O(1). Memo இல்லாத recursion exponential ஆகும் — அதே subproblems மீண்டும் மீண்டும் solve ஆகும். DP-ல் ஒவ்வொன்றும் ஒரு முறைதான்.","kannada":"Pattern: Fibonacci recurrence ಜೊತೆ DP. dp(n) = dp(n-1) + dp(n-2). ಕೊನೆಯ ಎರಡು values ಮಾತ್ರ ಬೇಕು, ಆದ್ದರಿಂದ ಎರಡು variables ಸಾಕು. Time O(n), space O(1). Memo ಇಲ್ಲದ recursion exponential ಆಗುತ್ತದೆ — ಅದೇ subproblems ಮತ್ತೆ ಮತ್ತೆ solve ಆಗುತ್ತವೆ. DP ನಲ್ಲಿ ಪ್ರತಿಯೊಂದೂ ಒಮ್ಮೆ ಮಾತ್ರ.","malayalam":"Pattern: Fibonacci recurrence-ഓടെ DP. dp(n) = dp(n-1) + dp(n-2). അവസാന രണ്ട് values മാത്രം മതി, അതുകൊണ്ട് രണ്ട് variables മതി. Time O(n), space O(1). Memo ഇല്ലാത്ത recursion exponential ആകും — അതേ subproblems വീണ്ടും വീണ്ടും solve ആകും. DP-യിൽ ഓരോന്നും ഒരിക്കൽ മാത്രം."},"simple":{"hinglish":"Simple mein: aakhri step par do taraf se aa sakte ho, ek peeche se ya do peeche se. Dono ke tareeke jod do.","english":"Simply: you can arrive at the last step from one step back or two steps back. Add those two counts."},"example":"Example: n = 2 -> 2 ways (1+1, 2). n = 3 -> 3 ways (1+1+1, 1+2, 2+1)."},{"topic":"House Robber","category":"Dynamic Programming","difficulty":"Medium","keywords":["house robber","house robbery","rob houses","robber","maximum loot houses"],"answers":{"hinglish":"Pattern hai DP with take or skip. Har ghar par do choice hain: is ghar ko looto aur pichhle ghar ko chhodo, ya is ghar ko chhodo aur pichhle tak ka best lo. Matlab dp of i equals max of dp of i minus 1, aur dp of i minus 2 plus current value. Sirf pichhle do values chahiye. Time hai O of n, space O of 1. Trade-off: har combination try karna exponential hota hai. DP mein decision sirf pichhle do gharon par depend karta hai, isliye ek pass kaafi hai. Interview mein ye batana zaroori hai ki paas paas wale ghar lootna mana hai, wahi constraint recurrence banata hai.","english":"The pattern is DP with take or skip. At each house you have two choices: rob this house and skip the previous one, or skip this house and keep the previous best. So dp of i equals the max of dp of i minus 1, and dp of i minus 2 plus the current value. Only the last two values are needed. Time is O of n, space O of 1. The trade-off: trying every combination is exponential. In DP, each decision depends only on the previous two houses, so one pass is enough. In an interview, state the constraint clearly: adjacent houses cannot both be robbed — that constraint creates the recurrence.","telugu":"Pattern: take or skip తో DP. ప్రతి ఇంటి దగ్గర రెండు choices: ఈ ఇల్లు దోచుకుని ముందు ఇల్లు వదలడం, లేదా ఈ ఇల్లు వదిలి ముందు best తీసుకోవడం. dp(i) = max(dp(i-1), dp(i-2) + value). Time O(n), space O(1). పక్కపక్క ఇళ్ళు రెండూ దోచుకోకూడదు — అదే constraint.","tamil":"Pattern: take or skip உடன் DP. ஒவ்வொரு வீட்டிலும் இரண்டு choices: இந்த வீட்டை கொள்ளையடித்து முந்தைய வீட்டை விடுவது, அல்லது இந்த வீட்டை விட்டு முந்தைய best-ஐ எடுப்பது. dp(i) = max(dp(i-1), dp(i-2) + value). Time O(n), space O(1). பக்கத்து வீடுகள் இரண்டையும் கொள்ளையடிக்க முடியாது — அதுதான் constraint.","kannada":"Pattern: take or skip ಜೊತೆ DP. ಪ್ರತಿ ಮನೆಯಲ್ಲಿ ಎರಡು choices: ಈ ಮನೆಯನ್ನು ದೋಚಿ ಹಿಂದಿನ ಮನೆಯನ್ನು ಬಿಡುವುದು, ಅಥವಾ ಈ ಮನೆಯನ್ನು ಬಿಟ್ಟು ಹಿಂದಿನ best ತೆಗೆದುಕೊಳ್ಳುವುದು. dp(i) = max(dp(i-1), dp(i-2) + value). Time O(n), space O(1). ಪಕ್ಕಪಕ್ಕದ ಮನೆಗಳೆರಡನ್ನೂ ದೋಚುವಂತಿಲ್ಲ — ಅದೇ constraint.","malayalam":"Pattern: take or skip-ഓടെ DP. ഓരോ വീട്ടിലും രണ്ട് choices: ഈ വീട് കൊള്ളയടിച്ച് മുൻ വീട് വിടുക, അല്ലെങ്കിൽ ഈ വീട് വിട്ട് മുൻ best എടുക്കുക. dp(i) = max(dp(i-1), dp(i-2) + value). Time O(n), space O(1). അടുത്തടുത്ത വീടുകൾ രണ്ടും കൊള്ളയടിക്കാൻ പാടില്ല — അതാണ് constraint."},"simple":{"hinglish":"Simple mein: har ghar par socho, lootoon ya chhodoon. Lootna hai toh pichhla chhodo, nahi toh pichhla best le lo.","english":"Simply: at each house, rob it and skip the last, or skip it and keep the last best. Take whichever is bigger."},"example":"Example: nums = [2,7,9,3,1] -> rob houses 2, 9, 1 = 12."},{"topic":"Coin Change","category":"Dynamic Programming","difficulty":"Medium","keywords":["coin change","coinchange","minimum coins","fewest coins","change coins"],"answers":{"hinglish":"Pattern hai DP over amount. Har amount ke liye minimum coins nikaalo, har coin ko aakhri coin maan ke. Matlab dp of amount equals one plus minimum of dp of amount minus coin, saare coins ke liye. Base case dp zero equals zero hai, impossible amounts ko infinity rakho. Time hai O of amount into number of coins, space O of amount. Trade-off: greedy, matlab hamesha sabse bada coin lena, har coin system mein kaam nahi karta. DP har coin system mein sahi jawab deta hai, bas table bharna padta hai.","english":"The pattern is DP over the amount. For each amount, find the minimum coins by trying every coin as the last coin. So dp of amount equals one plus the minimum of dp of amount minus coin, over all coins. The base case is dp of zero equals zero, and impossible amounts stay at infinity. Time is O of amount times number of coins, space O of amount. The trade-off: greedy, always taking the largest coin, fails for some coin systems. DP gives the right answer for any coin system, at the cost of filling a table.","telugu":"Pattern: amount పై DP. ప్రతి amount కి, ప్రతి coin ని చివరి coin గా try చేసి minimum coins కనుగొనండి. dp(amount) = 1 + min(dp(amount - coin)). Time O(amount x coins), space O(amount). Greedy అన్ని coin systems లో పనిచేయదు; DP ఎప్పుడూ సరైన answer ఇస్తుంది.","tamil":"Pattern: amount மீது DP. ஒவ்வொரு amount-க்கும், ஒவ்வொரு coin-ஐயும் கடைசி coin ஆக try செய்து minimum coins கண்டறியுங்கள். dp(amount) = 1 + min(dp(amount - coin)). Time O(amount x coins), space O(amount). Greedy எல்லா coin systems-லும் வேலை செய்யாது; DP எப்போதும் சரியான answer தரும்.","kannada":"Pattern: amount ಮೇಲೆ DP. ಪ್ರತಿ amount ಗೆ, ಪ್ರತಿ coin ಅನ್ನು ಕೊನೆಯ coin ಆಗಿ try ಮಾಡಿ minimum coins ಕಂಡುಹಿಡಿಯಿರಿ. dp(amount) = 1 + min(dp(amount - coin)). Time O(amount x coins), space O(amount). Greedy ಎಲ್ಲಾ coin systems ನಲ್ಲಿ ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ; DP ಯಾವಾಗಲೂ ಸರಿಯಾದ answer ನೀಡುತ್ತದೆ.","malayalam":"Pattern: amount-ന് മുകളിൽ DP. ഓരോ amount-നും, ഓരോ coin-നെയും അവസാന coin ആയി try ചെയ്ത് minimum coins കണ്ടെത്തുക. dp(amount) = 1 + min(dp(amount - coin)). Time O(amount x coins), space O(amount). Greedy എല്ലാ coin systems-ലും പ്രവർത്തിക്കില്ല; DP എപ്പോഴും ശരിയായ answer തരും."},"simple":{"hinglish":"Simple mein: chhote amount se shuru karo, har amount ke liye har coin try karo, sabse kam coins wala jawab rakho.","english":"Simply: build up from small amounts, try every coin for each amount, and keep the fewest coins."},"example":"Example: coins = [1,2,5], amount = 11 -> 3 coins (5+5+1). Amount = 3, coins = [2] -> impossible, -1."},{"topic":"Quick Sort","category":"Sorting","difficulty":"Medium","keywords":["quick sort","quicksort","quick-sort","partition sort","quicksort algorithm","क्विक सॉर्ट","క్విక్ సార్ట్","குயிக் சார்ட்","ಕ್ವಿಕ್ ಸಾರ್ಟ್","ക്വിക്ക് സോർട്ട്"],"answers":{"hinglish":"Pattern hai divide and conquer with partition. Ek pivot chuno, array ko rearrange karo taaki pivot se chhote elements baayein aur bade daayein aa jayein. Phir dono halves par wahi kaam dobara karo. Partition hi asli kaam hai, baaki recursion hai. Average time hai O of n log n, worst case O of n square jab pivot hamesha sabse chhota ya sabse bada ho, jaise sorted array mein pehla element pivot ho. Space hai O of log n recursion stack ke liye. Trade-off: merge sort se tez hota hai practice mein aur in place hota hai, lekin stable nahi hai aur worst case bura ho sakta hai. Random pivot worst case se bachata hai.","english":"The pattern is divide and conquer with partitioning. Pick a pivot, rearrange the array so smaller elements go left and larger ones go right. Then repeat on both halves. Partitioning is the real work; the rest is recursion. Average time is O of n log n, worst case O of n squared when the pivot is always the smallest or largest, such as the first element of a sorted array. Space is O of log n for the recursion stack. The trade-off: it is fast in practice and in place, but not stable, and the worst case is bad. A random pivot avoids the worst case.","telugu":"Pattern: partition తో divide and conquer. Pivot ఎంచుకుని, చిన్న elements ఎడమ, పెద్ద elements కుడి వైపు వచ్చేలా rearrange చేయండి, తర్వాత రెండు halves పై మళ్ళీ చేయండి. Average time O(n log n), worst case O(n square). Space O(log n). Random pivot worst case నుంచి కాపాడుతుంది.","tamil":"Pattern: partition உடன் divide and conquer. Pivot தேர்ந்து, சிறிய elements இடது, பெரிய elements வலது பக்கம் வருமாறு rearrange செய்யுங்கள், பிறகு இரண்டு halves-லும் மீண்டும் செய்யுங்கள். Average time O(n log n), worst case O(n square). Space O(log n). Random pivot worst case-லிருந்து காக்கும்.","kannada":"Pattern: partition ಜೊತೆ divide and conquer. Pivot ಆರಿಸಿ, ಚಿಕ್ಕ elements ಎಡ, ದೊಡ್ಡ elements ಬಲ ಬದಿಗೆ ಬರುವಂತೆ rearrange ಮಾಡಿ, ನಂತರ ಎರಡು halves ಮೇಲೆ ಮತ್ತೆ ಮಾಡಿ. Average time O(n log n), worst case O(n square). Space O(log n). Random pivot worst case ನಿಂದ ಕಾಪಾಡುತ್ತದೆ.","malayalam":"Pattern: partition-ഓടെ divide and conquer. Pivot തിരഞ്ഞെടുത്ത്, ചെറിയ elements ഇടത്, വലിയ elements വലത് വശത്ത് വരുംവിധം rearrange ചെയ്യുക, പിന്നീട് രണ്ട് halves-ലും വീണ്ടും ചെയ്യുക. Average time O(n log n), worst case O(n square). Space O(log n). Random pivot worst case-ൽ നിന്ന് രക്ഷിക്കും."},"simple":{"hinglish":"Simple mein: ek pivot lo, chhote baayein, bade daayein, phir dono taraf wahi karo.","english":"Simply: pick a pivot, put smaller elements left and larger right, then do the same on both sides."},"example":"Example: [3,6,8,10,1,2,1] with pivot 3 -> left [1,2,1], pivot 3, right [6,8,10], then sort each side."},{"topic":"Merge Sort","category":"Sorting","difficulty":"Medium","keywords":["merge sort","mergesort","merge-sort","merge sort algorithm","मर्ज सॉर्ट","మెర్జ్ సార్ట్","மெர்ஜ் சார்ட்","ಮರ್ಜ್ ಸಾರ್ಟ್","മെർജ് സോർട്ട്"],"answers":{"hinglish":"Pattern hai divide and conquer with merge. Array ko aadha aadha baant-te jao jab tak har hissa ek element ka na ho jaye, phir sorted order mein wapas jodo. Merge step mein do sorted halves ko compare karke ek sorted list banate hain. Divide karna aasan hai, merge karna asli kaam hai. Time hamesha O of n log n hota hai, best worst average sab mein. Space hai O of n merge ke liye extra array ke kaaran. Trade-off: quick sort se predictable hai aur stable hai, lekin extra memory leta hai aur practice mein thoda slow ho sakta hai. Linked list par merge sort khaas taur par achha hai, kyunki wahan merge O of 1 space mein hota hai.","english":"The pattern is divide and conquer with merging. Keep splitting the array in half until each piece has one element, then merge the pieces back in sorted order. The merge step compares two sorted halves to build one sorted list. Splitting is easy; merging is the real work. Time is always O of n log n, in the best, worst, and average cases. Space is O of n for the extra merge array. The trade-off: it is predictable and stable, unlike quick sort, but it uses extra memory and can be slower in practice. On linked lists it shines, because merging there takes O of 1 extra space.","telugu":"Pattern: merge తో divide and conquer. Array ని సగం సగం విభజిస్తూ వెళ్లి, తర్వాత sorted order లో తిరిగి కలపండి. Merge step లో రెండు sorted halves ని compare చేసి ఒక sorted list తయారుచేస్తారు. Time ఎప్పుడూ O(n log n), space O(n). Stable, కానీ extra memory పడుతుంది.","tamil":"Pattern: merge உடன் divide and conquer. Array-ஐ பாதி பாதியாகப் பிரித்து, பிறகு sorted order-ல் மீண்டும் இணைக்கவும். Merge step-ல் இரண்டு sorted halves-ஐ compare செய்து ஒரு sorted list உருவாக்குகிறோம். Time எப்போதும் O(n log n), space O(n). Stable, ஆனால் extra memory ஆகும்.","kannada":"Pattern: merge ಜೊತೆ divide and conquer. Array ಅನ್ನು ಅರ್ಧ ಅರ್ಧ ವಿಭಜಿಸುತ್ತಾ ಹೋಗಿ, ನಂತರ sorted order ನಲ್ಲಿ ಮತ್ತೆ ಸೇರಿಸಿ. Merge step ನಲ್ಲಿ ಎರಡು sorted halves ಅನ್ನು compare ಮಾಡಿ ಒಂದು sorted list ಮಾಡುತ್ತಾರೆ. Time ಯಾವಾಗಲೂ O(n log n), space O(n). Stable, ಆದರೆ extra memory ಬೇಕು.","malayalam":"Pattern: merge-ഓടെ divide and conquer. Array പകുതി പകുതിയായി വിഭജിച്ച്, പിന്നീട് sorted order-ൽ വീണ്ടും ചേർക്കുക. Merge step-ൽ രണ്ട് sorted halves compare ചെയ്ത് ഒരു sorted list ഉണ്ടാക്കുന്നു. Time എപ്പോഴും O(n log n), space O(n). Stable, പക്ഷേ extra memory വേണം."},"simple":{"hinglish":"Simple mein: baanto, baanto, phir sorted order mein jodo. Jodna hi asli kaam hai.","english":"Simply: split, split, then join back in sorted order. The joining is the real work."},"example":"Example: [38,27,43,3] -> split to [38],[27],[43],[3] -> merge to [27,38],[3,43] -> [3,27,38,43]."},{"topic":"Kth Largest Element","category":"Heap","difficulty":"Medium","keywords":["kth largest","kth largest element","k largest","kth smallest","kth largest element in array","find kth largest"],"answers":{"hinglish":"Pattern hai min-heap of size k. Heap mein pehle k elements daalo, phir baaki har element ke liye dekho: agar element heap ke top se bada hai toh top hatao aur naya daalo. Aakhir mein heap ka top hi kth largest hota hai, kyunki heap mein sirf sabse bade k elements bache hote hain. Time hai O of n log k, space O of k. Trade-off: poora array sort karna O of n log n leta hai, heap wala tareeka behtar hai jab k chhota ho. Quickselect O of n average mein bhi kar sakta hai, lekin worst case aur samajhna mushkil hai. Heap wala solution interview mein safe aur saaf hai.","english":"The pattern is a min-heap of size k. Put the first k elements in the heap, then for each remaining element: if it is larger than the heap top, remove the top and insert it. At the end, the heap top is the kth largest, because the heap holds only the k largest elements. Time is O of n log k, space O of k. The trade-off: sorting the whole array costs O of n log n; the heap method is better when k is small. Quickselect averages O of n but is harder to explain and has a bad worst case. The heap solution is the safe, clean interview answer.","telugu":"Pattern: size k గల min-heap. మొదటి k elements heap లో వేసి, మిగిలిన ప్రతి element heap top కన్నా పెద్దదైతే top తీసేసి కొత్తది వేయండి. చివర్లో heap top ఏ kth largest. Time O(n log k), space O(k). Sort చేస్తే O(n log n) పడుతుంది; k చిన్నదైతే heap మంచిది.","tamil":"Pattern: size k உள்ள min-heap. முதல் k elements-ஐ heap-ல் போட்டு, மீதமுள்ள ஒவ்வொரு element-ம் heap top-ஐ விட பெரியதாக இருந்தால் top-ஐ நீக்கி புதியதை போடுங்கள். முடிவில் heap top தான் kth largest. Time O(n log k), space O(k). Sort செய்தால் O(n log n) ஆகும்; k சிறியதாக இருந்தால் heap நல்லது.","kannada":"Pattern: size k ಇರುವ min-heap. ಮೊದಲ k elements ಅನ್ನು heap ನಲ್ಲಿ ಹಾಕಿ, ಉಳಿದ ಪ್ರತಿ element heap top ಗಿಂತ ದೊಡ್ಡದಾಗಿದ್ದರೆ top ತೆಗೆದು ಹೊಸದನ್ನು ಹಾಕಿ. ಕೊನೆಯಲ್ಲಿ heap top ಏ kth largest. Time O(n log k), space O(k). Sort ಮಾಡಿದರೆ O(n log n) ಆಗುತ್ತದೆ; k ಚಿಕ್ಕದಾಗಿದ್ದರೆ heap ಒಳ್ಳೆಯದು.","malayalam":"Pattern: size k ഉള്ള min-heap. ആദ്യ k elements heap-ൽ ഇട്ട്, ബാക്കി ഓരോ element-ഉം heap top-നേക്കാൾ വലുതാണെങ്കിൽ top നീക്കി പുതിയത് ഇടുക. അവസാനം heap top ആണ് kth largest. Time O(n log k), space O(k). Sort ചെയ്താൽ O(n log n) ആകും; k ചെറുതാണെങ്കിൽ heap നല്ലതാണ്."},"simple":{"hinglish":"Simple mein: sirf sabse bade k numbers ka dabba rakho. Dabbe mein sabse chhota wala hi kth largest hai.","english":"Simply: keep a box of only the k biggest numbers. The smallest number in the box is the kth largest."},"example":"Example: nums = [3,2,1,5,6,4], k = 2 -> 5."},{"topic":"Top K Frequent Elements","category":"Heap","difficulty":"Medium","keywords":["top k frequent","top k frequent elements","most frequent","k frequent","frequent elements","top frequent"],"answers":{"hinglish":"Pattern hai hash map plus heap, ya bucket sort. Pehle har element ki frequency gino hash map se. Phir do tareeke hain. Heap wala: frequency ke hisaab se min-heap mein top k rakho, time O of n log k. Bucket wala: frequency ko index banao, har frequency ke liye list rakho, phir peeche se k elements uthao, time O of n. Trade-off: bucket sort tez hai lekin O of n extra space leta hai aur samjhana thoda mushkil hai. Heap wala likhna aasan hai aur aksar acceptable hai. Interview mein pehle heap wala bolo, phir bucket wala optimisation ke roop mein batao.","english":"The pattern is a hash map plus a heap, or bucket sort. First count each element's frequency with a hash map. Then two options. Heap: keep the top k by frequency in a min-heap, time O of n log k. Bucket: index lists by frequency, then collect k elements from the back, time O of n. The trade-off: bucket sort is faster but takes O of n extra space and is trickier to explain. The heap version is easier to write and usually acceptable. In an interview, state the heap version first, then offer bucket sort as the optimisation.","telugu":"Pattern: hash map + heap, లేదా bucket sort. ముందు ప్రతి element frequency లెక్కించండి. Heap తో top k ఉంచితే O(n log k); bucket sort తో O(n). Bucket వేగంగా ఉంటుంది, కానీ O(n) space పడుతుంది. Interview లో ముందు heap చెప్పి, తర్వాత bucket optimisation గా చెప్పండి.","tamil":"Pattern: hash map + heap, அல்லது bucket sort. முதலில் ஒவ்வொரு element-ன் frequency-ஐ எண்ணுங்கள். Heap கொண்டு top k வைத்தால் O(n log k); bucket sort கொண்டு O(n). Bucket வேகமானது, ஆனால் O(n) space ஆகும். Interview-ல் முதலில் heap சொல்லி, பிறகு bucket optimisation ஆக சொல்லுங்கள்.","kannada":"Pattern: hash map + heap, ಅಥವಾ bucket sort. ಮೊದಲು ಪ್ರತಿ element ನ frequency ಎಣಿಸಿ. Heap ಜೊತೆ top k ಇಟ್ಟರೆ O(n log k); bucket sort ಜೊತೆ O(n). Bucket ವೇಗವಾಗಿದೆ, ಆದರೆ O(n) space ಬೇಕು. Interview ನಲ್ಲಿ ಮೊದಲು heap ಹೇಳಿ, ನಂತರ bucket optimisation ಆಗಿ ಹೇಳಿ.","malayalam":"Pattern: hash map + heap, അല്ലെങ്കിൽ bucket sort. ആദ്യം ഓരോ element-ന്റെ frequency എണ്ണുക. Heap കൊണ്ട് top k വച്ചാൽ O(n log k); bucket sort കൊണ്ട് O(n). Bucket വേഗമാണ്, പക്ഷേ O(n) space വേണം. Interview-ൽ ആദ്യം heap പറഞ്ഞ്, പിന്നീട് bucket optimisation ആയി പറയുക."},"simple":{"hinglish":"Simple mein: pehle gino kaun kitni baar aaya, phir sabse zyada baar aane wale k ko uthao.","english":"Simply: count how often each value appears, then pick the k most common ones."},"example":"Example: nums = [1,1,1,2,2,3], k = 2 -> [1,2]."}],"STOPWORDS_APPROACHES":["a","about","an","do","does","explain","for","how","in","is","me","of","tell","the","to","what"],"ALGORITHMS":[{"name":"Two Sum","category":"Arrays & Searching","aliases":["two sum","2 sum","pair sum","target sum","two numbers sum","to sum","do sum","टू सम","do number ka sum","టూ సమ్","டூ சம்","ಟೂ ಸಮ್","ടൂ സം"],"key_logic":"Find two numbers that add up to the target. The trick is remembering numbers you have already seen, so each lookup is instant.","approaches":[{"name":"Brute force","logic":"Check every pair of numbers until one adds up to the target. Simple, but repeats the same comparisons.","code":"int[] twoSum(int[] nums, int target) {\n    for (int i = 0; i < nums.length; i++)\n        for (int j = i + 1; j < nums.length; j++)\n            if (nums[i] + nums[j] == target)\n                return new int[]{i, j};\n    return new int[]{-1, -1};\n}","time":"O(n²)","space":"O(1)","optimal":false},{"name":"Hash map","logic":"One pass: for each number, check whether its partner (target minus current) was already seen. The map remembers past numbers, so no re-searching.","code":"int[] twoSum(int[] nums, int target) {\n    Map<Integer, Integer> seen = new HashMap<>();\n    for (int i = 0; i < nums.length; i++) {\n        int need = target - nums[i];\n        if (seen.containsKey(need))\n            return new int[]{seen.get(need), i};\n        seen.put(nums[i], i);\n    }\n    return new int[]{-1, -1};\n}","time":"O(n)","space":"O(n)","optimal":true},{"name":"Two pointers (sorted array)","logic":"Sort first, then squeeze from both ends: sum too small, move left; too big, move right. Loses the original indices, so only use it when the values (not positions) matter.","code":"// Works on a SORTED array; original indices are lost.\nint[] twoSum(int[] nums, int target) {\n    int l = 0, r = nums.length - 1;\n    while (l < r) {\n        int sum = nums[l] + nums[r];\n        if (sum == target) return new int[]{l, r};\n        if (sum < target) l++; else r--;\n    }\n    return new int[]{-1, -1};\n}","time":"O(n log n)","space":"O(1)","optimal":false}]},{"name":"3Sum","category":"Arrays & Searching","aliases":["3sum","three sum","triplet sum zero","3 sum","थ्री सम","teen number","triplet","త్రీ సమ్","த்ரீ சம்","ತ್ರೀ ಸಮ್","ത്രീ സം"],"key_logic":"Find all unique triplets that sum to zero. Sort first, then fix one number and two-pointer the rest.","approaches":[{"name":"Brute force","logic":"Three nested loops try every triplet, then a set removes duplicates. Easy to write, far too slow for interviews.","code":"List<List<Integer>> threeSum(int[] nums) {\n    Set<List<Integer>> found = new HashSet<>();\n    for (int i = 0; i < nums.length; i++)\n        for (int j = i + 1; j < nums.length; j++)\n            for (int k = j + 1; k < nums.length; k++)\n                if (nums[i] + nums[j] + nums[k] == 0) {\n                    List<Integer> t = Arrays.asList(nums[i], nums[j], nums[k]);\n                    Collections.sort(t);\n                    found.add(t);\n                }\n    return new ArrayList<>(found);\n}","time":"O(n³)","space":"O(n)","optimal":false},{"name":"Sort + two pointers","logic":"Sort, fix the first number, then squeeze the other two with pointers. Skipping equal neighbours removes duplicates without a set.","code":"List<List<Integer>> threeSum(int[] nums) {\n    Arrays.sort(nums);\n    List<List<Integer>> ans = new ArrayList<>();\n    for (int i = 0; i < nums.length - 2; i++) {\n        if (i > 0 && nums[i] == nums[i - 1]) continue;\n        int l = i + 1, r = nums.length - 1;\n        while (l < r) {\n            int sum = nums[i] + nums[l] + nums[r];\n            if (sum == 0) {\n                ans.add(List.of(nums[i], nums[l], nums[r]));\n                while (l < r && nums[l] == nums[l + 1]) l++;\n                while (l < r && nums[r] == nums[r - 1]) r--;\n                l++; r--;\n            } else if (sum < 0) l++;\n            else r--;\n        }\n    }\n    return ans;\n}","time":"O(n²)","space":"O(1)","optimal":true},{"name":"Hash set pairs","logic":"Fix the first number, then use a hash set to find pairs summing to its negative. Same time as two pointers but needs extra memory and a set for dedup.","code":"List<List<Integer>> threeSum(int[] nums) {\n    Set<List<Integer>> found = new HashSet<>();\n    for (int i = 0; i < nums.length; i++) {\n        Set<Integer> seen = new HashSet<>();\n        for (int j = i + 1; j < nums.length; j++) {\n            int need = -(nums[i] + nums[j]);\n            if (seen.contains(need)) {\n                List<Integer> t = Arrays.asList(nums[i], nums[j], need);\n                Collections.sort(t);\n                found.add(t);\n            }\n            seen.add(nums[j]);\n        }\n    }\n    return new ArrayList<>(found);\n}","time":"O(n²)","space":"O(n)","optimal":false}]},{"name":"Container With Most Water","category":"Arrays & Searching","aliases":["container with most water","most water","max water container","trapping water container","container","पानी","paani","max water","max area","കണ്ടെയ്നർ","கன்டெய்னர்","కంటైనర్","ಕಂಟೈನರ್"],"key_logic":"Two lines hold water: area equals distance times the shorter line. Start wide, and always move the shorter side — moving the taller side can never help.","approaches":[{"name":"Brute force","logic":"Compute the area for every pair of lines and keep the biggest. Correct but quadratic.","code":"int maxArea(int[] height) {\n    int best = 0;\n    for (int i = 0; i < height.length; i++)\n        for (int j = i + 1; j < height.length; j++)\n            best = Math.max(best, (j - i) * Math.min(height[i], height[j]));\n    return best;\n}","time":"O(n²)","space":"O(1)","optimal":false},{"name":"Two pointers","logic":"Start at both ends (widest container). Record the area, then move the shorter line inward — only a taller line can beat the current area.","code":"int maxArea(int[] height) {\n    int l = 0, r = height.length - 1, best = 0;\n    while (l < r) {\n        best = Math.max(best, (r - l) * Math.min(height[l], height[r]));\n        if (height[l] < height[r]) l++; else r--;\n    }\n    return best;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Best Time to Buy and Sell Stock","category":"Arrays & Searching","aliases":["buy sell stock","best time buy sell","stock profit","maximum profit stock","stock","स्टॉक","share","शेयर","kharid","bech","profit","buy and sell","షేర్","ஷேர்","ಶೇರ್","ഷെയർ","స్టాక్","ஸ்டாக்","ಸ್ಟಾಕ್","സ്റ്റോക്ക്"],"key_logic":"Track the lowest price seen so far; the best profit today is today's price minus that minimum. One pass is enough.","approaches":[{"name":"Brute force","logic":"Try every buy day with every later sell day and keep the best profit. Simple, quadratic.","code":"int maxProfit(int[] prices) {\n    int best = 0;\n    for (int i = 0; i < prices.length; i++)\n        for (int j = i + 1; j < prices.length; j++)\n            best = Math.max(best, prices[j] - prices[i]);\n    return best;\n}","time":"O(n²)","space":"O(1)","optimal":false},{"name":"One pass (track minimum)","logic":"Walk once, remembering the cheapest price so far. Each day, either update the cheapest price or record a better profit.","code":"int maxProfit(int[] prices) {\n    int cheapest = Integer.MAX_VALUE, best = 0;\n    for (int p : prices) {\n        cheapest = Math.min(cheapest, p);\n        best = Math.max(best, p - cheapest);\n    }\n    return best;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Product of Array Except Self","category":"Arrays & Searching","aliases":["product except self","product of array except self","product without division","except self","guna","गुणा","product of array","ప్రోడక్ట్","ப்ராடக்ட்","ಪ್ರಾಡಕ್ಟ್","പ്രോഡക്റ്റ്"],"key_logic":"Each answer is (product of everything to the left) times (product of everything to the right). Two passes, no division — so zeroes never break it.","approaches":[{"name":"Division","logic":"Multiply everything, then divide by each element. Breaks the moment the array contains a zero (and division is banned by the problem).","code":"// WRONG when any element is zero. Shown only to explain why not.\nint[] productExceptSelf(int[] nums) {\n    int total = 1;\n    for (int n : nums) total *= n;\n    int[] ans = new int[nums.length];\n    for (int i = 0; i < nums.length; i++) ans[i] = total / nums[i];\n    return ans;\n}","time":"O(n)","space":"O(1)","optimal":false},{"name":"Prefix and suffix arrays","logic":"Build a left-products array and a right-products array, then multiply them per index. Clear, but uses two extra arrays.","code":"int[] productExceptSelf(int[] nums) {\n    int n = nums.length;\n    int[] left = new int[n], right = new int[n], ans = new int[n];\n    left[0] = 1;\n    for (int i = 1; i < n; i++) left[i] = left[i - 1] * nums[i - 1];\n    right[n - 1] = 1;\n    for (int i = n - 2; i >= 0; i--) right[i] = right[i + 1] * nums[i + 1];\n    for (int i = 0; i < n; i++) ans[i] = left[i] * right[i];\n    return ans;\n}","time":"O(n)","space":"O(n)","optimal":false},{"name":"Output array + running products","logic":"Store left products in the answer array, then sweep back multiplying in the right products with a single running variable. No extra arrays.","code":"int[] productExceptSelf(int[] nums) {\n    int n = nums.length, ans[] = new int[n];\n    ans[0] = 1;\n    for (int i = 1; i < n; i++) ans[i] = ans[i - 1] * nums[i - 1];\n    int right = 1;\n    for (int i = n - 1; i >= 0; i--) {\n        ans[i] *= right;\n        right *= nums[i];\n    }\n    return ans;\n}","time":"O(n)","space":"O(1) extra","optimal":true}]},{"name":"Longest Consecutive Sequence","category":"Arrays & Searching","aliases":["longest consecutive","consecutive sequence","longest consecutive sequence","consecutive","lagatar","लगातार","sequence"],"key_logic":"Only start counting from numbers that begin a run (no n−1 present), so each run is walked exactly once.","approaches":[{"name":"Brute force","logic":"For every number, walk forward checking each next number with a linear search. The same runs get rescanned again and again.","code":"int longestConsecutive(int[] nums) {\n    int best = 0;\n    for (int n : nums) {\n        int cur = n, len = 1;\n        while (contains(nums, cur + 1)) { cur++; len++; }\n        best = Math.max(best, len);\n    }\n    return best;\n}\nboolean contains(int[] nums, int x) {\n    for (int n : nums) if (n == x) return true;\n    return false;\n}","time":"O(n³)","space":"O(1)","optimal":false},{"name":"Sort first","logic":"Sort, then one pass counts runs of consecutive values, skipping duplicates. The sort dominates the time.","code":"int longestConsecutive(int[] nums) {\n    if (nums.length == 0) return 0;\n    Arrays.sort(nums);\n    int best = 1, len = 1;\n    for (int i = 1; i < nums.length; i++) {\n        if (nums[i] == nums[i - 1]) continue;\n        if (nums[i] == nums[i - 1] + 1) len++;\n        else len = 1;\n        best = Math.max(best, len);\n    }\n    return best;\n}","time":"O(n log n)","space":"O(1)","optimal":false},{"name":"Hash set","logic":"Put everything in a set. Only start a run at numbers with no predecessor in the set, then walk forward with O(1) lookups.","code":"int longestConsecutive(int[] nums) {\n    Set<Integer> set = new HashSet<>();\n    for (int n : nums) set.add(n);\n    int best = 0;\n    for (int n : set) {\n        if (!set.contains(n - 1)) {\n            int cur = n, len = 1;\n            while (set.contains(cur + 1)) { cur++; len++; }\n            best = Math.max(best, len);\n        }\n    }\n    return best;\n}","time":"O(n)","space":"O(n)","optimal":true}]},{"name":"Subarray Sum Equals K (Prefix Sum)","category":"Arrays & Searching","aliases":["subarray sum equals k","subarray sum k","subarrays divisible","count subarrays sum k","prefix sum subarray","prefix sum","subarray sum","subarray","सबएरे","sum equals k","sum barabar k","సబ్అరే","சப்அரே","ಸಬ್ಅರೇ","സബ്അറേ"],"key_logic":"Prefix sums turn 'subarray sums to k' into 'have I seen prefix minus k before?' — one hash map pass answers it, even with negative numbers.","approaches":[{"name":"Brute force","logic":"Check every subarray's sum directly. Works, but quadratic and easy to beat.","code":"int subarraySum(int[] nums, int k) {\n    int count = 0;\n    for (int i = 0; i < nums.length; i++) {\n        int sum = 0;\n        for (int j = i; j < nums.length; j++) {\n            sum += nums[j];\n            if (sum == k) count++;\n        }\n    }\n    return count;\n}","time":"O(n²)","space":"O(1)","optimal":false},{"name":"Prefix sum + hash map","logic":"Track the running prefix sum. If (prefix − k) appeared before, every occurrence ends a valid subarray here. Count frequencies in the map.","code":"int subarraySum(int[] nums, int k) {\n    Map<Integer, Integer> freq = new HashMap<>();\n    freq.put(0, 1);\n    int sum = 0, count = 0;\n    for (int n : nums) {\n        sum += n;\n        count += freq.getOrDefault(sum - k, 0);\n        freq.put(sum, freq.getOrDefault(sum, 0) + 1);\n    }\n    return count;\n}","time":"O(n)","space":"O(n)","optimal":true}]},{"name":"Remove Duplicates from Sorted Array","category":"Arrays & Searching","aliases":["remove duplicates","remove duplicates sorted","deduplicate sorted array","remove duplicate","duplicate hatao","डुप्लिकेट","duplicates","డూప్లికేట్","டூப்ளிகேட்","ಡೂಪ್ಲಿಕೇಟ್","ഡ്യൂപ്ലിക്കേറ്റ്"],"key_logic":"The array is sorted, so duplicates sit together. One slow pointer marks the next unique slot; one fast pointer scans.","approaches":[{"name":"Extra array","logic":"Copy unique values into a new array, then copy back. Simple but uses extra memory the problem asks you to avoid.","code":"int removeDuplicates(int[] nums) {\n    if (nums.length == 0) return 0;\n    int[] copy = new int[nums.length];\n    int w = 0;\n    for (int i = 0; i < nums.length; i++)\n        if (i == 0 || nums[i] != nums[i - 1]) copy[w++] = nums[i];\n    System.arraycopy(copy, 0, nums, 0, w);\n    return w;\n}","time":"O(n)","space":"O(n)","optimal":false},{"name":"Two pointers in place","logic":"The slow pointer only advances when the fast pointer finds a new value. Everything before the slow pointer is the deduped answer.","code":"int removeDuplicates(int[] nums) {\n    if (nums.length == 0) return 0;\n    int slow = 0;\n    for (int fast = 1; fast < nums.length; fast++)\n        if (nums[fast] != nums[slow])\n            nums[++slow] = nums[fast];\n    return slow + 1;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Move Zeroes","category":"Arrays & Searching","aliases":["move zeroes","move zeros","move zeroes to end","shift zeroes","move zero","zeroes","zero","ज़ीरो","शून्य","end mein zero","జీరో","ஜீரோ","ಜೀರೋ","സീറോ"],"key_logic":"Compact all non-zeroes to the front in order, then fill the tail with zeroes. Relative order of non-zeroes must stay the same.","approaches":[{"name":"Extra array","logic":"Collect non-zeroes into a new array, copy back, zero-fill the rest. Clear, but extra memory.","code":"void moveZeroes(int[] nums) {\n    int[] copy = new int[nums.length];\n    int w = 0;\n    for (int n : nums) if (n != 0) copy[w++] = n;\n    System.arraycopy(copy, 0, nums, 0, nums.length);\n}","time":"O(n)","space":"O(n)","optimal":false},{"name":"Two pointers (overwrite)","logic":"Write each non-zero to the next front slot, then zero-fill the tail. One pass plus a fill — the cleanest in-place version.","code":"void moveZeroes(int[] nums) {\n    int w = 0;\n    for (int n : nums) if (n != 0) nums[w++] = n;\n    while (w < nums.length) nums[w++] = 0;\n}","time":"O(n)","space":"O(1)","optimal":true},{"name":"Swap in place","logic":"Swap each non-zero forward into the next slot. Same complexity, single pass, but writes more often than overwriting.","code":"void moveZeroes(int[] nums) {\n    int w = 0;\n    for (int r = 0; r < nums.length; r++)\n        if (nums[r] != 0) {\n            int tmp = nums[w]; nums[w] = nums[r]; nums[r] = tmp;\n            w++;\n        }\n}","time":"O(n)","space":"O(1)","optimal":false}]},{"name":"Longest Substring Without Repeating Characters","category":"Strings & Hashing","aliases":["longest substring without repeating","longest substring no repeat","longest unique substring","substring","repeat","bina repeat","longest substring","sliding window substring","సబ్‌స్ట్రింగ్","சப்ஸ்ட்ரிங்","ಸಬ್‌ಸ್ಟ್ರಿಂಗ್","സബ്സ്ട്രിംഗ്"],"key_logic":"A sliding window holds the current substring; when a repeat enters, shrink from the left until it is unique again.","approaches":[{"name":"Brute force","logic":"Generate every substring and check each for repeats with a set. Correct, cubic, never the interview answer.","code":"int lengthOfLongestSubstring(String s) {\n    int best = 0;\n    for (int i = 0; i < s.length(); i++)\n        for (int j = i; j < s.length(); j++)\n            if (allUnique(s, i, j)) best = Math.max(best, j - i + 1);\n    return best;\n}\nboolean allUnique(String s, int l, int r) {\n    Set<Character> seen = new HashSet<>();\n    for (int i = l; i <= r; i++)\n        if (!seen.add(s.charAt(i))) return false;\n    return true;\n}","time":"O(n³)","space":"O(min(n, m))","optimal":false},{"name":"Sliding window + set","logic":"Expand the right edge; if the character is already in the set, shrink the left edge until it is not. Each character enters and leaves once.","code":"int lengthOfLongestSubstring(String s) {\n    Set<Character> window = new HashSet<>();\n    int best = 0, l = 0;\n    for (int r = 0; r < s.length(); r++) {\n        while (window.contains(s.charAt(r)))\n            window.remove(s.charAt(l++));\n        window.add(s.charAt(r));\n        best = Math.max(best, r - l + 1);\n    }\n    return best;\n}","time":"O(n)","space":"O(min(n, m))","optimal":false},{"name":"Sliding window + index map","logic":"Remember each character's last index. On a repeat, jump the left edge straight past the previous occurrence instead of shrinking one by one.","code":"int lengthOfLongestSubstring(String s) {\n    Map<Character, Integer> last = new HashMap<>();\n    int best = 0, l = 0;\n    for (int r = 0; r < s.length(); r++) {\n        char c = s.charAt(r);\n        if (last.containsKey(c)) l = Math.max(l, last.get(c) + 1);\n        last.put(c, r);\n        best = Math.max(best, r - l + 1);\n    }\n    return best;\n}","time":"O(n)","space":"O(min(n, m))","optimal":true}]},{"name":"Valid Anagram","category":"Strings & Hashing","aliases":["valid anagram","anagram check","check anagram","are anagrams","anagram","एनाग्राम","అనాగ్రామ్","அனகிராம்","ಅನಾಗ್ರಾಮ್","അനഗ്രാം"],"key_logic":"Two strings are anagrams when their letter counts match exactly. Count, don't rearrange.","approaches":[{"name":"Sort both strings","logic":"Anagrams become identical once sorted. Simple and obviously correct; the sort costs the most.","code":"boolean isAnagram(String s, String t) {\n    if (s.length() != t.length()) return false;\n    char[] a = s.toCharArray(), b = t.toCharArray();\n    Arrays.sort(a); Arrays.sort(b);\n    return Arrays.equals(a, b);\n}","time":"O(n log n)","space":"O(n)","optimal":false},{"name":"Frequency array","logic":"Count each letter in the first string, subtract for the second. All zeroes means anagram. Fixed 26 slots, so constant space.","code":"boolean isAnagram(String s, String t) {\n    if (s.length() != t.length()) return false;\n    int[] count = new int[26];\n    for (int i = 0; i < s.length(); i++) {\n        count[s.charAt(i) - 'a']++;\n        count[t.charAt(i) - 'a']--;\n    }\n    for (int c : count) if (c != 0) return false;\n    return true;\n}","time":"O(n)","space":"O(1)","optimal":true},{"name":"Hash map counts","logic":"Same counting idea with a map, so it works for any Unicode characters, not just lowercase letters. Slightly more overhead.","code":"boolean isAnagram(String s, String t) {\n    if (s.length() != t.length()) return false;\n    Map<Character, Integer> count = new HashMap<>();\n    for (char c : s.toCharArray())\n        count.put(c, count.getOrDefault(c, 0) + 1);\n    for (char c : t.toCharArray()) {\n        count.put(c, count.getOrDefault(c, 0) - 1);\n        if (count.get(c) == 0) count.remove(c);\n    }\n    return count.isEmpty();\n}","time":"O(n)","space":"O(k)","optimal":false}]},{"name":"Sliding Window (generic)","category":"Arrays & Searching","aliases":["sliding window","sliding window technique","window technique","two pointers window","window pattern","खिड़की","స్లైడింగ్ విండో","ஸ்லைடிங் விண்டோ","ಸ್ಲೈಡಿಂಗ್ ವಿಂಡೋ","സ്ലൈഡിംഗ് വിൻഡോ"],"key_logic":"A window slides across the array instead of recomputing from scratch: add the entering element, remove the leaving one. Each element is touched twice at most.","approaches":[{"name":"Recompute every window","logic":"For each window position, sum or scan the whole window again. The same elements get re-added hundreds of times.","code":"// Max sum of any k consecutive elements, the slow way.\nint maxSum(int[] nums, int k) {\n    int best = Integer.MIN_VALUE;\n    for (int i = 0; i + k <= nums.length; i++) {\n        int sum = 0;\n        for (int j = i; j < i + k; j++) sum += nums[j];\n        best = Math.max(best, sum);\n    }\n    return best;\n}","time":"O(n·k)","space":"O(1)","optimal":false},{"name":"Fixed-size window","logic":"Sum the first window, then slide: add the new element, subtract the one that left. Use it when the window size is fixed (k elements).","code":"int maxSum(int[] nums, int k) {\n    int sum = 0;\n    for (int i = 0; i < k; i++) sum += nums[i];\n    int best = sum;\n    for (int i = k; i < nums.length; i++) {\n        sum += nums[i] - nums[i - k];\n        best = Math.max(best, sum);\n    }\n    return best;\n}","time":"O(n)","space":"O(1)","optimal":false},{"name":"Variable-size window","logic":"Expand the right edge, and shrink the left edge while the window breaks the rule. The general pattern behind longest-substring, minimum-window, and most subarray problems.","code":"// Longest subarray whose sum is at most k (positive numbers).\nint longestAtMost(int[] nums, int k) {\n    int best = 0, sum = 0, l = 0;\n    for (int r = 0; r < nums.length; r++) {\n        sum += nums[r];\n        while (sum > k) sum -= nums[l++];\n        best = Math.max(best, r - l + 1);\n    }\n    return best;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Binary Search","category":"Arrays & Searching","aliases":["binary search","binarysearch","search sorted array","bainari search","sorted array search","log n search","द्विआधारी खोज","బైనరీ సెర్చ్","பைனரி சர்ச்","ಬೈನರಿ ಸರ್ಚ್","ബൈനറി സെർച്ച്"],"key_logic":"Sorted data halves the search space every step: compare with the middle, discard the wrong half. Log time needs sorted input.","approaches":[{"name":"Linear scan","logic":"Check each element in order. Works on unsorted data too, but wastes the sorted order completely.","code":"int search(int[] nums, int target) {\n    for (int i = 0; i < nums.length; i++)\n        if (nums[i] == target) return i;\n    return -1;\n}","time":"O(n)","space":"O(1)","optimal":false},{"name":"Iterative binary search","logic":"Keep a [low, high] range, check the middle, keep the half that can contain the target. No recursion overhead.","code":"int search(int[] nums, int target) {\n    int lo = 0, hi = nums.length - 1;\n    while (lo <= hi) {\n        int mid = lo + (hi - lo) / 2; // avoids overflow\n        if (nums[mid] == target) return mid;\n        if (nums[mid] < target) lo = mid + 1;\n        else hi = mid - 1;\n    }\n    return -1;\n}","time":"O(log n)","space":"O(1)","optimal":true},{"name":"Recursive binary search","logic":"Same halving idea expressed as recursion: search the left or right half. Elegant, but each call costs stack space.","code":"int search(int[] nums, int target) {\n    return search(nums, target, 0, nums.length - 1);\n}\nint search(int[] nums, int target, int lo, int hi) {\n    if (lo > hi) return -1;\n    int mid = lo + (hi - lo) / 2;\n    if (nums[mid] == target) return mid;\n    if (nums[mid] < target) return search(nums, target, mid + 1, hi);\n    return search(nums, target, lo, mid - 1);\n}","time":"O(log n)","space":"O(log n)","optimal":false}]},{"name":"Merge Intervals","category":"Arrays & Searching","aliases":["merge intervals","merge overlapping intervals","overlapping intervals","merge interval","interval merge","merge overlapping"],"key_logic":"Sort by start time; overlapping intervals then sit next to each other and merge in one pass.","approaches":[{"name":"Pairwise merging","logic":"Repeatedly scan for any two overlapping intervals and merge them until none overlap. Works, but rescans constantly.","code":"// Sketch: repeat until stable — merge any overlapping pair found.\nList<int[]> merge(List<int[]> intervals) {\n    boolean changed = true;\n    while (changed) {\n        changed = false;\n        outer:\n        for (int i = 0; i < intervals.size(); i++)\n            for (int j = i + 1; j < intervals.size(); j++) {\n                int[] a = intervals.get(i), b = intervals.get(j);\n                if (a[0] <= b[1] && b[0] <= a[1]) {\n                    intervals.set(i, new int[]{Math.min(a[0], b[0]), Math.max(a[1], b[1])});\n                    intervals.remove(j);\n                    changed = true;\n                    break outer;\n                }\n            }\n    }\n    return intervals;\n}","time":"O(n²)","space":"O(n)","optimal":false},{"name":"Sort + single pass","logic":"Sort by start. Keep the last merged interval: if the next one starts before it ends, extend it; otherwise start a new one.","code":"int[][] merge(int[][] intervals) {\n    Arrays.sort(intervals, (a, b) -> a[0] - b[0]);\n    List<int[]> merged = new ArrayList<>();\n    for (int[] in : intervals) {\n        if (merged.isEmpty() || in[0] > merged.get(merged.size() - 1)[1])\n            merged.add(new int[]{in[0], in[1]});\n        else\n            merged.get(merged.size() - 1)[1] =\n                Math.max(merged.get(merged.size() - 1)[1], in[1]);\n    }\n    return merged.toArray(new int[0][]);\n}","time":"O(n log n)","space":"O(n)","optimal":true}]},{"name":"Trapping Rain Water","category":"Arrays & Searching","aliases":["trapping rain water","rain water trapped","trap rainwater","trapped water","trap rain water","rain water","rainwater","water trapped"],"key_logic":"Water over a bar equals min(highest bar on the left, highest on the right) minus the bar's own height, never below zero.","approaches":[{"name":"Brute force","logic":"For each bar, scan left and right to find the highest bars. Recomputes the same maxima for every position.","code":"int trap(int[] height) {\n    int water = 0;\n    for (int i = 0; i < height.length; i++) {\n        int leftMax = 0, rightMax = 0;\n        for (int j = 0; j <= i; j++) leftMax = Math.max(leftMax, height[j]);\n        for (int j = i; j < height.length; j++) rightMax = Math.max(rightMax, height[j]);\n        water += Math.min(leftMax, rightMax) - height[i];\n    }\n    return water;\n}","time":"O(n²)","space":"O(1)","optimal":false},{"name":"DP arrays","logic":"Precompute the highest bar to the left and right of every position once, then one pass applies the formula. Fast, but two extra arrays.","code":"int trap(int[] height) {\n    int n = height.length, water = 0;\n    int[] leftMax = new int[n], rightMax = new int[n];\n    for (int i = 1; i < n; i++) leftMax[i] = Math.max(leftMax[i - 1], height[i - 1]);\n    for (int i = n - 2; i >= 0; i--) rightMax[i] = Math.max(rightMax[i + 1], height[i + 1]);\n    for (int i = 0; i < n; i++)\n        water += Math.max(0, Math.min(leftMax[i], rightMax[i]) - height[i]);\n    return water;\n}","time":"O(n)","space":"O(n)","optimal":false},{"name":"Two pointers","logic":"Squeeze from both ends tracking the highest bar seen on each side. The lower side decides the water level, so one pass with no arrays is enough.","code":"int trap(int[] height) {\n    int l = 0, r = height.length - 1, leftMax = 0, rightMax = 0, water = 0;\n    while (l < r) {\n        if (height[l] < height[r]) {\n            leftMax = Math.max(leftMax, height[l]);\n            water += leftMax - height[l++];\n        } else {\n            rightMax = Math.max(rightMax, height[r]);\n            water += rightMax - height[r--];\n        }\n    }\n    return water;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Maximum Subarray (Kadane's Algorithm)","category":"Arrays & Searching","aliases":["maximum subarray","kadane","kadane's algorithm","max subarray sum","largest sum subarray","max subarray","kadane's","maximum sum subarray"],"key_logic":"Keep a running sum; if it ever goes negative, restart from the next element — a negative prefix only drags the total down.","approaches":[{"name":"Brute force","logic":"Sum every possible subarray and keep the largest. Straightforward, quadratic.","code":"int maxSubArray(int[] nums) {\n    int best = Integer.MIN_VALUE;\n    for (int i = 0; i < nums.length; i++) {\n        int sum = 0;\n        for (int j = i; j < nums.length; j++) {\n            sum += nums[j];\n            best = Math.max(best, sum);\n        }\n    }\n    return best;\n}","time":"O(n²)","space":"O(1)","optimal":false},{"name":"Divide and conquer","logic":"Split the array; the answer is the best in the left half, the right half, or crossing the middle. Elegant recursion, slower than Kadane's.","code":"int maxSubArray(int[] nums) { return solve(nums, 0, nums.length - 1); }\nint solve(int[] nums, int l, int r) {\n    if (l == r) return nums[l];\n    int m = (l + r) / 2;\n    int leftSum = Integer.MIN_VALUE, sum = 0;\n    for (int i = m; i >= l; i--) { sum += nums[i]; leftSum = Math.max(leftSum, sum); }\n    int rightSum = Integer.MIN_VALUE; sum = 0;\n    for (int i = m + 1; i <= r; i++) { sum += nums[i]; rightSum = Math.max(rightSum, sum); }\n    return Math.max(Math.max(solve(nums, l, m), solve(nums, m + 1, r)), leftSum + rightSum);\n}","time":"O(n log n)","space":"O(log n)","optimal":false},{"name":"Kadane's algorithm","logic":"At each element decide: extend the current subarray or start fresh here. Track the best seen. One pass, two variables.","code":"int maxSubArray(int[] nums) {\n    int current = nums[0], best = nums[0];\n    for (int i = 1; i < nums.length; i++) {\n        current = Math.max(nums[i], current + nums[i]);\n        best = Math.max(best, current);\n    }\n    return best;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Group Anagrams","category":"Strings & Hashing","aliases":["group anagrams","grouping anagrams","anagram groups","group anagram"],"key_logic":"Anagrams share a signature: either the sorted word or its 26 letter counts. Group words by their signature.","approaches":[{"name":"Sort each word","logic":"Sort the letters of every word; anagrams produce the same sorted key. Group by that key in a map.","code":"List<List<String>> groupAnagrams(String[] strs) {\n    Map<String, List<String>> groups = new HashMap<>();\n    for (String s : strs) {\n        char[] chars = s.toCharArray();\n        Arrays.sort(chars);\n        String key = new String(chars);\n        groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);\n    }\n    return new ArrayList<>(groups.values());\n}","time":"O(n·k log k)","space":"O(n·k)","optimal":false},{"name":"Count signature","logic":"Build a 26-count signature per word instead of sorting — counting is linear in word length, so the sort factor disappears.","code":"List<List<String>> groupAnagrams(String[] strs) {\n    Map<String, List<String>> groups = new HashMap<>();\n    for (String s : strs) {\n        int[] count = new int[26];\n        for (char c : s.toCharArray()) count[c - 'a']++;\n        String key = Arrays.toString(count);\n        groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);\n    }\n    return new ArrayList<>(groups.values());\n}","time":"O(n·k)","space":"O(n·k)","optimal":true}]},{"name":"Longest Palindromic Substring","category":"Strings & Hashing","aliases":["longest palindromic substring","longest palindrome","palindromic substring","palindrome substring","expand around center","expand around centre"],"key_logic":"A palindrome mirrors around its centre. Expand outwards from every possible centre and keep the longest expansion.","approaches":[{"name":"Brute force","logic":"Check every substring for being a palindrome. n² substrings, each check up to n — cubic and only a starting point.","code":"String longestPalindrome(String s) {\n    String best = \"\";\n    for (int i = 0; i < s.length(); i++)\n        for (int j = i; j < s.length(); j++) {\n            String sub = s.substring(i, j + 1);\n            if (isPalindrome(sub) && sub.length() > best.length()) best = sub;\n        }\n    return best;\n}\nboolean isPalindrome(String s) {\n    int l = 0, r = s.length() - 1;\n    while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;\n    return true;\n}","time":"O(n³)","space":"O(1)","optimal":false},{"name":"Expand around center","logic":"Treat every position (and every gap) as a centre and expand while characters match. Two centre types cover odd and even palindromes.","code":"String longestPalindrome(String s) {\n    int start = 0, len = 0;\n    for (int i = 0; i < s.length(); i++) {\n        int odd = expand(s, i, i), even = expand(s, i, i + 1);\n        int cur = Math.max(odd, even);\n        if (cur > len) { len = cur; start = i - (cur - 1) / 2; }\n    }\n    return s.substring(start, start + len);\n}\nint expand(String s, int l, int r) {\n    while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { l--; r++; }\n    return r - l - 1;\n}","time":"O(n²)","space":"O(1)","optimal":true},{"name":"DP table","logic":"A substring is a palindrome if its ends match and the inside is a palindrome. Fill a table of known results bottom-up.","code":"String longestPalindrome(String s) {\n    int n = s.length(), start = 0, len = 1;\n    boolean[][] dp = new boolean[n][n];\n    for (int i = n - 1; i >= 0; i--) {\n        dp[i][i] = true;\n        for (int j = i + 1; j < n; j++) {\n            dp[i][j] = s.charAt(i) == s.charAt(j) && (j - i < 2 || dp[i + 1][j - 1]);\n            if (dp[i][j] && j - i + 1 > len) { start = i; len = j - i + 1; }\n        }\n    }\n    return s.substring(start, start + len);\n}","time":"O(n²)","space":"O(n²)","optimal":false}]},{"name":"Reverse Linked List","category":"Linked List","aliases":["reverse linked list","reverse a linked list","reverse list","linked list reverse","reverse link list","reversing linked list","रिवर्स लिंक्ड लिस्ट","లింక్డ్ లిస్ట్ రివర్స్","லிங்க்ட் லிஸ்ட் ரிவர்ஸ்","ಲಿಂಕ್ಡ್ ಲಿಸ್ಟ್ ರಿವರ್ಸ್","ലിങ്ക്ഡ് ലിസ്റ്റ് റിവേഴ്സ്"],"key_logic":"Walk the list flipping each node's arrow; three pointers (prev, curr, next) keep you from losing the rest of the list.","approaches":[{"name":"Iterative (three pointers)","logic":"Save the next node, flip the current arrow to point backwards, step all pointers forward. Constant extra space.","code":"ListNode reverseList(ListNode head) {\n    ListNode prev = null, curr = head;\n    while (curr != null) {\n        ListNode next = curr.next; // save before flipping\n        curr.next = prev;\n        prev = curr;\n        curr = next;\n    }\n    return prev;\n}","time":"O(n)","space":"O(1)","optimal":true},{"name":"Recursive","logic":"Reverse the rest of the list, then fix the current node's arrow. Same idea, expressed recursively — the call stack holds the pointers.","code":"ListNode reverseList(ListNode head) {\n    if (head == null || head.next == null) return head;\n    ListNode rest = reverseList(head.next);\n    head.next.next = head;\n    head.next = null;\n    return rest;\n}","time":"O(n)","space":"O(n)","optimal":false},{"name":"Stack","logic":"Push all nodes on a stack, then pop them to rebuild the list in reverse order. Simple to reason about, wastes a full stack of space.","code":"ListNode reverseList(ListNode head) {\n    Deque<ListNode> stack = new ArrayDeque<>();\n    while (head != null) { stack.push(head); head = head.next; }\n    ListNode dummy = new ListNode(0), curr = dummy;\n    while (!stack.isEmpty()) { curr.next = stack.pop(); curr = curr.next; }\n    curr.next = null;\n    return dummy.next;\n}","time":"O(n)","space":"O(n)","optimal":false}]},{"name":"Linked List Cycle","category":"Linked List","aliases":["linked list cycle","detect cycle","cycle in linked list","loop in linked list","floyd cycle","tortoise hare","cycle detection linked list"],"key_logic":"Two runners at different speeds on a loop must eventually meet; on a straight road the fast one reaches the end. That meeting is the cycle test.","approaches":[{"name":"Hash set of visited nodes","logic":"Remember every node visited; the first repeat proves a cycle. Easy to see, but stores the whole list.","code":"boolean hasCycle(ListNode head) {\n    Set<ListNode> seen = new HashSet<>();\n    while (head != null) {\n        if (!seen.add(head)) return true;\n        head = head.next;\n    }\n    return false;\n}","time":"O(n)","space":"O(n)","optimal":false},{"name":"Floyd's tortoise and hare","logic":"A slow pointer moves one step, a fast pointer two. If they ever land on the same node, there is a cycle; if fast hits null, there is none.","code":"boolean hasCycle(ListNode head) {\n    ListNode slow = head, fast = head;\n    while (fast != null && fast.next != null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow == fast) return true;\n    }\n    return false;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Merge Two Sorted Lists","category":"Linked List","aliases":["merge two sorted lists","merge sorted lists","merge two lists","merge two sorted linked lists"],"key_logic":"Always attach the smaller head node; a dummy node removes the empty-list edge case entirely.","approaches":[{"name":"Dummy node + iterative","logic":"Walk both lists with a tail pointer, attaching the smaller head each time, then attach whichever list remains.","code":"ListNode mergeTwoLists(ListNode a, ListNode b) {\n    ListNode dummy = new ListNode(0), tail = dummy;\n    while (a != null && b != null) {\n        if (a.val <= b.val) { tail.next = a; a = a.next; }\n        else { tail.next = b; b = b.next; }\n        tail = tail.next;\n    }\n    tail.next = (a != null) ? a : b;\n    return dummy.next;\n}","time":"O(n + m)","space":"O(1)","optimal":true},{"name":"Recursive","logic":"The smaller head keeps its place; merge the rest recursively and attach the result. Same time, but the call stack grows with the lists.","code":"ListNode mergeTwoLists(ListNode a, ListNode b) {\n    if (a == null) return b;\n    if (b == null) return a;\n    if (a.val <= b.val) {\n        a.next = mergeTwoLists(a.next, b);\n        return a;\n    }\n    b.next = mergeTwoLists(a, b.next);\n    return b;\n}","time":"O(n + m)","space":"O(n + m)","optimal":false}]},{"name":"Remove Nth Node From End of List","category":"Linked List","aliases":["remove nth node","remove nth from end","nth node from end","delete nth node end","remove nth node from end","remove node from end linked list"],"key_logic":"Two pointers kept n apart: when the front pointer hits the end, the rear pointer sits just before the node to remove.","approaches":[{"name":"Two passes","logic":"First pass counts the length; second pass walks to the node before the target and skips it. Simple, touches the list twice.","code":"ListNode removeNthFromEnd(ListNode head, int n) {\n    int len = 0;\n    for (ListNode p = head; p != null; p = p.next) len++;\n    ListNode dummy = new ListNode(0, head), p = dummy;\n    for (int i = 0; i < len - n; i++) p = p.next;\n    p.next = p.next.next;\n    return dummy.next;\n}","time":"O(n)","space":"O(1)","optimal":false},{"name":"One pass, two pointers","logic":"Move the front pointer n+1 steps ahead, then move both together. The gap guarantees the rear lands on the node before the target.","code":"ListNode removeNthFromEnd(ListNode head, int n) {\n    ListNode dummy = new ListNode(0, head);\n    ListNode front = dummy, rear = dummy;\n    for (int i = 0; i <= n; i++) front = front.next;\n    while (front != null) { front = front.next; rear = rear.next; }\n    rear.next = rear.next.next;\n    return dummy.next;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Valid Parentheses","category":"Stack & Queue","aliases":["valid parentheses","valid brackets","balanced parentheses","check parentheses","valid parenthesis","parentheses valid","brackets valid","balanced brackets"],"key_logic":"An opener must be closed by the matching closer, most recent first — exactly what a stack gives you.","approaches":[{"name":"Stack","logic":"Push openers; on a closer, the stack top must be its match. Anything left over, or a mismatch, means invalid.","code":"boolean isValid(String s) {\n    Deque<Character> stack = new ArrayDeque<>();\n    Map<Character, Character> match = Map.of(')', '(', ']', '[', '}', '{');\n    for (char c : s.toCharArray()) {\n        if (match.containsKey(c)) {\n            if (stack.isEmpty() || stack.pop() != match.get(c)) return false;\n        } else {\n            stack.push(c);\n        }\n    }\n    return stack.isEmpty();\n}","time":"O(n)","space":"O(n)","optimal":true},{"name":"Counter (one bracket type only)","logic":"Count +1 for '(' and −1 for ')'; never negative, end at zero. Constant space — but it only works when a single bracket type exists, so it fails mixed brackets.","code":"// ONLY for a single bracket type like \"()()\". Fails on \"([)]\".\nboolean isValidSingleType(String s) {\n    int depth = 0;\n    for (char c : s.toCharArray()) {\n        if (c == '(') depth++;\n        else if (--depth < 0) return false;\n    }\n    return depth == 0;\n}","time":"O(n)","space":"O(1)","optimal":false}]},{"name":"Min Stack","category":"Stack & Queue","aliases":["min stack","minimum stack","stack with getmin","getmin stack","stack getmin","get minimum stack","minstack"],"key_logic":"Carry the minimum along with the data, so getMin never has to rescan the stack.","approaches":[{"name":"Rescan on getMin","logic":"A plain stack; getMin scans everything. Push and pop stay fast, but the minimum query is slow — the opposite of what the problem asks.","code":"class MinStack {\n    Deque<Integer> stack = new ArrayDeque<>();\n    void push(int x) { stack.push(x); }\n    void pop() { stack.pop(); }\n    int top() { return stack.peek(); }\n    int getMin() { // O(n) every call\n        int min = Integer.MAX_VALUE;\n        for (int x : stack) min = Math.min(min, x);\n        return min;\n    }\n}","time":"O(n) per getMin","space":"O(n)","optimal":false},{"name":"Two stacks","logic":"A second stack tracks the minimum at each height: push the new minimum alongside every push, pop both together.","code":"class MinStack {\n    Deque<Integer> stack = new ArrayDeque<>();\n    Deque<Integer> mins = new ArrayDeque<>();\n    void push(int x) {\n        stack.push(x);\n        mins.push(mins.isEmpty() ? x : Math.min(x, mins.peek()));\n    }\n    void pop() { stack.pop(); mins.pop(); }\n    int top() { return stack.peek(); }\n    int getMin() { return mins.peek(); }\n}","time":"O(1) per operation","space":"O(n)","optimal":true},{"name":"Store pairs","logic":"Each entry stores (value, minimum-so-far). One stack instead of two; same idea, slightly different packaging.","code":"class MinStack {\n    record Entry(int value, int min) {}\n    Deque<Entry> stack = new ArrayDeque<>();\n    void push(int x) {\n        int min = stack.isEmpty() ? x : Math.min(x, stack.peek().min());\n        stack.push(new Entry(x, min));\n    }\n    void pop() { stack.pop(); }\n    int top() { return stack.peek().value(); }\n    int getMin() { return stack.peek().min(); }\n}","time":"O(1) per operation","space":"O(n)","optimal":false}]},{"name":"Next Greater Element","category":"Stack & Queue","aliases":["next greater element","next greater","next larger element","nge","next largest element","monotonic stack","next bigger element"],"key_logic":"A decreasing stack holds elements still waiting for a greater one; each element is pushed and popped exactly once.","approaches":[{"name":"Brute force","logic":"For each element, scan right until a larger value appears. Simple, quadratic in the worst case.","code":"int[] nextGreater(int[] nums) {\n    int[] ans = new int[nums.length];\n    for (int i = 0; i < nums.length; i++) {\n        ans[i] = -1;\n        for (int j = i + 1; j < nums.length; j++)\n            if (nums[j] > nums[i]) { ans[i] = nums[j]; break; }\n    }\n    return ans;\n}","time":"O(n²)","space":"O(1)","optimal":false},{"name":"Monotonic stack","logic":"Scan once, keeping a decreasing stack of indices. A new element resolves every smaller element waiting on the stack, then joins it.","code":"int[] nextGreater(int[] nums) {\n    int[] ans = new int[nums.length];\n    Arrays.fill(ans, -1);\n    Deque<Integer> stack = new ArrayDeque<>(); // indices, decreasing values\n    for (int i = 0; i < nums.length; i++) {\n        while (!stack.isEmpty() && nums[i] > nums[stack.peek()]) {\n            ans[stack.pop()] = nums[i];\n        }\n        stack.push(i);\n    }\n    return ans;\n}","time":"O(n)","space":"O(n)","optimal":true}]},{"name":"Binary Tree Traversals","category":"Trees","aliases":["binary tree traversal","tree traversal","inorder","preorder","postorder","dfs traversal tree","traverse binary tree","in order traversal","pre order traversal","post order traversal","inorder preorder postorder","traverse tree","tree traversals"],"key_logic":"DFS visits root-left-right in different orders; the order decides what the traversal is for — inorder of a BST gives sorted values, preorder rebuilds the tree.","approaches":[{"name":"Recursive DFS","logic":"The call stack does the work: visit in the order the traversal defines. The clearest code, and the standard interview answer.","code":"// Inorder: left, root, right. Swap the lines for pre/postorder.\nvoid inorder(TreeNode root, List<Integer> out) {\n    if (root == null) return;\n    inorder(root.left, out);\n    out.add(root.val);\n    inorder(root.right, out);\n}","time":"O(n)","space":"O(h)","optimal":true},{"name":"Iterative with a stack","logic":"Manage your own stack instead of recursion: push left children, visit, then go right. Same result, no call-stack depth limit.","code":"List<Integer> inorder(TreeNode root) {\n    List<Integer> out = new ArrayList<>();\n    Deque<TreeNode> stack = new ArrayDeque<>();\n    while (root != null || !stack.isEmpty()) {\n        while (root != null) { stack.push(root); root = root.left; }\n        root = stack.pop();\n        out.add(root.val);\n        root = root.right;\n    }\n    return out;\n}","time":"O(n)","space":"O(h)","optimal":false},{"name":"Morris traversal","logic":"Temporarily rewire the tree's empty right pointers to thread back up, then restore them. Constant space, but advanced and easy to get wrong.","code":"// Inorder, O(1) space. Threads the tree, then restores it.\nList<Integer> inorder(TreeNode root) {\n    List<Integer> out = new ArrayList<>();\n    TreeNode curr = root;\n    while (curr != null) {\n        if (curr.left == null) { out.add(curr.val); curr = curr.right; }\n        else {\n            TreeNode pred = curr.left;\n            while (pred.right != null && pred.right != curr) pred = pred.right;\n            if (pred.right == null) { pred.right = curr; curr = curr.left; }\n            else { pred.right = null; out.add(curr.val); curr = curr.right; }\n        }\n    }\n    return out;\n}","time":"O(n)","space":"O(1)","optimal":false}]},{"name":"Maximum Depth of Binary Tree","category":"Trees","aliases":["maximum depth binary tree","max depth tree","height of binary tree","depth of tree","maximum depth of binary tree","max depth binary tree","depth of binary tree","tree height","tree depth"],"key_logic":"A tree's depth is 1 plus the deeper of its two subtrees. The recursion writes itself.","approaches":[{"name":"Recursive DFS","logic":"Depth of an empty tree is 0; otherwise 1 + max(depth of children). The cleanest solution by far.","code":"int maxDepth(TreeNode root) {\n    if (root == null) return 0;\n    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n}","time":"O(n)","space":"O(h)","optimal":true},{"name":"BFS level order","logic":"Walk level by level with a queue and count the levels. The queue holds one full level at a time.","code":"int maxDepth(TreeNode root) {\n    if (root == null) return 0;\n    Queue<TreeNode> queue = new ArrayDeque<>(List.of(root));\n    int depth = 0;\n    while (!queue.isEmpty()) {\n        depth++;\n        for (int i = queue.size(); i > 0; i--) {\n            TreeNode node = queue.remove();\n            if (node.left != null) queue.add(node.left);\n            if (node.right != null) queue.add(node.right);\n        }\n    }\n    return depth;\n}","time":"O(n)","space":"O(w)","optimal":false},{"name":"Iterative DFS with a stack","logic":"Track (node, depth) pairs on your own stack and keep the maximum depth seen. Recursion-free, same idea.","code":"int maxDepth(TreeNode root) {\n    if (root == null) return 0;\n    Deque<TreeNode> nodes = new ArrayDeque<>();\n    Deque<Integer> depths = new ArrayDeque<>();\n    nodes.push(root); depths.push(1);\n    int best = 0;\n    while (!nodes.isEmpty()) {\n        TreeNode node = nodes.pop();\n        int d = depths.pop();\n        best = Math.max(best, d);\n        if (node.left != null) { nodes.push(node.left); depths.push(d + 1); }\n        if (node.right != null) { nodes.push(node.right); depths.push(d + 1); }\n    }\n    return best;\n}","time":"O(n)","space":"O(h)","optimal":false}]},{"name":"Invert Binary Tree","category":"Trees","aliases":["invert binary tree","invert tree","mirror tree","flip binary tree","mirror binary tree","reverse binary tree"],"key_logic":"Swap every node's left and right children, then do the same for both subtrees. The mirror builds itself.","approaches":[{"name":"Recursive swap","logic":"Swap the children, then recurse on both. Three lines of real logic — the classic answer.","code":"TreeNode invertTree(TreeNode root) {\n    if (root == null) return null;\n    TreeNode tmp = root.left;\n    root.left = invertTree(root.right);\n    root.right = invertTree(tmp);\n    return root;\n}","time":"O(n)","space":"O(h)","optimal":true},{"name":"Iterative with a queue","logic":"BFS through the tree, swapping each node's children as you visit. Same result without recursion.","code":"TreeNode invertTree(TreeNode root) {\n    if (root == null) return null;\n    Queue<TreeNode> queue = new ArrayDeque<>(List.of(root));\n    while (!queue.isEmpty()) {\n        TreeNode node = queue.remove();\n        TreeNode tmp = node.left;\n        node.left = node.right;\n        node.right = tmp;\n        if (node.left != null) queue.add(node.left);\n        if (node.right != null) queue.add(node.right);\n    }\n    return root;\n}","time":"O(n)","space":"O(w)","optimal":false}]},{"name":"Validate Binary Search Tree","category":"Trees","aliases":["validate bst","validate binary search tree","check bst","is valid bst","valid bst","bst valid","binary search tree valid"],"key_logic":"Every node must sit inside a valid (min, max) range inherited from its ancestors — comparing with the parent alone is not enough.","approaches":[{"name":"Brute force subtree checks","logic":"For each node, verify its whole left subtree is smaller and right subtree larger by scanning both. Repeats the same scans at every level.","code":"boolean isValidBST(TreeNode root) {\n    if (root == null) return true;\n    return allSmaller(root.left, root.val)\n        && allGreater(root.right, root.val)\n        && isValidBST(root.left) && isValidBST(root.right);\n}\nboolean allSmaller(TreeNode node, int val) {\n    if (node == null) return true;\n    return node.val < val && allSmaller(node.left, val) && allSmaller(node.right, val);\n}\nboolean allGreater(TreeNode node, int val) {\n    if (node == null) return true;\n    return node.val > val && allGreater(node.left, val) && allGreater(node.right, val);\n}","time":"O(n²)","space":"O(h)","optimal":false},{"name":"Inorder + sorted check","logic":"Inorder traversal of a BST must be strictly increasing. Walk it and check each value beats the previous one.","code":"boolean isValidBST(TreeNode root) {\n    return inorder(root, new long[]{Long.MIN_VALUE});\n}\nboolean inorder(TreeNode node, long[] prev) {\n    if (node == null) return true;\n    if (!inorder(node.left, prev)) return false;\n    if (node.val <= prev[0]) return false;\n    prev[0] = node.val;\n    return inorder(node.right, prev);\n}","time":"O(n)","space":"O(h)","optimal":false},{"name":"Range check (min, max)","logic":"Carry the allowed range down: left children must stay below the parent, right children above it, tightened by every ancestor.","code":"boolean isValidBST(TreeNode root) {\n    return check(root, Long.MIN_VALUE, Long.MAX_VALUE);\n}\nboolean check(TreeNode node, long lo, long hi) {\n    if (node == null) return true;\n    if (node.val <= lo || node.val >= hi) return false;\n    return check(node.left, lo, node.val) && check(node.right, node.val, hi);\n}","time":"O(n)","space":"O(h)","optimal":true}]},{"name":"Lowest Common Ancestor of a BST","category":"Trees","aliases":["lowest common ancestor","lca bst","lca of bst","lowest common ancestor bst","lca","common ancestor","lowest common ancestor binary search tree"],"key_logic":"In a BST the split point is the answer: go left if both targets are smaller, right if both are larger — otherwise you are standing on the LCA.","approaches":[{"name":"Path lists","logic":"Record the root-to-target path for both nodes; the last common node on the two paths is the LCA. General, but stores both paths.","code":"TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n    List<TreeNode> pathP = pathTo(root, p), pathQ = pathTo(root, q);\n    TreeNode lca = root;\n    for (int i = 0; i < Math.min(pathP.size(), pathQ.size()); i++) {\n        if (pathP.get(i) == pathQ.get(i)) lca = pathP.get(i);\n        else break;\n    }\n    return lca;\n}\nList<TreeNode> pathTo(TreeNode root, TreeNode target) {\n    List<TreeNode> path = new ArrayList<>();\n    while (root != target) {\n        path.add(root);\n        root = target.val < root.val ? root.left : root.right;\n    }\n    path.add(root);\n    return path;\n}","time":"O(h)","space":"O(h)","optimal":false},{"name":"Iterative BST walk","logic":"Walk down using the BST order: both targets smaller, go left; both larger, go right; split means current node is the LCA. No extra memory.","code":"TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n    while (root != null) {\n        if (p.val < root.val && q.val < root.val) root = root.left;\n        else if (p.val > root.val && q.val > root.val) root = root.right;\n        else return root;\n    }\n    return null;\n}","time":"O(h)","space":"O(1)","optimal":true},{"name":"Recursive BST walk","logic":"Same split logic as the iterative walk, written recursively. The recursion depth is the tree height.","code":"TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n    if (p.val < root.val && q.val < root.val)\n        return lowestCommonAncestor(root.left, p, q);\n    if (p.val > root.val && q.val > root.val)\n        return lowestCommonAncestor(root.right, p, q);\n    return root;\n}","time":"O(h)","space":"O(h)","optimal":false}]},{"name":"Breadth-First Search (BFS)","category":"Graphs","aliases":["bfs","breadth first search","breadth-first search","level order traversal graph","breadth-first","bfs graph","breadth first traversal","level order graph"],"key_logic":"A queue visits nodes level by level — the first time you reach a node is by the shortest path. That is why BFS finds shortest paths in unweighted graphs.","approaches":[{"name":"Queue + visited set","logic":"Push the start node, then repeatedly pop, visit, and push unvisited neighbours. The visited set stops revisits and infinite loops.","code":"void bfs(Map<Integer, List<Integer>> graph, int start) {\n    Queue<Integer> queue = new ArrayDeque<>(List.of(start));\n    Set<Integer> visited = new HashSet<>(Set.of(start));\n    while (!queue.isEmpty()) {\n        int node = queue.remove();\n        // visit(node)\n        for (int next : graph.getOrDefault(node, List.of()))\n            if (visited.add(next)) queue.add(next);\n    }\n}","time":"O(V + E)","space":"O(V)","optimal":true},{"name":"Level-by-level BFS","logic":"Process the queue one level at a time (snapshot its size per level). Same traversal, but you know each node's distance from the start.","code":"List<List<Integer>> bfsLevels(Map<Integer, List<Integer>> graph, int start) {\n    List<List<Integer>> levels = new ArrayList<>();\n    Queue<Integer> queue = new ArrayDeque<>(List.of(start));\n    Set<Integer> visited = new HashSet<>(Set.of(start));\n    while (!queue.isEmpty()) {\n        List<Integer> level = new ArrayList<>();\n        for (int i = queue.size(); i > 0; i--) {\n            int node = queue.remove();\n            level.add(node);\n            for (int next : graph.getOrDefault(node, List.of()))\n                if (visited.add(next)) queue.add(next);\n        }\n        levels.add(level);\n    }\n    return levels;\n}","time":"O(V + E)","space":"O(V)","optimal":false},{"name":"BFS on a grid","logic":"Same queue idea on a 2D grid: neighbours are the four directions, and visited cells are marked in place. The workhorse for shortest-path-on-grid problems.","code":"// Shortest distance from (0,0) in a grid; -1 means blocked.\nint bfsGrid(int[][] grid) {\n    int R = grid.length, C = grid[0].length;\n    int[][] dist = new int[R][C];\n    Queue<int[]> queue = new ArrayDeque<>(List.of(new int[]{0, 0}));\n    grid[0][0] = -1;\n    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n    while (!queue.isEmpty()) {\n        int[] cell = queue.remove();\n        for (int[] d : dirs) {\n            int r = cell[0] + d[0], c = cell[1] + d[1];\n            if (r >= 0 && r < R && c >= 0 && c < C && grid[r][c] != -1) {\n                grid[r][c] = -1;\n                dist[r][c] = dist[cell[0]][cell[1]] + 1;\n                queue.add(new int[]{r, c});\n            }\n        }\n    }\n    return dist[R - 1][C - 1];\n}","time":"O(R·C)","space":"O(R·C)","optimal":false}]},{"name":"Depth-First Search (DFS)","category":"Graphs","aliases":["dfs","depth first search","depth-first search","graph dfs","depth-first","dfs graph","depth first traversal"],"key_logic":"Go as deep as possible before backtracking. Recursion or an explicit stack — the stack, real or manual, is the whole technique.","approaches":[{"name":"Recursive DFS","logic":"Visit a node, mark it, recurse into each unvisited neighbour. The call stack remembers the path back. The standard form for most graph problems.","code":"void dfs(Map<Integer, List<Integer>> graph, int node, Set<Integer> visited) {\n    visited.add(node);\n    // visit(node)\n    for (int next : graph.getOrDefault(node, List.of()))\n        if (!visited.contains(next))\n            dfs(graph, next, visited);\n}","time":"O(V + E)","space":"O(V)","optimal":true},{"name":"Iterative DFS with a stack","logic":"Push neighbours on your own stack instead of recursing. Same visit order family, no recursion-depth limit — useful for very deep graphs.","code":"void dfs(Map<Integer, List<Integer>> graph, int start) {\n    Deque<Integer> stack = new ArrayDeque<>(List.of(start));\n    Set<Integer> visited = new HashSet<>(Set.of(start));\n    while (!stack.isEmpty()) {\n        int node = stack.pop();\n        // visit(node)\n        for (int next : graph.getOrDefault(node, List.of()))\n            if (visited.add(next)) stack.push(next);\n    }\n}","time":"O(V + E)","space":"O(V)","optimal":false},{"name":"DFS on a grid","logic":"Flood-fill recursion on a grid: mark the cell, recurse in four directions. The core of island counting, area problems, and flood fill.","code":"void dfsGrid(char[][] grid, int r, int c) {\n    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) return;\n    if (grid[r][c] != '1') return;\n    grid[r][c] = '0'; // mark visited in place\n    dfsGrid(grid, r + 1, c);\n    dfsGrid(grid, r - 1, c);\n    dfsGrid(grid, r, c + 1);\n    dfsGrid(grid, r, c - 1);\n}","time":"O(R·C)","space":"O(R·C)","optimal":false}]},{"name":"Number of Islands","category":"Graphs","aliases":["number of islands","count islands","islands problem","count of islands","islands","number islands","island count","connected islands"],"key_logic":"Each unvisited '1' starts a new island; flood-fill it so its land is never counted twice.","approaches":[{"name":"DFS flood fill","logic":"Scan the grid; on an unvisited '1', count one island and recursively sink the whole island to '0'. The most common interview answer.","code":"int numIslands(char[][] grid) {\n    int islands = 0;\n    for (int r = 0; r < grid.length; r++)\n        for (int c = 0; c < grid[0].length; c++)\n            if (grid[r][c] == '1') { islands++; sink(grid, r, c); }\n    return islands;\n}\nvoid sink(char[][] grid, int r, int c) {\n    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) return;\n    if (grid[r][c] != '1') return;\n    grid[r][c] = '0';\n    sink(grid, r + 1, c); sink(grid, r - 1, c);\n    sink(grid, r, c + 1); sink(grid, r, c - 1);\n}","time":"O(R·C)","space":"O(R·C) worst case","optimal":true},{"name":"BFS flood fill","logic":"Same scan, but each island is sunk with a queue instead of recursion. No recursion depth risk on huge islands.","code":"int numIslands(char[][] grid) {\n    int islands = 0;\n    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n    for (int r = 0; r < grid.length; r++)\n        for (int c = 0; c < grid[0].length; c++) {\n            if (grid[r][c] != '1') continue;\n            islands++;\n            Queue<int[]> queue = new ArrayDeque<>(List.of(new int[]{r, c}));\n            grid[r][c] = '0';\n            while (!queue.isEmpty()) {\n                int[] cell = queue.remove();\n                for (int[] d : dirs) {\n                    int nr = cell[0] + d[0], nc = cell[1] + d[1];\n                    if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length\n                            && grid[nr][nc] == '1') {\n                        grid[nr][nc] = '0';\n                        queue.add(new int[]{nr, nc});\n                    }\n                }\n            }\n        }\n    return islands;\n}","time":"O(R·C)","space":"O(R·C) worst case","optimal":false},{"name":"Union-Find","logic":"Union every land cell with its land neighbours, then count distinct roots. No flood fill at all — good when the grid changes over time.","code":"// Sketch: parent array over R*C cells; union right/down neighbours.\nint numIslands(char[][] grid) {\n    int R = grid.length, C = grid[0].length;\n    int[] parent = new int[R * C];\n    for (int i = 0; i < parent.length; i++) parent[i] = i;\n    // union(r, c) with (r+1, c) and (r, c+1) when both are '1' ...\n    Set<Integer> roots = new HashSet<>();\n    for (int r = 0; r < R; r++)\n        for (int c = 0; c < C; c++)\n            if (grid[r][c] == '1') roots.add(find(parent, r * C + c));\n    return roots.size();\n}\nint find(int[] parent, int x) {\n    if (parent[x] != x) parent[x] = find(parent, parent[x]);\n    return parent[x];\n}","time":"O(R·C·α)","space":"O(R·C)","optimal":false}]},{"name":"Climbing Stairs","category":"Dynamic Programming","aliases":["climbing stairs","climb stairs","stairs problem","ways to climb stairs","stairs","climbing staircase"],"key_logic":"Ways to reach step n equal ways to n−1 plus ways to n−2 — the Fibonacci recurrence. The whole problem is not recomputing it.","approaches":[{"name":"Plain recursion","logic":"Directly code the recurrence. The same subproblems get solved exponentially many times — the classic DP motivation.","code":"int climbStairs(int n) {\n    if (n <= 2) return n;\n    return climbStairs(n - 1) + climbStairs(n - 2);\n}","time":"O(2^n)","space":"O(n)","optimal":false},{"name":"Memoization","logic":"Cache each answer the first time it is computed. Every subproblem is solved once; the recursion structure stays.","code":"int climbStairs(int n) {\n    return solve(n, new HashMap<>());\n}\nint solve(int n, Map<Integer, Integer> memo) {\n    if (n <= 2) return n;\n    if (memo.containsKey(n)) return memo.get(n);\n    int ans = solve(n - 1, memo) + solve(n - 2, memo);\n    memo.put(n, ans);\n    return ans;\n}","time":"O(n)","space":"O(n)","optimal":false},{"name":"Two variables","logic":"Only the last two answers matter, so keep two variables and roll forward. Same time as memoization, constant space.","code":"int climbStairs(int n) {\n    if (n <= 2) return n;\n    int prev2 = 1, prev1 = 2;\n    for (int i = 3; i <= n; i++) {\n        int cur = prev1 + prev2;\n        prev2 = prev1;\n        prev1 = cur;\n    }\n    return prev1;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"House Robber","category":"Dynamic Programming","aliases":["house robber","rob houses","house robber problem","maximum robbery","house robbery","robber","maximum loot houses"],"key_logic":"At each house, choose: rob it (plus the best up to two houses back) or skip it (keep the best up to the previous house).","approaches":[{"name":"Plain recursion","logic":"Try rob/skip at every house recursively. Exponential — the same suffixes are re-decided constantly.","code":"int rob(int[] nums) { return solve(nums, 0); }\nint solve(int[] nums, int i) {\n    if (i >= nums.length) return 0;\n    return Math.max(nums[i] + solve(nums, i + 2), solve(nums, i + 1));\n}","time":"O(2^n)","space":"O(n)","optimal":false},{"name":"DP array","logic":"dp[i] is the best loot considering houses up to i. Fill it left to right using the rob/skip choice.","code":"int rob(int[] nums) {\n    if (nums.length == 1) return nums[0];\n    int[] dp = new int[nums.length];\n    dp[0] = nums[0];\n    dp[1] = Math.max(nums[0], nums[1]);\n    for (int i = 2; i < nums.length; i++)\n        dp[i] = Math.max(dp[i - 1], dp[i - 2] + nums[i]);\n    return dp[nums.length - 1];\n}","time":"O(n)","space":"O(n)","optimal":false},{"name":"Two variables","logic":"Only the previous two dp values are ever used, so two rolling variables replace the whole array.","code":"int rob(int[] nums) {\n    int prev2 = 0, prev1 = 0;\n    for (int n : nums) {\n        int cur = Math.max(prev1, prev2 + n);\n        prev2 = prev1;\n        prev1 = cur;\n    }\n    return prev1;\n}","time":"O(n)","space":"O(1)","optimal":true}]},{"name":"Coin Change","category":"Dynamic Programming","aliases":["coin change","minimum coins","fewest coins","coin change problem","coinchange","change coins"],"key_logic":"dp[amount] equals 1 plus the fewest coins for (amount − coin), tried over every coin. Build it from 0 up to the target.","approaches":[{"name":"Plain recursion","logic":"Try every coin as the first pick and recurse on the remainder. The same amounts are recomputed exponentially often.","code":"int coinChange(int[] coins, int amount) {\n    if (amount == 0) return 0;\n    if (amount < 0) return -1;\n    int best = Integer.MAX_VALUE;\n    for (int coin : coins) {\n        int sub = coinChange(coins, amount - coin);\n        if (sub >= 0) best = Math.min(best, sub + 1);\n    }\n    return best == Integer.MAX_VALUE ? -1 : best;\n}","time":"Exponential","space":"O(amount)","optimal":false},{"name":"Memoization (top-down)","logic":"Same recursion, but each amount is solved once and cached. The recursion mirrors the problem statement directly.","code":"int coinChange(int[] coins, int amount) {\n    return solve(coins, amount, new HashMap<>());\n}\nint solve(int[] coins, int amount, Map<Integer, Integer> memo) {\n    if (amount == 0) return 0;\n    if (amount < 0) return -1;\n    if (memo.containsKey(amount)) return memo.get(amount);\n    int best = Integer.MAX_VALUE;\n    for (int coin : coins) {\n        int sub = solve(coins, amount - coin, memo);\n        if (sub >= 0) best = Math.min(best, sub + 1);\n    }\n    int ans = best == Integer.MAX_VALUE ? -1 : best;\n    memo.put(amount, ans);\n    return ans;\n}","time":"O(amount·n)","space":"O(amount)","optimal":false},{"name":"Bottom-up DP","logic":"Fill dp[0..amount] in order; each entry tries every coin against an already-solved smaller amount. No recursion, no repeated work.","code":"int coinChange(int[] coins, int amount) {\n    int[] dp = new int[amount + 1];\n    Arrays.fill(dp, amount + 1); // sentinel for \"impossible\"\n    dp[0] = 0;\n    for (int a = 1; a <= amount; a++)\n        for (int coin : coins)\n            if (coin <= a) dp[a] = Math.min(dp[a], dp[a - coin] + 1);\n    return dp[amount] > amount ? -1 : dp[amount];\n}","time":"O(amount·n)","space":"O(amount)","optimal":true}]},{"name":"Quick Sort","category":"Sorting","aliases":["quick sort","quicksort","quick sort algorithm","quick-sort","partition sort","quicksort algorithm","क्विक सॉर्ट","క్విక్ సార్ట్","குயிக் சார்ட்","ಕ್ವಿಕ್ ಸಾರ್ಟ್","ക്വിക്ക് സോർട്ട്"],"key_logic":"Pick a pivot, partition so smaller elements go left and larger go right, then sort both sides. The partition scheme is the whole algorithm.","approaches":[{"name":"Lomuto partition","logic":"Use the last element as pivot; one pointer tracks the boundary of smaller elements. The easiest partition to write correctly.","code":"void quickSort(int[] a, int lo, int hi) {\n    if (lo >= hi) return;\n    int pivot = a[hi], i = lo;\n    for (int j = lo; j < hi; j++)\n        if (a[j] < pivot) swap(a, i++, j);\n    swap(a, i, hi);\n    quickSort(a, lo, i - 1);\n    quickSort(a, i + 1, hi);\n}\nvoid swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }","time":"O(n log n) average, O(n²) worst","space":"O(log n)","optimal":false},{"name":"Hoare partition","logic":"Two pointers move toward each other from both ends, swapping out-of-place pairs. Fewer swaps than Lomuto and the classic efficient form.","code":"void quickSort(int[] a, int lo, int hi) {\n    if (lo >= hi) return;\n    int pivot = a[lo], i = lo - 1, j = hi + 1;\n    while (true) {\n        do { i++; } while (a[i] < pivot);\n        do { j--; } while (a[j] > pivot);\n        if (i >= j) break;\n        swap(a, i, j);\n    }\n    quickSort(a, lo, j);\n    quickSort(a, j + 1, hi);\n}\nvoid swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }","time":"O(n log n) average, O(n²) worst","space":"O(log n)","optimal":true},{"name":"3-way partition (duplicates)","logic":"Split into less-than, equal, and greater-than pivot groups, and only recurse on the outer two. With many duplicates this beats both schemes.","code":"void quickSort(int[] a, int lo, int hi) {\n    if (lo >= hi) return;\n    int pivot = a[lo], lt = lo, i = lo + 1, gt = hi;\n    while (i <= gt) {\n        if (a[i] < pivot) swap(a, lt++, i++);\n        else if (a[i] > pivot) swap(a, i, gt--);\n        else i++;\n    }\n    quickSort(a, lo, lt - 1);\n    quickSort(a, gt + 1, hi);\n}\nvoid swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }","time":"O(n log n) average, O(n) all-equal","space":"O(log n)","optimal":false}]},{"name":"Merge Sort","category":"Sorting","aliases":["merge sort","mergesort","merge sort algorithm","merge-sort","मर्ज सॉर्ट","మెర్జ్ సార్ట్","மெர்ஜ் சார்ட்","ಮರ್ಜ್ ಸಾರ್ಟ್","മെർജ് സോർട്ട്"],"key_logic":"Split the array in half until single elements, then merge the sorted halves back together. Always O(n log n) — no bad pivot case.","approaches":[{"name":"Top-down recursive","logic":"Recursively sort each half, then merge with a temporary array. The standard, stable, guaranteed-fast version.","code":"void mergeSort(int[] a, int lo, int hi) {\n    if (hi - lo <= 1) return;\n    int mid = (lo + hi) / 2;\n    mergeSort(a, lo, mid);\n    mergeSort(a, mid, hi);\n    int[] tmp = new int[hi - lo];\n    int i = lo, j = mid, k = 0;\n    while (i < mid && j < hi)\n        tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];\n    while (i < mid) tmp[k++] = a[i++];\n    while (j < hi) tmp[k++] = a[j++];\n    System.arraycopy(tmp, 0, a, lo, tmp.length);\n}","time":"O(n log n)","space":"O(n)","optimal":true},{"name":"Bottom-up iterative","logic":"Merge runs of size 1, then 2, then 4, doubling each pass. Same merges, no recursion at all.","code":"void mergeSort(int[] a) {\n    int n = a.length;\n    int[] tmp = new int[n];\n    for (int width = 1; width < n; width *= 2)\n        for (int lo = 0; lo < n; lo += 2 * width) {\n            int mid = Math.min(lo + width, n);\n            int hi = Math.min(lo + 2 * width, n);\n            int i = lo, j = mid, k = lo;\n            while (i < mid && j < hi)\n                tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];\n            while (i < mid) tmp[k++] = a[i++];\n            while (j < hi) tmp[k++] = a[j++];\n            System.arraycopy(tmp, lo, a, lo, hi - lo);\n        }\n}","time":"O(n log n)","space":"O(n)","optimal":false},{"name":"In-place merge","logic":"Merge without a temporary array by rotating/shifting elements. Constant space, but the merge step gets much slower and the code far trickier — rarely worth it.","code":"// Sketch: merge two sorted halves in place by insertion.\n// Each out-of-order element is shifted right into place.\nvoid mergeInPlace(int[] a, int lo, int mid, int hi) {\n    int i = lo, j = mid;\n    while (i < j && j < hi) {\n        if (a[i] <= a[j]) { i++; continue; }\n        int value = a[j];\n        System.arraycopy(a, i, a, i + 1, j - i);\n        a[i] = value;\n        i++; j++;\n    }\n}","time":"O(n log n) with slow merges","space":"O(1)","optimal":false}]},{"name":"Kth Largest Element","category":"Heap","aliases":["kth largest","kth largest element","k largest","find kth largest","kth smallest","kth largest element in array"],"key_logic":"You only need the top k, not a full sort. A heap of size k keeps exactly the candidates that can still win.","approaches":[{"name":"Sort","logic":"Sort everything and pick index n−k. The simplest answer, and the baseline every other approach must beat.","code":"int findKthLargest(int[] nums, int k) {\n    Arrays.sort(nums);\n    return nums[nums.length - k];\n}","time":"O(n log n)","space":"O(log n)","optimal":false},{"name":"Min-heap of size k","logic":"Keep a min-heap of the k largest seen so far; its top is the kth largest. Each element costs one heap operation of size k, not n.","code":"int findKthLargest(int[] nums, int k) {\n    PriorityQueue<Integer> heap = new PriorityQueue<>();\n    for (int n : nums) {\n        heap.add(n);\n        if (heap.size() > k) heap.remove();\n    }\n    return heap.peek();\n}","time":"O(n log k)","space":"O(k)","optimal":true},{"name":"Quickselect","logic":"Partition like quicksort, but recurse into only the side containing rank k. Average linear time; worst case quadratic without a good pivot.","code":"int findKthLargest(int[] nums, int k) {\n    int target = nums.length - k, lo = 0, hi = nums.length - 1;\n    while (lo <= hi) {\n        int p = partition(nums, lo, hi);\n        if (p == target) return nums[p];\n        if (p < target) lo = p + 1; else hi = p - 1;\n    }\n    return -1;\n}\nint partition(int[] a, int lo, int hi) {\n    int pivot = a[hi], i = lo;\n    for (int j = lo; j < hi; j++)\n        if (a[j] < pivot) { int t = a[i]; a[i] = a[j]; a[j] = t; i++; }\n    int t = a[i]; a[i] = a[hi]; a[hi] = t;\n    return i;\n}","time":"O(n) average, O(n²) worst","space":"O(1)","optimal":false}]},{"name":"Top K Frequent Elements","category":"Heap","aliases":["top k frequent","top k frequent elements","k most frequent","most frequent elements","most frequent","k frequent","frequent elements","top frequent"],"key_logic":"Count frequencies first; the ranking step decides the complexity. Bucket sort by frequency is the linear-time trick.","approaches":[{"name":"Sort by frequency","logic":"Count with a map, sort the distinct elements by count, take the top k. Simple, dominated by the sort.","code":"int[] topKFrequent(int[] nums, int k) {\n    Map<Integer, Integer> freq = new HashMap<>();\n    for (int n : nums) freq.put(n, freq.getOrDefault(n, 0) + 1);\n    List<Integer> keys = new ArrayList<>(freq.keySet());\n    keys.sort((a, b) -> freq.get(b) - freq.get(a));\n    int[] ans = new int[k];\n    for (int i = 0; i < k; i++) ans[i] = keys.get(i);\n    return ans;\n}","time":"O(n log n)","space":"O(n)","optimal":false},{"name":"Min-heap of size k","logic":"Keep a heap of the k most frequent entries seen so far, ordered by count. Each distinct element costs one heap step of size k.","code":"int[] topKFrequent(int[] nums, int k) {\n    Map<Integer, Integer> freq = new HashMap<>();\n    for (int n : nums) freq.put(n, freq.getOrDefault(n, 0) + 1);\n    PriorityQueue<Integer> heap =\n        new PriorityQueue<>((a, b) -> freq.get(a) - freq.get(b));\n    for (int key : freq.keySet()) {\n        heap.add(key);\n        if (heap.size() > k) heap.remove();\n    }\n    int[] ans = new int[k];\n    for (int i = k - 1; i >= 0; i--) ans[i] = heap.remove();\n    return ans;\n}","time":"O(n log k)","space":"O(n)","optimal":false},{"name":"Bucket sort by frequency","logic":"Frequencies range from 1 to n, so bucket elements by their count and read the buckets from the top down. No comparisons at all.","code":"int[] topKFrequent(int[] nums, int k) {\n    Map<Integer, Integer> freq = new HashMap<>();\n    for (int n : nums) freq.put(n, freq.getOrDefault(n, 0) + 1);\n    List<Integer>[] buckets = new List[nums.length + 1];\n    for (int key : freq.keySet()) {\n        int f = freq.get(key);\n        if (buckets[f] == null) buckets[f] = new ArrayList<>();\n        buckets[f].add(key);\n    }\n    int[] ans = new int[k];\n    int w = 0;\n    for (int f = buckets.length - 1; f >= 0 && w < k; f--)\n        if (buckets[f] != null)\n            for (int key : buckets[f]) ans[w++] = key;\n    return ans;\n}","time":"O(n)","space":"O(n)","optimal":true}]},{"name":"Prime Number Check","category":"Math & Number Theory","aliases":["prime","prime number","prime check","check prime","is prime","isprime","primality","sieve","prime number check","abhaajya","abhajya","अभाज्य","ప్రధాన సంఖ్య","பகா எண்","ಅವಿಭಾಜ್ಯ","അഭാജ്യ"],"key_logic":"A prime has no divisors except 1 and itself. If n has a divisor larger than √n, it must also have one smaller than √n — so checking up to √n is enough.","approaches":[{"name":"Trial division to n−1","logic":"Try every divisor from 2 to n−1. The definition written as code — correct, and the slowest possible way.","code":"boolean isPrime(int n) {\n    if (n <= 1) return false;\n    for (int i = 2; i < n; i++)\n        if (n % i == 0) return false;\n    return true;\n}","time":"O(n)","space":"O(1)","optimal":false},{"name":"Trial division to √n","logic":"Only check divisors up to the square root: any factor above √n pairs with one below it, so nothing is missed. The single biggest speedup.","code":"boolean isPrime(int n) {\n    if (n <= 1) return false;\n    for (int i = 2; i * i <= n; i++)\n        if (n % i == 0) return false;\n    return true;\n}","time":"O(√n)","space":"O(1)","optimal":false},{"name":"6k ± 1 optimized","logic":"Skip all multiples of 2 and 3: every prime above 3 sits next to a multiple of 6. Checks only 6k−1 and 6k+1 candidates — about 3× fewer divisions than plain √n trial division.","code":"boolean isPrime(int n) {\n    if (n <= 1) return false;\n    if (n <= 3) return true;\n    if (n % 2 == 0 || n % 3 == 0) return false;\n    for (int i = 5; i * i <= n; i += 6)\n        if (n % i == 0 || n % (i + 2) == 0)\n            return false;\n    return true;\n}","time":"O(√n)","space":"O(1)","optimal":true},{"name":"Sieve of Eratosthenes","logic":"A different job: find ALL primes up to n at once. Mark multiples of each prime as composite, starting from its square. Best when many numbers must be checked, wasteful for a single check.","code":"// All primes up to n — not a single-number check.\nboolean[] sieve(int n) {\n    boolean[] isPrime = new boolean[n + 1];\n    Arrays.fill(isPrime, true);\n    isPrime[0] = isPrime[1] = false;\n    for (int i = 2; i * i <= n; i++)\n        if (isPrime[i])\n            for (int j = i * i; j <= n; j += i)\n                isPrime[j] = false;\n    return isPrime;\n}","time":"O(n log log n)","space":"O(n)","optimal":false}]}]};
